        production_term_count=length(production_terms),numeric_only=true)
end

Base.@noinline Base.@nospecializeinfer function _ccp_q1_lcfs_near_cut_G_replay_numeric_capture(capture;
        endpoint_epsilon=1e-3,endpoint_u_panels=4,positive_r_panels=4,
        positive_u_panels=4,terms=16,precision_bits=256,max_interval_ops=2_000_000,adaptive_refinement=:none)
    Base.@nospecialize capture
    capture isa NamedTuple && hasproperty(capture,:payload) &&
        capture.payload.schema===:near_cut_q8_numeric_replay_v1 &&
        capture.payload.numeric_only===true || return (status=:typed_absent,reason=:invalid_numeric_replay_capture)
    p=capture.payload
    terms_dict=Dict{Any,Any}(t.coverage_id=>(E=t.E,G=t.G) for t in p.production_terms)
    _ccp_q1_lcfs_near_cut_G_all_inventory_consumer_interface(p.prep,terms_dict;
        production_E=p.production_E,production_G=p.production_G,
        coordinate_direction=p.coordinate_direction,endpoint_epsilon=endpoint_epsilon,
        endpoint_u_panels=endpoint_u_panels,positive_r_panels=positive_r_panels,
        positive_u_panels=positive_u_panels,terms=terms,precision_bits=precision_bits,
        max_interval_ops=max_interval_ops,max_kernel_calls=p.max_kernel_calls,
        kernel_calls_ref=Ref(p.kernel_calls_before_join),adaptive_refinement=adaptive_refinement)
end

# The geometry Jacobian is ordered by its native-psi DOF map, not by the
# complete coupled state. Preserve the producer's scalar accumulation order.
Base.@noinline Base.@nospecializeinfer function _ccp_full_native_coordinate_direction(geometry,direction)
    Base.@nospecialize geometry direction
    ids=Int.(collect(geometry.psi_global_dof_ids))
    J=geometry.coordinate_jacobian
    size(J)==(128,length(ids)) && length(unique(ids))==length(ids) &&
        all(i->1<=i<=length(direction),ids) && all(isfinite,J) && all(isfinite,direction) ||
        throw(ArgumentError("LCFS coordinate Jacobian/native-psi/full-state direction mapping is invalid"))
    out=zeros(Float64,128)
    for a in 1:64,k in eachindex(ids)
        coefficient=direction[ids[k]]
        out[2a-1]+=J[2a-1,k]*coefficient
        out[2a]+=J[2a,k]*coefficient
    end
    out
end

Base.@noinline Base.@nospecializeinfer function _ccp_q1_lcfs_near_cut_G_all_inventory_consumer_interface(prep,production_terms;
        production_E=nothing,production_G=nothing,
        coordinate_direction=nothing,
