                    edcurR=_ccp_q1_lcfs_signed_interval_scale(Eint.Br,prep.dcurrent[col];precision_bits=precision_bits)
                    edcurZ=_ccp_q1_lcfs_signed_interval_scale(Eint.Bz,prep.dcurrent[col];precision_bits=precision_bits)
                    leaf_E_current=(interval_add(leaf_E_current[1],ecurR),interval_add(leaf_E_current[2],ecurZ))
