                exact_E_dcurrent=(interval_add(exact_E_dcurrent[1],bounds_E_dcurrent[1]),
                    interval_add(exact_E_dcurrent[2],bounds_E_dcurrent[2]))
                # Bound the actual Float64 matrix-vector dots against exact sums
                # of their captured binary64 operands. This measures the BLAS
                # result directly, including its actual reduction order.
                for k in 1:2
                    e_exact=sum(BigFloat(live.E[k,j])*BigFloat(prep.dcurrent[j]) for j in eachindex(prep.dcurrent))
                    g_exact=sum(BigFloat(live.G[k,j])*BigFloat(coordinate_direction[j]) for j in eachindex(coordinate_direction))
                    dot_roundoff=ntuple(j->setrounding(BigFloat,RoundUp) do
                        dot_roundoff[j]+(j==k ? abs(BigFloat(edot[k])-e_exact)+abs(BigFloat(gdot[k])-g_exact)+abs(BigFloat(local_q8[k])-BigFloat(edot[k])-BigFloat(gdot[k])) : BigFloat(0))
