    (status=:evaluated_near_cut_G_all_inventory_partial,
        target_index=prep.target_index,state_direction_scope=:ray19_psi_dof_41032,
        inventory_scope=:all_prepared_near_target_cut_cells_and_their_Duffy_triangles,
        exact_near_cut_G_directional_integral_interval_RZ=exact,
        exact_near_cut_E_dot_current_integral_interval_RZ=exact_E_current,
        exact_near_cut_E_dot_dcurrent_integral_interval_RZ=exact_E_dcurrent,
        production_E_dot_current_RZ=Tuple(aggregate_E_current),
        production_E_dot_dcurrent_RZ=Tuple(aggregate_E_dot),
        production_G_dot_dX_RZ=Tuple(aggregate_G_dot),
        near_cut_production_Q8_directional_RZ=Tuple(aggregate_Q8),
        production_Q8_terms_recomputed_from_captured_triangle_matrices=true,
        aggregate_E_dot_of_captured_matrix_exact_interval_RZ=e_dot_exact,
        aggregate_E_current_of_captured_matrix_exact_interval_RZ=e_current_exact,
        aggregate_G_dot_exact_interval_RZ=g_dot_exact,
        aggregate_G_dot_to_exact_leaf_sum_distance_upper_RZ=aggregate_g_distance,
        aggregate_E_dot_current_to_exact_leaf_basis_sum_distance_upper_RZ=aggregate_e_current_distance,
        aggregate_E_dot_dcurrent_to_exact_leaf_basis_sum_distance_upper_RZ=aggregate_e_distance,
        consumer_Q8_to_exact_E_dot_plus_G_integral_interval_distance_upper_RZ=mixed_distance,
        combined_near_cut_Q8_tolerance_policy=:strict_relative_bound_per_E_G_and_Q8,
        near_cut_exact_relative_limit=exact_relative_limit,
        near_cut_E_dot_current_integral_absolute_error_norm_upper=e_current_error_norm,
        near_cut_E_dot_dcurrent_integral_absolute_error_norm_upper=e_dcurrent_error_norm,
        near_cut_G_integral_absolute_error_norm_upper=g_error_norm,
        near_cut_combined_Q8_absolute_error_norm_upper=mixed_error_norm,
        near_cut_E_dot_current_approximation_norm_lower=e_current_approx_norm,
        near_cut_E_dot_dcurrent_approximation_norm_lower=e_dcurrent_approx_norm,
        near_cut_G_approximation_norm_lower=g_approx_norm,
        near_cut_combined_Q8_approximation_norm_lower=mixed_approx_norm,
        near_cut_E_dot_current_relative_integral_gate_passed=e_current_gate,
        near_cut_E_dot_dcurrent_relative_integral_gate_passed=e_dcurrent_gate,
        near_cut_G_relative_integral_gate_passed=g_gate,
        near_cut_combined_Q8_relative_integral_gate_passed=mixed_gate,
        near_cut_integral_gate_passed=near_cut_integral_gate_passed,
        exact_sum_of_captured_production_Q8_terms_RZ=float_q8_exact,
        float64_sum_of_captured_production_Q8_terms_RZ=float_q8,
        q8_matrix_dot_roundoff_sum_upper_RZ=dot_roundoff,
        q8_float64_triangle_reduction_roundoff_upper_RZ=reduction_roundoff,
        per_triangle_Q8_to_exact_E_plus_G_interval_distance_sum_upper_RZ=error_upper,
        coverage_ids=Tuple(r.coverage_id for r in records),records=Tuple(records),
        near_cut_active_basis_terms=total,covered_near_cut_basis_terms=covered,
        covered_star_leaf_basis_terms=covered_star,covered_nonstar_basis_terms=covered_nonstar,
        uncovered_nonstar_basis_terms=nonstar-covered_nonstar,
        uncovered_star_basis_terms=(expected-nonstar)-covered_star,
        unconsumed_production_term_count=length(production_terms)-length(records),
        outside_near_cut_cell_count=outside_near_cells,
        uncovered_scope=:every_non_near_preparation_cell,
        interval_operations=ops[],max_interval_operations=max_interval_ops,
        kernel_calls=calls[],max_kernel_calls=max_kernel_calls,
        production_directional_formula=:triangle_add_times_dcurrent_plus_triangle_G_times_coordinate_direction,
        geometry_rounding_to_stored_polygon_error=:typed_absent,
        nonstar_near_cut_G_error_bound=:included_in_all_leaf_exact_G_interval,
        full_response_G_error_bound=:typed_absent,
        captured_E_dot_dcurrent_roundoff_upper_RZ=ntuple(k->setrounding(BigFloat,RoundUp) do
            max(abs(BigFloat(aggregate_E_dot[k])-e_dot_exact[k][1]),
                abs(BigFloat(aggregate_E_dot[k])-e_dot_exact[k][2]))
