        captured_E_dot_current_roundoff_upper_RZ=ntuple(k->setrounding(BigFloat,RoundUp) do
            max(abs(BigFloat(aggregate_E_current[k])-e_current_exact[k][1]),
                abs(BigFloat(aggregate_E_current[k])-e_current_exact[k][2]))
        end,2),
        captured_G_dot_roundoff_upper_RZ=ntuple(k->setrounding(BigFloat,RoundUp) do
            max(abs(BigFloat(aggregate_G_dot[k])-g_dot_exact[k][1]),
                abs(BigFloat(aggregate_G_dot[k])-g_dot_exact[k][2]))
        end,2),
        consumer_E_dot_dcurrent_plus_G_dot_coordinate_direction_roundoff=:full_signed_basis_E_and_G_interval_compared_to_actual_aggregated_float64_matrices,
        consumer_mixed_E_error_scope=:all_near_cut_leaf_Q1_basis_primal_E_integrals_weighted_by_signed_dcurrent,
        full_near_cut_E_integration_error_bound=aggregate_e_current_distance,
        near_cut_E_dot_dcurrent_integration_error_bound=aggregate_e_distance,
        E_and_G_enclosure_leaf_inventory=:same_actual_near_cut_triangle_and_active_Q1_basis_ids,
        E_and_G_enclosures_share_interval_operation_counter=true,
        interval_kernel_calls_added=0,
        kernel_call_budget_scope=:original_production_shared_40M_counter,
        numeric_replay_capture=numeric_replay_capture,
        numeric_replay_capture_bytes=numeric_replay_capture.estimated_bytes,
        numeric_replay_capture_schema=:near_cut_q8_numeric_replay_v1,
        numeric_replay_capture_excludes_callbacks_components_and_sources=true,
        consumer_status=near_cut_integral_gate_passed ? :near_cut_strict_integral_bound_passed : :typed_absent,
        near_cut_integral_gate_reason=near_cut_integral_gate_passed ? :within_original_strict_relative_bound :
            :near_cut_strict_relative_bound_unresolved,G=:typed_absent,
        global_closure=false,physical_validation=false)
end

Base.@noinline Base.@nospecializeinfer function _ccp_q1_lcfs_red_chart_co_moving_response(prep;order=8,max_kernel_calls=40_000_000,
        local_E_join=nothing,local_G_join=false,near_cut_only=false,max_interval_ops=2_000_000)
    Base.@nospecialize prep
    local_G_join isa Bool || throw(ArgumentError("local G inventory selector must be Bool"))
    near_cut_only isa Bool || throw(ArgumentError("near/cut-only response selector must be Bool"))
