        max_kernel_calls isa Integer && !(max_kernel_calls isa Bool) && max_kernel_calls>0 &&
        max_interval_ops isa Integer && !(max_interval_ops isa Bool) && max_interval_ops>0 &&
        max_interval_ops<=(local_G_join ? 8_000_000 : 2_000_000) ||
        throw(ArgumentError("red-chart co-moving response needs prepared geometry and bounded budgets"))
    prep.refined_triangle_count>0 && !isempty(prep.near_target_cell_ids) ||
        return (status=:typed_absent,reason=:qualified_two_level_near_parent_chart_missing,
            consumer_status=:typed_absent,kernel_calls=0)
    domain=prep.domain;state=prep.state;target_index=prep.target_index
