    production_near_cut_E=zeros(Float64,2,ncore)
    production_near_cut_G=zeros(Float64,2,128)
    if local_E_join!==nothing
        selector_check=_ccp_q1_lcfs_validate_local_E_join_selector(prep,local_E_join;
            order=order,max_kernel_calls=max_kernel_calls)
        selector_check.status===:validated_local_E_join_selector ||
            return merge(selector_check,(consumer_status=:typed_absent,
                full_response_error_bound=:typed_absent,G_error_bound=:typed_absent,kernel_calls=0))
    end
    for cell_partition in prep.quadrature_partition
        # Partial response only: saved far E/G is joined separately by its consumer.
        near_cut_only && !cell_partition.near_target && continue
        cell=prep.prepared_cells[cell_partition.cell_index]
        bounds=cell.bounds;columns=cell.columns
        complete_plasma_only=!isempty(cell.pieces) && all(piece->hasproperty(piece.lineage,:source) &&
            piece.lineage.source===:plasma_only_native_cell,cell.pieces)
        if complete_plasma_only && !(cell.native_cell in prep.near_target_cell_ids)
