                triangle_G=capture_near_cut_G ? zeros(Float64,2,128) : G
                add=_ccp_q1_duffy_triangle_response(prep.target,p0,p1,p2,bounds,columns,ncore,
                    domain.law.mu0_N_per_A2,order,nodes,weights,calls,max_kernel_calls;
                    target_jacobian=targetJ,vertex_jacobians=(D0,D1,D2),
                    current_density=current,geometry_accumulator=triangle_G,geometry_row=1,
                    affine_parent_points=triangle.affine_parent_points,
                    affine_parent_jacobians=parent_jacobians,
                    affine_vertex_weights=triangle.affine_vertex_weights,
                    affine_det_ratio=triangle.affine_det_ratio)
                add isa NamedTuple && get(add,:status,:none)===:typed_absent &&
                    return merge(add,(kernel_calls=calls[],partial_response_discarded=true,
                        consumer_status=:typed_absent))
                add===nothing && return (status=:typed_absent,reason=:red_chart_kernel_budget_exceeded,
                    kernel_calls=calls[],partial_response_discarded=true,consumer_status=:typed_absent)
                if capture_near_cut_G
                    coverage_id=(target_index,cell.native_cell,piece_partition.piece_index,
                        triangle.triangle_index,triangle.child_path)
                    haskey(production_near_cut_G_terms,coverage_id) && return (status=:typed_absent,
                        reason=:near_cut_G_duplicate_live_triangle_term,coverage_id=coverage_id,
                        partial_response_discarded=true,consumer_status=:typed_absent,kernel_calls=calls[])
                    production_near_cut_G_terms[coverage_id]=(E=add,G=triangle_G)
                    G .+= triangle_G
                end
                if local_E_join!==nothing &&
                        cell.native_cell==local_E_join.source_cell_native_ij &&
                        piece_partition.piece_index==local_E_join.piece_index &&
                        triangle.triangle_index==local_E_join.triangle_index &&
                        triangle.child_path==local_E_join.child_path
                    local_join_id=(target_index,cell.native_cell,piece_partition.piece_index,
                        triangle.triangle_index,triangle.child_path,local_E_join.basis_index)
                    local_join_record===:typed_absent || return (status=:typed_absent,
                        reason=:local_E_join_selected_duplicate_coverage_id,coverage_id=local_join_id,
                        consumer_status=:typed_absent,full_response_error_bound=:typed_absent,
                        G_error_bound=:typed_absent,kernel_calls=calls[],
                        local_partition_active_basis_terms=local_join_total_terms,
                        local_partition_uncovered_nonstar_terms=local_join_nonstar_terms)
                    basis=local_E_join.basis_index;col=columns[basis]
                    triangle.singular_target_star && col>0 &&
                        triangle.affine_parent_points isa Tuple && triangle.affine_vertex_weights isa Tuple &&
                        triangle.affine_det_ratio===1/16 || return (status=:typed_absent,
                            reason=:local_E_join_selected_leaf_or_basis_not_qualified,
                            coverage_id=local_join_id,active_basis_column=col,
                            consumer_status=:typed_absent,full_response_error_bound=:typed_absent,
                            G_error_bound=:typed_absent,kernel_calls=calls[],
                            local_partition_active_basis_terms=local_join_total_terms,
                            local_partition_uncovered_nonstar_terms=local_join_nonstar_terms)
