                        affine_det_ratio=triangle.affine_det_ratio,basis_index=basis,
                        max_interval_ops=local_E_join.max_interval_ops,max_kernel_calls=max_kernel_calls,
                        interval_ops=local_E_join.interval_operations,kernel_calls=calls,
