                        active_basis_column=col,native_source_id=core_ids[col],
                        live_production_Q_RZ=live_Q,whole_star_production_Q_RZ=helper_Q,
                        live_Q_matches_whole_star_Q_bitwise=true,
                        exact_integral_enclosure_RZ=cert.exact_integral_enclosure_RZ,
                        production_Q_to_integral_distance_upper_RZ=distance,
                        abs_source_current_A_per_m2=absJ,
                        current_weighted_local_field_error_upper_T_RZ=weighted_distance,
                        interval_width_RZ=cert.exact_integral_width_RZ,
                        interval_operations=local_E_join.interval_operations[],
                        max_interval_operations=local_E_join.max_interval_ops,
                        kernel_calls=calls[],max_kernel_calls=max_kernel_calls,
                        integration_domain=cert.integration_domain,
                        geometry_rounding_to_stored_polygon_error=cert.geometry_rounding_to_stored_polygon_error,
                        local_basis_term_coverage=:one_selected_triangle_basis_only,
                        full_response_error_bound=:typed_absent,G=:typed_absent,
