        E_error_bound_T_per_A_m2=E_error_bound,
        E_error_bound_scope=near_cut_only ? :not_applicable_to_near_cut_only_partial : :complete_native_plasma_only_far_cells_only,
        full_response_error_bound=:typed_absent_due_to_near_and_cut_Duffy_terms,
