        clipping_topology_signature=prep.clipping_signature,near_target_cell_ids=prep.near_target_cell_ids,
        refined_triangle_count=prep.refined_triangle_count,kernel_calls=calls[],quadrature_order=order,
        floating_point_error_certified=false,physical_validation=false,consumer_status=:typed_absent)
