        local_G_interval=_ccp_q1_lcfs_near_cut_G_all_inventory_consumer_interface(prep,
            production_near_cut_G_terms;production_E=production_near_cut_E,
            production_G=production_near_cut_G,max_interval_ops=max_interval_ops,
            max_kernel_calls=max_kernel_calls,kernel_calls_ref=calls)
        result=merge(result,(local_G_join_response=local_G_interval,
            local_G_join_status=local_G_interval.status,
            local_G_join_G_error_bound=get(local_G_interval,:aggregate_G_dot_to_exact_leaf_sum_distance_upper_RZ,:typed_absent),
            local_G_join_E_error_bound=get(local_G_interval,:aggregate_E_dot_current_to_exact_leaf_basis_sum_distance_upper_RZ,:typed_absent),
            local_G_join_E_dcurrent_error_bound=get(local_G_interval,:aggregate_E_dot_dcurrent_to_exact_leaf_basis_sum_distance_upper_RZ,:typed_absent),
            local_G_join_E_plus_G_error_bound=get(local_G_interval,:consumer_Q8_to_exact_E_dot_plus_G_integral_interval_distance_upper_RZ,:typed_absent),
            local_G_join_per_triangle_distance_sum_upper_RZ=get(local_G_interval,:per_triangle_Q8_to_exact_E_plus_G_interval_distance_sum_upper_RZ,:typed_absent)))
    end
