    local_join_record===:typed_absent && return (status=:typed_absent,
        reason=:local_E_join_expected_coverage_id_not_found,kernel_calls=calls[],
        interval_operations=local_E_join.interval_operations[],
        expected_coverage_id=(target_index,local_E_join.source_cell_native_ij,local_E_join.piece_index,
            local_E_join.triangle_index,local_E_join.child_path,local_E_join.basis_index),
        local_partition_active_basis_terms=local_join_total_terms,
        local_partition_uncovered_nonstar_terms=local_join_nonstar_terms,
        local_partition_uncovered_star_terms=local_join_star_uncovered_terms,
        local_partition_uncovered_total_terms=local_join_total_terms,
        local_partition_uncovered_total_status=:typed_absent_nonstar_cut_and_unselected_star_terms,
        full_response_error_bound=:typed_absent,G_error_bound=:typed_absent,
        partial_response_discarded=true,consumer_status=:typed_absent)
