        B_exterior_status=:typed_absent,B_exterior_jacobian_status=:typed_absent,
        stress_jump_status=:typed_absent,
        reason=:moving_LCFS_exterior_B_out_and_stress_jump_unavailable,
        solver_rows_added=0,global_topology_closed=false,
        missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES)
    return merge(trace_identity,(status=:evaluated_composite_dynamic_LCFS_offgrid_profile_and_curl_Bphi,
        reason=:composite_exact_PF_plasma_spline_profile_current_trace,
        dynamic_geometry=geometry,source_state=state,field_model_id=native_field_model_id,
        pressure_status=:evaluated_composite_profile_pressure,
        current_status=:evaluated_composite_profile_curl_Bphi,
        current_normal_trace=:evaluated_dynamic_geometry_holdout,
        canonical_state_current_normal_A_per_m2=canonical_current.Jn_A_per_m2,
        canonical_state_current_normal_diagnostic=canonical_current.normal_current_diagnostic,
        canonical_state_current_representation=:shared_profile_P_total_psi_plus_tensor_spline_D_over_R,
        canonical_state_current_F_residual_T_m=copy(canonical_current.native_lift_defect_T_m),
        canonical_state_current_F_residual_source=:native_lift_defect_not_original_regional_row_evaluation,
        legacy_Q1_regional_F_defect_role=:historical_comparison_only_not_evaluated_by_production_consumer,
        fields=fields,field_order=(:profile_pressure_Pa,:Bphi_T,:JR_A_per_m2,:JZ_A_per_m2,:Jn_A_per_m2),
        residual=residual,jacobian=jac,
        residual_order=(:pressure_minus_boundary,:stable_shared_lifted_F_B_minus_fvac,:actual_lifted_curl_Jn),
        active_F_residual_evaluator=:shared_Pcentered_plus_tensor_spline_defect,
        active_F_residual_jacobian_source=:same_shared_lifted_F_state_jacobian,
        F_B_centering_roundoff_T_m=copy(canonical_current.F_B_centering_roundoff_T_m),
        pressure_jacobian=pressure_jacobian,Bphi_residual_jacobian=current_jacobian,
        current_normal_jacobian=normal_current_jacobian,
        plasma_side_interface_inputs=plasma_side_interface_inputs,
        jacobian_columns=:full_existing_state_columns_for_pressure_and_shared_lifted_F_current,
        dynamic_geometry_jacobian_columns=:psi_native_dofs_only,
        q_normalized_to=:dynamic_profile_axis_boundary_flux,
        profile_helper_coordinate=:Q_one_minus_shape_q,
        profile_shape_q_convention=:(psi_minus_B_over_A_minus_B),
        profile_endpoint_values=(axis=profile_span.axis,boundary=profile_span.boundary,delta=D),
        endpoint_definition_residual=(profile_span.axis-geometry.psi_axis_Wb_per_rad,
            profile_span.boundary-geometry.psi_boundary_Wb_per_rad),
        composite_surface_psi_Wb_per_rad=Tuple(surface_psi),
        composite_surface_gradient_RZ_Wb_per_rad_m=Tuple(zip(surface_gR,surface_gZ)),
        composite_surface_hessian_RZ_Wb_per_rad_m2=Tuple(zip(surface_hessian[1,:],
            surface_hessian[2,:],surface_hessian[3,:])),
        profile_q=Tuple(shape_qvalue),profile_helper_Q=Tuple(qvalue),mask_spline_value=Tuple(mask_value),
        effective_boundary_q=Tuple(effective_boundary_q),
        effective_boundary_helper_Q=Tuple(effective_boundary_helper_Q),
        effective_boundary_q_source=:same_state_dynamic_geometry_psi_boundary_flux,
        profile_q_source=:raw_composite_surface_psi_preserved,
        mask_spline_gradient_RZ_per_m=Tuple(zip(mask_gR,mask_gZ)),
        mask_spline_anchor_check=(max_value_error=source_mask_value_error,
            value_bound=source_mask_value_bound,max_gradient_error=source_mask_gradient_error,
            gradient_bound=source_mask_gradient_bound,
            source_hessian_reference=:not_emitted,
            moved_hessian_method=:analytic_second_derivative_of_reconstructed_source_mask_spline),
        source_mask_provenance=Tuple(s.mask_matches_refreshed_current_support for s in source),
        source_fd_anchors_preserved_separately=true,
        source_mask_rebuild_gate=:native_core_mask_inventory_unchanged_required,
        fixed_geometry=false,fixed_source_mask=true,source_fields_reused=false,
        current_scope=:shared_lifted_F_curl_for_active_current_rows,
        legacy_profile_point_diagnostic=(status=:evaluated_legacy_composite_profile_point_not_active,
            fields=copy(legacy_point_values),F_residual=copy(legacy_point_F_residual),
            raw_normal_current_projection_A_per_m2=Tuple(raw_normal_projection),
            levelset_normal_parallel_flux_cross_Wb_per_rad_m=Tuple(normal_parallel_flux_cross),
            normal_current_identity_error_A_per_m2=Tuple(normal_current_identity_error),
            point_partials=copy(partials),
            pressure_partial_role=:reused_for_active_pressure_rows,
            current_partial_role=:legacy_diagnostic_only,
            row_role=:legacy_current_values_not_active_solver_rows),
        normal_scope=:moving_composite_LCFS_normal_no_phi_component,
        solver_rows_added=0,extra_solver_rows=0,global_topology_closed=false,
        physical_validation=false,missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES))

end

function _ccp_native_continuous_Jphi_core_v1(psi_plasma_mat,gs_operator,Raxis,nz,mu0,core_ids,pf_Jphi_core)
    size(psi_plasma_mat)==(length(Raxis),nz) && length(core_ids)==length(pf_Jphi_core) ||
        throw(DimensionMismatch("continuous native current geometry/core shape mismatch"))
    psi_delta_star_mat=gs_operator.H_RR*psi_plasma_mat-
        gs_operator.radial_first*psi_plasma_mat+
        psi_plasma_mat*transpose(gs_operator.H_ZZ)
    psi_plasma_delta_star=vec(permutedims(psi_delta_star_mat))
    native_R=repeat(Raxis,inner=nz)
    native_Jphi_plasma=-psi_plasma_delta_star./(mu0.*native_R)
    native_Jphi_plasma[core_ids].+pf_Jphi_core
end

function _ccp_native_jphi_operator_budget_kernel_v1(;Raxis,Zaxis,Dr=nothing,Dz=nothing,
        psi_plasma_mat,psi_interp,pf_native_Br_T,pf_native_Bz_T,lcfs_dynamic_geometry_data,
        gs_operator=nothing,gs_source_operator=nothing,core_ids,nz,mu0,native_Jphi=nothing,
        native_field_model_id=nothing,
        profile_law_Jphi,toroidal,accepted_source_Jphi=nothing,area_weight_m2=nothing)
    # Reuse the producer's pure spline and GS4 builders when the saved observer
    # has only the actual axes/derivative maps; no Hagenow response is involved.
    Dr=Dr===nothing ? _ccp_native_spline_derivative(Raxis) : Dr
    Dz=Dz===nothing ? _ccp_native_spline_derivative(Zaxis) : Dz
    gs_source_operator=gs_source_operator===nothing ? _ccp_native_gs4_operator(Raxis,Zaxis) : gs_source_operator
    gs_operator=gs_operator===nothing ? _ccp_native_spline_delta_star_operator(Raxis,Zaxis,Dr,Dz) : gs_operator
    nr=length(Raxis);n=nr*nz;ids=collect(Int,core_ids);nc=length(ids)
    native_Jphi===nothing && native_field_model_id!==:plasma_spline_plus_exact_pf_potential_jet_v1 &&
        throw(ArgumentError("reconstructing native current requires the declared absolute composite field model"))
    length(Zaxis)==nz && (native_Jphi===nothing || length(native_Jphi)==n) && length(profile_law_Jphi)==nc &&
        length(toroidal)==n && size(psi_plasma_mat)==(nr,nz) && length(psi_interp)==n ||
        throw(DimensionMismatch("saved native Jphi budget inputs have inconsistent shape"))
    pf_Br=permutedims(reshape(Float64.(pf_native_Br_T),nz,nr))
    pf_Bz=permutedims(reshape(Float64.(pf_native_Bz_T),nz,nr))
    Rgrid=repeat(reshape(Float64.(Raxis),nr,1),1,nz)
    plasma_Br=-(psi_plasma_mat*transpose(Dz))./Rgrid
    plasma_Bz=(Dr*psi_plasma_mat)./Rgrid
    Jphi_pf_discrete=vec(permutedims((pf_Br*transpose(Dz)-Dr*pf_Bz)./mu0))
    Jphi_plasma_discrete=vec(permutedims((plasma_Br*transpose(Dz)-Dr*plasma_Bz)./mu0))
    H_RR=_ccp_native_spline_point_hessian_weights(Raxis,Dr,Raxis)
    H_ZZ=_ccp_native_spline_point_hessian_weights(Zaxis,Dz,Zaxis)
    psi_plasma_R=Dr*psi_plasma_mat
    psi_RR=H_RR*psi_plasma_mat
    psi_RZ=Dr*psi_plasma_mat*transpose(Dz)
    psi_ZZ=psi_plasma_mat*transpose(H_ZZ)
    gs4_row_by_native=Dict(k=>r for (r,k) in enumerate(gs_source_operator.native_ids))
    all(k->haskey(gs4_row_by_native,k),ids) ||
        throw(ArgumentError("core Jphi budget includes a node absent from the GS4 A4h operator"))
    A4h_psi=gs_source_operator.operator*psi_interp
    pf_discrete_core=Jphi_pf_discrete[ids]
    plasma_discrete_core=Jphi_plasma_discrete[ids]
    pf_continuous=Vector{Float64}(undef,nc)
    plasma_continuous=Vector{Float64}(undef,nc)
    gs4_current=Vector{Float64}(undef,nc)
    hessian_core=Matrix{Float64}(undef,3,nc)
    Rcore=Vector{Float64}(undef,nc)
    A4h_core=Vector{Float64}(undef,nc)
    for (q,k) in enumerate(ids)
        i=cld(k,nz);j=mod1(k,nz);radius=Raxis[i]
        hrr=psi_RR[i,j];hrz=psi_RZ[i,j];hzz=psi_ZZ[i,j]
        hessian_core[:,q].=(hrr,hrz,hzz);Rcore[q]=radius
        plasma_continuous[q]=-(hrr-psi_plasma_R[i,j]/radius+hzz)/(mu0*radius)
        pf=_ccp_full_native_exact_pf_jet(lcfs_dynamic_geometry_data,radius,Zaxis[j])
        pf_continuous[q]=-(pf.hessian[1,1]-pf.gradient[1]/radius+pf.hessian[2,2])/(mu0*radius)
        row=gs4_row_by_native[k];A4h_core[q]=A4h_psi[row]
        gs4_current[q]=-A4h_core[q]/(mu0*radius)
    end
    native_core=native_Jphi===nothing ?
        _ccp_native_continuous_Jphi_core_v1(psi_plasma_mat,gs_operator,Raxis,nz,mu0,ids,pf_continuous) :
        native_Jphi[ids]
    state_field=native_core.-pf_discrete_core.-plasma_discrete_core
    pf_drift=pf_discrete_core.-pf_continuous
    plasma_drift=plasma_discrete_core.-plasma_continuous
    gs4_primitive_drift=gs4_current.-(pf_continuous.+plasma_continuous)
    gs4_profile=gs4_current.-profile_law_Jphi
    gs4_residual_current_equivalent=(A4h_core.+mu0.*Rcore.*toroidal[ids])./(mu0.*Rcore)
    native_gs4=native_core.-gs4_current
    native_profile=native_core.-profile_law_Jphi
    stats(a,b)=(rms=sqrt(sum(abs2,a.-b)/length(a)),max=maximum(abs,a.-b))
    if accepted_source_Jphi===nothing
        accepted=(status=:typed_absent,gs4_minus=:typed_absent,profile_minus=:typed_absent,
            sum=:typed_absent,error=:typed_absent,target=:typed_absent)
    else
        accepted=Float64.(accepted_source_Jphi)
        length(accepted)==nc || throw(DimensionMismatch("accepted source Jphi length mismatch"))
        gs4_minus=gs4_current.-accepted
        signed_sum=state_field.+pf_drift.+plasma_drift.-gs4_primitive_drift.+gs4_minus
        target=native_core.-accepted
        closure_error=signed_sum.-target
        all(isfinite,signed_sum) && all(isfinite,closure_error) ||
            throw(ArgumentError("signed native Jphi operator budget became nonfinite"))
        accepted=(status=:present,gs4_minus=gs4_minus,
            profile_minus=profile_law_Jphi.-accepted,sum=signed_sum,error=closure_error,target=target)
    end
    area_status=area_weight_m2===nothing ? :typed_absent :
        (length(area_weight_m2)==nc ? :present : throw(DimensionMismatch("accepted area-weight length mismatch")))
    all(isfinite,hessian_core) && all(isfinite,gs4_residual_current_equivalent) ||
        throw(ArgumentError("signed native Jphi operator budget became nonfinite"))
    (comparison_native_ids=copy(ids),native_Jphi_core_A_per_m2=native_core,
     native_current_source=native_Jphi===nothing ? :same_state_absolute_spline_plus_exact_PF_curl : :supplied_original_native_current,
     pf_discrete=pf_discrete_core,plasma_discrete=plasma_discrete_core,
     pf_continuous=pf_continuous,plasma_continuous=plasma_continuous,gs4_current=gs4_current,
     state_field_reconstruction_residual=state_field,pf_sampled_minus_continuous_jet=pf_drift,
     plasma_spline_nodal_minus_continuous_jet=plasma_drift,
     gs4_operator_minus_continuous_primitive_jet=gs4_primitive_drift,
     gs4_operator_minus_candidate_profile=gs4_profile,
     gs4_residual_current_equivalent=gs4_residual_current_equivalent,
     candidate_profile_minus_accepted_source=accepted.profile_minus,
     gs4_operator_minus_accepted_source=accepted.gs4_minus,
     signed_budget_sum=accepted.sum,budget_closure_error=accepted.error,
     target=accepted.target,hessian_core=hessian_core,
     native_minus_gs4=native_gs4,native_minus_profile=native_profile,gs4_minus_profile=gs4_profile,
     pointwise=(native_minus_gs4=stats(native_core,gs4_current),
         native_minus_profile=stats(native_core,profile_law_Jphi),
         gs4_minus_profile=stats(gs4_current,profile_law_Jphi)),
     accepted_source_status=accepted.status,accepted_area_weight_status=area_status,
     H_RR_map_size=size(H_RR),H_ZZ_map_size=size(H_ZZ),
     A4h_size=size(gs_source_operator.operator),A4h_nnz=nnz(gs_source_operator.operator),
     GS4_operator_native_ids=copy(gs_source_operator.native_ids))
end

function _ccp_full_native_dynamic_composite_lcfs_current_trace(data,state;with_jacobian=true,
        geometry_override=nothing,geometry_cache=nothing,kernel_calls_ref=nothing,
        max_kernel_calls=40_000_000,pf_ring_evaluations_ref=nothing)
    trace_identity=data.trace_identity
    model_id=_ccp_native_geometry_model_id(data.native_field_model_id)
    state_x=Float64.(collect(state))
    geometry=geometry_override===nothing ? _ccp_full_native_dynamic_geometry(
        data.lcfs_dynamic_geometry_data,state_x;model_id=model_id,kernel_calls_ref=kernel_calls_ref,
        max_kernel_calls=max_kernel_calls,pf_ring_evaluations_ref=pf_ring_evaluations_ref) : geometry_override
    geometry.status===:evaluated_dynamic_LCFS_geometry || return merge(trace_identity,
        (status=geometry.status,reason=geometry.reason,dynamic_geometry=geometry,
         pressure_status=:typed_absent,current_status=:typed_absent,
         current_normal_trace=:typed_absent,fields=nothing,residual=nothing,jacobian=nothing,
         fixed_geometry=false,fixed_source_mask=false,source_fields_reused=false,
         global_topology_closed=false))
    active_geometry_cache=geometry_cache===nothing ?
        (domain=data.state_domain,state=state_x,geometry=geometry) : geometry_cache
    active_geometry_cache isa NamedTuple && hasproperty(active_geometry_cache,:domain) &&
        hasproperty(active_geometry_cache,:state) && hasproperty(active_geometry_cache,:geometry) &&
        active_geometry_cache.domain===data.state_domain && active_geometry_cache.state==state_x &&
        active_geometry_cache.geometry===geometry || throw(ArgumentError(
            "composite current geometry cache is not bound to its actual domain/state/geometry"))
    _ccp_full_native_composite_dynamic_lcfs_current_trace(data,state_x,geometry;
        with_jacobian=with_jacobian,geometry_cache=active_geometry_cache,
        kernel_calls_ref=kernel_calls_ref,max_kernel_calls=max_kernel_calls,
        pf_ring_evaluations_ref=pf_ring_evaluations_ref)
end

function freegs_axisymmetric_full_support_profile_callbacks(context,artifacts,
        t::FreeGSAxisymmetricLCFSTraceV4;vary_profile_coefficients::Bool=false,
        dynamic_profile_span::Bool=false,
        native_field_model_id::Symbol=:source_fd_anchor_plus_plasma_spline_increment_v1,
        toroidal_coordinate::Symbol=:native_Bphi_T_v1)
    toroidal_coordinate in (:native_Bphi_T_v1,:native_F_defect_T_m_v1) ||
        throw(ArgumentError("unsupported full-native toroidal coordinate"))
    toroidal_coordinate===:native_F_defect_T_m_v1 &&
        !(dynamic_profile_span && vary_profile_coefficients &&
          native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1) &&
        throw(ArgumentError("D coordinates require the selected dynamic-span absolute-field full-native model"))
    native_field_model_id in (:source_fd_anchor_plus_plasma_spline_increment_v1,
            :plasma_spline_plus_exact_pf_potential_jet_v1) ||
        throw(ArgumentError("unsupported native Br/Bz field model ID"))
    dynamic_profile_span && !vary_profile_coefficients &&
        throw(ArgumentError("dynamic profile span requires variable profile coefficients"))
    _ccp_validate_lcfs_trace(t)
    d=t.data; api=parentmodule(typeof(artifacts))
    d.candidate_hash==string(context.candidate_hash) && d.context_hash==string(context.context_hash) ||
        throw(ArgumentError("full profile candidate/context differs from the accepted trace"))
    getfield(api,:validate_freegs_axisymmetric_receipt)(context,artifacts.receipt)
    getfield(api,:_freegs_sha256_text)(artifacts.input_json)==artifacts.receipt.input_hash &&
        getfield(api,:_freegs_sha256_text)(artifacts.output_json)==artifacts.receipt.output_hash &&
        d.upstream_output_hash==string(artifacts.receipt.output_hash) ||
        throw(ArgumentError("full profile source differs from the accepted trace"))
    binding=getfield(api,:_freegs_context_binding)(context)
    pressure_domain=isdefined(api,:_freegs_owned_pressure_domain) ?
        getfield(api,:_freegs_owned_pressure_domain)(context.candidate) : nothing
    declaration=binding.declaration; law=d.profile_law; support=d.current_support
    identity=(candidate_hash=d.candidate_hash,context_hash=d.context_hash,
        upstream_output_hash=d.upstream_output_hash,missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,
        full_model_constructed=false,global_topology_closed=false,coupled_solve_attempted=false,
        physical_validation=false,claim_ceiling=screen_only)
    _ccp_full_profile_law_supported(law) &&
        declaration.profile.alpha_m==1.0 && declaration.profile.alpha_n==2.0 ||
        return merge(identity,(status=:typed_absent,reason=:unsupported_profile_exponents))
    support.status===:present || return merge(identity,
        (status=:typed_absent,reason=:accepted_native_core_mask_unavailable))
    d.profile_boundary_pressure_Pa==0.0 && law.fvac_T_m>0 &&
        declaration.profile.vacuum_f_tm==law.fvac_T_m ||
        throw(ArgumentError("full profile requires declared zero boundary pressure and positive fvac"))
    nr=length(support.R_m); nz=length(support.Z_m); n=nr*nz
    nr==declaration.domain.nx && nz==declaration.domain.ny ||
        throw(ArgumentError("full profile grid differs from declared domain"))
    samples=artifacts.field_samples_rz_m
    length(samples)==n || throw(ArgumentError("full native field sample coverage is missing"))
    # Bind all exported nodes, including exterior Br/Bz, to the already verified
    # output bytes once. No JSON work occurs in the changing-state callbacks.
    raw_output=getfield(api,:JSON3).read(artifacts.output_json)
    raw=raw_output[:field_samples_rz_m]
    length(raw)==n || throw(ArgumentError("accepted output lacks the full native sample array"))
    gs_input=_ccp_native_gs4_input(get(raw_output,:native_gs_state,nothing),support)
    gs_ready=gs_input.status===:present
    dynamic_profile_span && !gs_ready && throw(ArgumentError("dynamic profile span requires same-run GS4 source data"))
    native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 && !gs_ready &&
        throw(ArgumentError("absolute native Br/Bz field model requires same-run plasma psi source data"))
    length(support.core_mask)==nr && all(row->length(row)==nz,support.core_mask) ||
        throw(ArgumentError("full native mask dimensions differ"))
    R=Float64[]; Z=Float64[]; mask=Bool[]; initial=Float64[]; raw_status=Symbol[];raw_reason=Symbol[]
    core_pressure=Float64[]; pressure_dofs=zeros(Int,n); pressure_rows=zeros(Int,n)
    for i in 1:nr,j in 1:nz
        k=(i-1)*nz+j; sample=samples[k]; c=sample.constitutive
        rr=raw[k]
        all(name->getproperty(sample,name)==Float64(rr[name]),
            (:R_m,:Z_m,:Br_T,:Bz_T,:psi_wb_per_rad)) &&
            String(c.status)==String(rr[:constitutive][:status]) &&
            String(c.reason)==String(rr[:constitutive][:reason]) ||
            throw(ArgumentError("full native sample values differ from accepted output bytes"))
        r=support.R_m[i]; z=support.Z_m[j]; m=support.core_mask[i][j]
        m in (0.0,1.0) || throw(ArgumentError("native mask must remain exactly binary"))
        tol=16eps(Float64)*max(1.0,abs(r),abs(z))
        abs(sample.R_m-r)<=tol && abs(sample.Z_m-z)<=tol ||
            throw(ArgumentError("full native sample order/coordinates differ"))
        psi=support.psi_wb_per_rad[i][j]
        isapprox(sample.psi_wb_per_rad,psi;rtol=1e-12,atol=1e-12) ||
            throw(ArgumentError("full native field and profile flux differ"))
        if m==1.0
            c.status===:present && c.core_mask==1.0 ||
                throw(ArgumentError("core node lacks its accepted constitutive state"))
            p=c.pressure_Pa; bp=c.Btor_T
            p==Float64(rr[:constitutive][:pressure_Pa]) && bp==Float64(rr[:constitutive][:Btor_T]) ||
                throw(ArgumentError("full native core state differs from accepted output bytes"))
        else
            c.status===:typed_absent || throw(ArgumentError("raw outside absence was not retained"))
            p=nothing; bp=law.fvac_T_m/r
        end
        push!(R,r);push!(Z,z);push!(mask,m==1.0);push!(raw_status,c.status);push!(raw_reason,c.reason)
        append!(initial,(sample.Br_T,bp,sample.Bz_T,psi))
        if m==1.0
            push!(core_pressure,p);pressure_dofs[k]=4n+length(core_pressure)
            pressure_rows[k]=n+length(core_pressure)
        end
    end
    append!(initial,core_pressure)
    Raxis=collect(support.R_m);Zaxis=collect(support.Z_m)
    pressure_geometry_map=pressure_domain===nothing ?
        (status=:typed_absent,reason=:no_authored_pressure_domain) :
        _ccp_pressure_domain_geometry_map(d.coordinates_m,d.normals_RZ,Raxis,Zaxis,mask,pressure_dofs,
            pressure_domain,t.trace_hash,d.representation,d.upstream_output_hash,
            string(artifacts.receipt.runner_code_hash))
    coefficient_columns=(length(initial)+1,length(initial)+2)
    accepted_coefficients=(law.L_A_per_m2*law.Beta0,law.L_A_per_m2*(1-law.Beta0))
    vary_profile_coefficients && append!(initial,accepted_coefficients)
    span_columns=dynamic_profile_span ? (length(initial)+1,length(initial)+2) : ()
    dynamic_profile_span && append!(initial,(law.psi_axis_wb_per_rad,law.psi_boundary_wb_per_rad))
    profile_coefficients(x)=vary_profile_coefficients ?
        (x[coefficient_columns[1]],x[coefficient_columns[2]]) : accepted_coefficients
    ndof=length(initial); nrows=n+length(core_pressure)
    all(isfinite,initial) || throw(ArgumentError("full native initial state is nonfinite"))
    # The four geometric faces share their corner nodes: 516 incidences but
    # 512 unique nodes on a 129x129 grid. Each face keeps its own outward normal.
    faces=((name=:R_min,ids=[j for j in 1:nz],normal=(-1.0,0.0)),
        (name=:R_max,ids=[(nr-1)*nz+j for j in 1:nz],normal=(1.0,0.0)),
        (name=:Z_min,ids=[(i-1)*nz+1 for i in 1:nr],normal=(0.0,-1.0)),
        (name=:Z_max,ids=[i*nz for i in 1:nr],normal=(0.0,1.0)))
    boundary_ids=sort!(unique!(Int[k for face in faces for k in face.ids]))
    all(k->!mask[k],boundary_ids) ||
        throw(ArgumentError("this derived vacuum boundary requires every native outer node outside core"))
    # Reexecute the actual source program in one batch across every exterior
    # node. Its existing evaluator compiles the field program once per batch.
    exterior_ids=findall(!,mask)
    authored=getfield(api,:freegs_axisymmetric_authored_source_values)(context;
        sample_RZ=[(R[k],Z[k]) for k in exterior_ids])
    authored.status===:evaluated_authored_G1_G3_sources &&
        isapprox(authored.vacuum_f_tm,law.fvac_T_m;rtol=64eps(Float64),atol=0) ||
        throw(ArgumentError("outer TF source sign/coefficient is missing or differs from profile fvac"))
    exterior_TF_Bphi=collect(authored.TF_Bphi_T)
    length(exterior_TF_Bphi)==length(exterior_ids) &&
        all(q->isapprox(initial[4exterior_ids[q]-2],exterior_TF_Bphi[q];
            rtol=64eps(Float64),atol=0),eachindex(exterior_ids)) ||
        throw(ArgumentError("derived exterior F differs from executed G3 TF source values"))
    lcfs_dynamic_geometry_data=(gs_ready=gs_ready,critical_points=support.critical_points,
        support_psi=Float64[support.psi_wb_per_rad[cld(k,nz)][mod1(k,nz)] for k in 1:n],
        anchor_psi=Float64[initial[4k] for k in 1:n],Raxis=copy(Raxis),Zaxis=copy(Zaxis),
        Dr=copy(_ccp_native_spline_derivative(Raxis)),Dz=copy(_ccp_native_spline_derivative(Zaxis)),
        plasma_reference=gs_ready ? copy(gs_input.plasma_psi) : Float64[],
        pf_loop_support=Tuple(d.pf_loop_support),
        coil_currents_A_per_turn=Tuple(d.coil_currents_A_per_turn),mu0_N_per_A2=law.mu0_N_per_A2,
        dynamic_profile_span=dynamic_profile_span,span_columns=span_columns,
        profile_axis_Wb_per_rad=law.psi_axis_wb_per_rad,
        profile_boundary_Wb_per_rad=law.psi_boundary_wb_per_rad,
        nr=nr,nz=nz,n=n,ndof=ndof,mask=copy(mask),pressure_dofs=copy(pressure_dofs))
    native_pf_field_grid=if native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1
        length(lcfs_dynamic_geometry_data.pf_loop_support)==
            length(lcfs_dynamic_geometry_data.coil_currents_A_per_turn)>0 ||
            throw(ArgumentError("absolute native Br/Bz model requires the accepted PF loop/current map"))
        pf_psi=zeros(n);pf_br=zeros(n);pf_bz=zeros(n)
        pf_clip_count=0;pf_eval_count=0;pf_m_min=Inf;pf_m_max=0.0
        for k in 1:n
            i=cld(k,nz);j=mod1(k,nz)
            jet=_ccp_full_native_exact_pf_jet(lcfs_dynamic_geometry_data,Raxis[i],Zaxis[j])
            pf_psi[k]=jet.psi
            pf_clip_count+=jet.source_clip_count;pf_eval_count+=jet.source_clip_evaluation_count
            pf_m_min=min(pf_m_min,jet.raw_m_min);pf_m_max=max(pf_m_max,jet.raw_m_max)
            pf_br[k]=-jet.gradient[2]/Raxis[i]
            pf_bz[k]=jet.gradient[1]/Raxis[i]
        end
        all(isfinite,pf_psi) && all(isfinite,pf_br) && all(isfinite,pf_bz) ||
            throw(ArgumentError("absolute native Br/Bz PF jet is nonfinite"))
        (psi_Wb_per_rad=pf_psi,Br_T=pf_br,Bz_T=pf_bz,
            model=:unclipped_analytic_circular_filament_Green_jet,
            source_clip_count=pf_clip_count,source_clip_evaluation_count=pf_eval_count,
            m_raw_min=pf_m_min,m_raw_max=pf_m_max,source_fd_anchor_use=:provenance_only)
    else
        nothing
    end
    lcfs_dynamic_geometry_data=merge(lcfs_dynamic_geometry_data,
        (native_field_model_id=native_field_model_id,
         pf_native_psi_Wb_per_rad=native_pf_field_grid===nothing ? nothing : native_pf_field_grid.psi_Wb_per_rad,
         pf_native_source_clip_count=native_pf_field_grid===nothing ? 0 : native_pf_field_grid.source_clip_count,
         pf_native_source_clip_evaluation_count=native_pf_field_grid===nothing ? 0 : native_pf_field_grid.source_clip_evaluation_count,
         pf_native_m_raw_min=native_pf_field_grid===nothing ? Inf : native_pf_field_grid.m_raw_min,
         pf_native_m_raw_max=native_pf_field_grid===nothing ? 0.0 : native_pf_field_grid.m_raw_max))
    physical_initial=copy(initial)
    toroidal_geometry_domain=(ndof=ndof,n=n,mask=mask,law=law,
        vary_profile_coefficients=vary_profile_coefficients,
        coefficient_columns=coefficient_columns,accepted_coefficients=accepted_coefficients,
        dynamic_profile_span=dynamic_profile_span,span_columns=span_columns,
        dynamic_geometry_data=(Raxis=Raxis,nz=nz),toroidal_coordinate=toroidal_coordinate)
    lcfs_dynamic_geometry_data=merge(lcfs_dynamic_geometry_data,
        (toroidal_coordinate=toroidal_coordinate,toroidal_geometry_domain=toroidal_geometry_domain))
    state_domain=(ndof=ndof,n=n,mask=mask,pressure_dofs=pressure_dofs,law=law,
        toroidal_coordinate=toroidal_coordinate,native_field_model_id=native_field_model_id,
        vary_profile_coefficients=vary_profile_coefficients,
        coefficient_columns=coefficient_columns,accepted_coefficients=accepted_coefficients,
        dynamic_profile_span=dynamic_profile_span,span_columns=span_columns,
        dynamic_geometry_data=lcfs_dynamic_geometry_data)
    initial_coordinate_record=if toroidal_coordinate===:native_F_defect_T_m_v1
        converted=_ccp_full_native_prepare_D_trial(
            merge(state_domain,(toroidal_coordinate=:native_Bphi_T_v1,)),physical_initial,
            _ccp_full_native_profile_F_lift_jet;action=:encode_legacy)
        initial=converted.state
        (state=initial,state_coordinate_id=toroidal_coordinate,
            coordinate_origin=:explicit_legacy_conversion,
            physical_defect_change_T_m=converted.physical_defect_change_T_m,
            same_old_physical_state_claim=false)
    else
        (state=initial,state_coordinate_id=toroidal_coordinate,
            coordinate_origin=:accepted_source_Bphi,physical_defect_change_T_m=:not_applicable,
            same_old_physical_state_claim=true)
    end
    checked_state(state)=_ccp_full_native_checked_state(state_domain,state)
    profile_numeric_data=(domain=state_domain,R=R,pressure_rows=pressure_rows,nrows=nrows)
    profile_evaluate=state->_ccp_full_native_profile_evaluate(profile_numeric_data,state)
    profile_oracle=state->_ccp_full_native_profile_oracle(profile_numeric_data,state)
    # The default model preserves the source finite-difference field anchor and
    # applies plasma-spline increments. The absolute model derives plasma flux
    # from the total-flux DOF minus the same exact native PF potential jet.
    Dr=_ccp_native_spline_derivative(Raxis);Dz=_ccp_native_spline_derivative(Zaxis)
    anchor=copy(physical_initial)
    flux_numeric_data=if native_pf_field_grid===nothing
        (n=n,nr=nr,nz=nz,Raxis=Raxis,Zaxis=Zaxis,Dr=Dr,Dz=Dz,anchor=anchor)
    else
        (n=n,nr=nr,nz=nz,Raxis=Raxis,Zaxis=Zaxis,Dr=Dr,Dz=Dz,anchor=anchor,
            native_field_model_id=native_field_model_id,
            pf_native_psi_Wb_per_rad=native_pf_field_grid.psi_Wb_per_rad,
            pf_native_Br_T=native_pf_field_grid.Br_T,pf_native_Bz_T=native_pf_field_grid.Bz_T)
    end
    flux_jacobian=_ccp_native_flux_jacobian(Raxis,Zaxis,Dr,Dz,ndof)
    oracle_flux_jacobian=Ref{Any}(nothing)
    # Absolute GS4 equations use exported plasma flux, not total-flux vacuum
    # assumptions. Fixed PF implies delta(plasma psi)==delta(total psi).
    selected_current_operator=native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1
    gs_operator=gs_ready ? (selected_current_operator ?
        _ccp_native_spline_delta_star_operator(Raxis,Zaxis,Dr,Dz) :
        merge(_ccp_native_gs4_operator(Raxis,Zaxis),(model_id=:legacy_freegs_A4h_source_cp_v1,))) : nothing
    gs_source_operator=gs_ready ? merge(_ccp_native_gs4_operator(Raxis,Zaxis),
        (model_id=:legacy_freegs_A4h_source_cp_v1,)) : nothing
    gs_oracle_operator=Ref{Any}(nothing)
    gs_rows=gs_ready ? length(gs_operator.native_ids) : 0
    gs_current_coeff=law.L_A_per_m2.*(law.Beta0.*R./law.Raxis_m.+(1-law.Beta0).*law.Raxis_m./R)
    gs_delta=law.psi_axis_wb_per_rad-law.psi_boundary_wb_per_rad
    gs_numeric_data=gs_ready ? (domain=state_domain,R=R,gs_delta=gs_delta,
        gs_current_coeff=gs_current_coeff,native_ids=gs_operator.native_ids,
        operator_model_id=gs_operator.model_id,plasma_psi=gs_input.plasma_psi,
        anchor_psi=anchor[4:4:4n]) : nothing
    gs_comparison_bound=0.0
    gs_coefficient(x,k)=vary_profile_coefficients ?
        x[coefficient_columns[1]]*R[k]/law.Raxis_m+x[coefficient_columns[2]]*law.Raxis_m/R[k] : gs_current_coeff[k]
    function gs_current(x;profile_span=nothing)
        span=profile_span===nothing ? _ccp_full_native_profile_span(state_domain,x) : profile_span
        [mask[k] ? gs_coefficient(x,k)*_ccp_full_native_profile_shape(
            x[4k],span.axis,span.boundary).q^2 : 0.0 for k in 1:n]
    end
    if gs_ready
        d.solver_jtor_diagnostic.status===:present || throw(ArgumentError("GS4 requires separate actual retained current"))
        retained=[d.solver_jtor_diagnostic.solver_eq_Jtor_A_per_m2[i][j] for i in 1:nr for j in 1:nz]
        final=[support.Jphi_A_per_m2[i][j] for i in 1:nr for j in 1:nz]
        ids=gs_source_operator.native_ids;A=gs_source_operator.operator
        source_current=gs_current(initial)
        maximum(abs,source_current-final)<=512eps(Float64)*max(1.0,maximum(abs,final)) ||
            throw(ArgumentError("GS4 fixed profile current differs from accepted final-profile source"))
        for (current,reference) in ((retained,gs_input.retained_reference),(source_current,gs_input.final_reference))
            actual=A*gs_input.plasma_psi+law.mu0_N_per_A2.*R[ids].*current[ids]
            # Scale by the absolute operator products, not a tiny PDE residual.
            scale=abs.(A)*abs.(gs_input.plasma_psi)+abs.(law.mu0_N_per_A2.*R[ids].*current[ids])
            gs_comparison_bound=max(gs_comparison_bound,2048eps(Float64)*max(1.0,maximum(scale)))
            all(i->abs(actual[i]-reference[i])<=2048eps(Float64)*max(1.0,scale[i]),eachindex(actual)) ||
                throw(ArgumentError("GS4 source reference differs from the original FreeGS operator"))
        end
    end
    function gs_block(x;independent=false)
        gs_ready || return (residual=Float64[],jacobian=spzeros(0,ndof))
        if independent && gs_oracle_operator[]===nothing
            gs_oracle_operator[]=selected_current_operator ?
                _ccp_native_spline_delta_star_operator(Raxis,Zaxis,Dr,Dz;independent=true) :
                merge(_ccp_native_gs4_operator(Raxis,Zaxis;independent=true),
                    (model_id=:legacy_freegs_A4h_source_cp_v1,))
        end
        A=independent ? gs_oracle_operator[].operator : gs_operator.operator
        _ccp_full_native_gs_rows(gs_numeric_data,x,A;independent=independent)
    end

    normalization_rows=vary_profile_coefficients ? 2 : 0
    normalization_weights=if vary_profile_coefficients
        wr=_ccp_native_romberg_weights(nr);wz=_ccp_native_romberg_weights(nz)
        dr=Raxis[2]-Raxis[1];dz=Zaxis[2]-Zaxis[1]
        dr>0 && dz>0 && all(i->isapprox(Raxis[i],Raxis[1]+(i-1)*dr;
            rtol=0,atol=32eps(Float64)*max(1.0,abs(Raxis[end]))),1:nr) &&
            all(j->isapprox(Zaxis[j],Zaxis[1]+(j-1)*dz;
            rtol=0,atol=32eps(Float64)*max(1.0,abs(Zaxis[end]))),1:nz) ||
            throw(ArgumentError("profile Romberg normalization needs the actual uniform native grid"))
        [wr[i]*wz[j]*dr*dz for i in 1:nr for j in 1:nz]
    else
        Float64[]
    end
    normalization_numeric_data=(domain=state_domain,R=R,gs_delta=gs_delta,
        axis_pressure_pa=declaration.profile.axis_pressure_pa,
        plasma_current_a=declaration.profile.plasma_current_a)
    normalization_oracle_weights=Ref{Any}(nothing)
    function normalization_block(x;independent=false)
        vary_profile_coefficients || return (residual=Float64[],jacobian=spzeros(0,ndof))
        if independent && normalization_oracle_weights[]===nothing
            wr=_ccp_native_romberg_weights_oracle(nr);wz=_ccp_native_romberg_weights_oracle(nz)
            dr=Raxis[2]-Raxis[1];dz=Zaxis[2]-Zaxis[1]
            normalization_oracle_weights[]=[wr[i]*wz[j]*dr*dz for i in 1:nr for j in 1:nz]
        end
        weights=independent ? normalization_oracle_weights[] : normalization_weights
        _ccp_full_native_normalization_block(normalization_numeric_data,x,weights;independent=independent)
    end

    # Source-equivalent freeBoundaryHagenow feedback. The input is the same
    # run's plasma-only flux; `x[psi]` remains total flux, so fixed PF flux is
    # removed by a bound offset while state increments pass through unchanged.
    core_ids=findall(mask)
    plasma_reference=gs_ready ? copy(gs_input.plasma_psi) : Float64[]
    # Reconstruct the external FreeGS source response with its original A4h
    # operator. The selected continuous-psi GS operator has a separate role.
    hagenow_map=gs_ready ? merge(_ccp_native_hagenow_core_map(
        Raxis,Zaxis,gs_source_operator,core_ids,law.mu0_N_per_A2),
        (source_operator_model_id=gs_source_operator.model_id,)) : nothing
    coil_flux_reference=gs_ready ? [support.psi_wb_per_rad[cld(k,nz)][mod1(k,nz)]-
        plasma_reference[k] for k in 1:n] : Float64[]
    hagenow_rows=gs_ready ? length(hagenow_map.boundary_native_ids) : 0
    hagenow_source_reference=gs_ready ? gs_input.hagenow_source : nothing
    hagenow_source_current=gs_ready ? gs_current(initial)[core_ids] : Float64[]
    hagenow_source_map_values=gs_ready ? hagenow_map.response_per_Jphi*hagenow_source_current : Float64[]
    hagenow_source_values=gs_ready ? hagenow_source_reference.final_profile_boundary_values : Float64[]
    hagenow_source_comparison_error=gs_ready ? maximum(abs,hagenow_source_map_values-hagenow_source_values) : nothing
    hagenow_source_comparison_bound=gs_ready ? 2048eps(Float64)*max(1.0,
        maximum(abs,hagenow_source_map_values),maximum(abs,hagenow_source_values)) : nothing
    gs_ready && hagenow_source_comparison_error>hagenow_source_comparison_bound &&
        throw(ArgumentError("analytic Hagenow map differs from direct FreeGS boundary source reference"))

    # The source attachment was authenticated once by the existing execution
    # transport. Bind its exact native orders to this accepted mask and output.
    hagenow_source_attachment=artifacts.hagenow_source_response
    hagenow_source_metadata=getfield(api,:_freegs_hagenow_source_metadata)(raw_output)
    (hagenow_source_attachment===nothing)==(hagenow_source_metadata===nothing) ||
        throw(ArgumentError("Hagenow source matrix metadata/attachment is missing"))
    hagenow_source_H=nothing
    hagenow_full_source_validation=:not_executed
    hagenow_full_source_map_error=nothing;hagenow_full_source_map_bound=nothing
    hagenow_initial_source_jacobian_error=nothing;hagenow_initial_source_jacobian_bound=nothing
    if hagenow_source_attachment!==nothing
        gs_ready || throw(ArgumentError("Hagenow source matrix lacks supported GS input"))
        a=hagenow_source_attachment;m=hagenow_source_metadata
        String(m[:status])=="present" && String(m[:file_name])=="hagenow_source_response.f64" &&
            String(m[:encoding])==String(a.encoding) && String(m[:sha256])==a.sha256 &&
            Int.(m[:shape])==[hagenow_rows,length(core_ids)] &&
            m[:byte_count]==8hagenow_rows*length(core_ids) &&
            Int.(m[:boundary_native_ids])==a.boundary_native_ids==hagenow_map.boundary_native_ids &&
            Int.(m[:core_native_ids])==a.core_native_ids==core_ids &&
            size(a.values)==(hagenow_rows,length(core_ids)) && all(isfinite,a.values) ||
            throw(ArgumentError("Hagenow source matrix differs from accepted output/native support"))
        hagenow_source_H=copy(a.values)
        hagenow_full_source_map_error=maximum(abs,hagenow_map.response_per_Jphi-hagenow_source_H)
        hagenow_full_source_map_bound=2048eps(Float64)*max(1.0,
            maximum(abs,hagenow_map.response_per_Jphi),maximum(abs,hagenow_source_H))
        isfinite(hagenow_full_source_map_error) && isfinite(hagenow_full_source_map_bound) &&
            hagenow_full_source_map_error<=hagenow_full_source_map_bound ||
            throw(ArgumentError("full analytic Hagenow map differs from independent source matrix"))
    end
    # Set the public response after source validation and before any callback
    # can read it during the independent Jacobian comparison.
    hagenow_public_response=gs_ready ?
        copy(hagenow_source_H===nothing ? hagenow_map.response_per_Jphi : hagenow_source_H) : nothing

    hagenow_profile_scope=vary_profile_coefficients ? :fixed_mask_axis_boundary_with_variable_profile_coefficients : :fixed_accepted_mask_axis_boundary_and_profile_coefficients
    # Private numerical state shared by component and outer ABI; no public matrix aliases.
    hagenow_numeric_data=gs_ready ? (domain=state_domain,R=R,core_ids=core_ids,
        boundary_native_ids=hagenow_map.boundary_native_ids,gs_delta=gs_delta,
        gs_current_coeff=gs_current_coeff,plasma_reference=plasma_reference,
        anchor_psi=anchor[4:4:4n],response_per_Jphi=hagenow_map.response_per_Jphi,
        source_H=hagenow_source_H,source_operator_model_id=gs_source_operator.model_id) : nothing
    function hagenow_block(x)
        gs_ready || return (status=:typed_absent,reason=gs_input.reason,
            residual=Float64[],jacobian=spzeros(0,ndof),native_ids=Int[],
            response_map=nothing,backward_error=nothing,absolute_boundary_anchor_subtracted=false)
        evaluated=_ccp_full_native_hagenow_block(hagenow_numeric_data,x)
        residual=evaluated.residual;j=evaluated.current;djdpsi=evaluated.derivative
        result=(status=:evaluated_absolute_plasma_psi_minus_freeBoundaryHagenow,
            reason=:same_run_plasma_flux_and_profile_coefficients,
            residual=residual,jacobian=evaluated.jacobian,
            native_ids=copy(hagenow_map.boundary_native_ids),
            response_map=hagenow_public_response,
            source_boundary_values=copy(hagenow_source_values),
            source_boundary_residual=plasma_reference[hagenow_map.boundary_native_ids]-hagenow_source_values,
            source_map_comparison_error=hagenow_source_comparison_error,
            source_map_comparison_bound=hagenow_source_comparison_bound,
            full_hagenow_jacobian_source_validation=hagenow_full_source_validation,
            current_A_per_m2=j,derivative_dJ_dpsi_A_m2_per_Wb_rad=djdpsi,
            profile_scope=hagenow_profile_scope,absolute_boundary_anchor_subtracted=false,
            adjoint_solve_max_backward_error=hagenow_map.adjoint_solve_max_backward_error,
            fixed_pf_flux=copy(coil_flux_reference),
            green_source_arguments=hagenow_map.greens_source_arguments,
            green_observation_arguments=hagenow_map.greens_observation_arguments,
            outward_observation_epsilon_m=hagenow_map.outward_observation_epsilon_m,
            corner_trace=:source_diagonal_fourth_order,
            sparse_lu_direct_solver=true,linear_solver_stopping_tolerance=:not_applicable_direct_factorization)
        native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
            merge(result,(fixed_pf_flux=copy(native_pf_field_grid.psi_Wb_per_rad),
                source_equilibrium_pf_flux=copy(coil_flux_reference))) : result
    end
    hagenow_oracle_jacobian(x)=gs_ready ?
        _ccp_full_native_hagenow_oracle(hagenow_numeric_data,x) : spzeros(0,ndof)

    if hagenow_source_H!==nothing
        # Both full sparse blocks include every boundary identity column and
        # every core psi column, plus u/v when those are actual state unknowns.
        let candidate=hagenow_block(initial).jacobian,source=hagenow_oracle_jacobian(initial)
            hagenow_initial_source_jacobian_error=maximum(abs,nonzeros(candidate-source);init=0.0)
            hagenow_initial_source_jacobian_bound=2048eps(Float64)*max(1.0,
                maximum(abs,nonzeros(candidate);init=0.0),maximum(abs,nonzeros(source);init=0.0))
        end
        isfinite(hagenow_initial_source_jacobian_error) && isfinite(hagenow_initial_source_jacobian_bound) &&
            hagenow_initial_source_jacobian_error<=hagenow_initial_source_jacobian_bound ||
            throw(ArgumentError("complete initial Hagenow Jacobian differs from independent source chain"))
        hagenow_full_source_validation=:passed
        hagenow_source_reference=merge(hagenow_source_reference,(
            producer_full_jacobian_status=hagenow_source_reference.full_jacobian_status,
            full_jacobian_status=:passed,
            full_jacobian_validation_scope=:complete_source_H_and_initial_sparse_H_block_fixed_PF_mask_axis_boundary,
            full_jacobian_kernel_validation_scope=:analytic_reconstructed_H_vs_exported_source_H_entrywise_max_abs_with_2048eps_bound,
            full_jacobian_profile_derivative_validation_scope=:complex_step_profile_current_derivative_with_source_H_fixed_mask_axis_boundary))
    end
    # Conservative axisymmetric poloidal-current face map from the actual
    # full-grid toroidal field state. Faces use positive R / positive Z
    # orientation; the cell incidence signs are outward from each RZ cell.
    # The 2蟺 factor converts the per-radian R-weighted Ampere flux to current
    # through the toroidal surface. This is an observation, never a solver row.
    function poloidal_current_face_map(x)
        nRfaces=nr*(nz-1);nZfaces=(nr-1)*nz;nfaces=nRfaces+nZfaces
        ncell=(nr-1)*(nz-1);scale=2pi/law.mu0_N_per_A2
        fnode=_ccp_full_native_D_coordinate(state_domain) ?
            _ccp_full_native_state_toroidal_samples(state_domain,x).F_centered_T_m :
            [R[k]*x[4k-2] for k in 1:n]
        face_flux=zeros(nfaces);jr=Int[];jc=Int[];jv=Float64[]
        sizehint!(jr,2nfaces);sizehint!(jc,2nfaces);sizehint!(jv,2nfaces)
        rface(i,j)=(i-1)*(nz-1)+j
        zface(i,j)=nRfaces+(i-1)*nz+j
        for i in 1:nr,j in 1:nz-1
            row=rface(i,j);a=(i-1)*nz+j;b=a+1
            # Positive-R flux: 2蟺鈭玆 J_R dZ = -2蟺 螖_Z F / 渭0.
            face_flux[row]=-scale*(fnode[b]-fnode[a])
            push!(jr,row);push!(jc,4a-2);push!(jv,scale*R[a])
            push!(jr,row);push!(jc,4b-2);push!(jv,-scale*R[b])
        end
        for i in 1:nr-1,j in 1:nz
            row=zface(i,j);a=(i-1)*nz+j;b=i*nz+j
            # Positive-Z flux: 2蟺鈭玆 J_Z dR = 2蟺 螖_R F / 渭0.
            face_flux[row]=scale*(fnode[b]-fnode[a])
            push!(jr,row);push!(jc,4a-2);push!(jv,-scale*R[a])
            push!(jr,row);push!(jc,4b-2);push!(jv,scale*R[b])
        end
        ir=Int[];ic=Int[];iv=Float64[];cell_class=Vector{Symbol}(undef,ncell)
        sizehint!(ir,4ncell);sizehint!(ic,4ncell);sizehint!(iv,4ncell)
        for i in 1:nr-1,j in 1:nz-1
            row=(i-1)*(nz-1)+j
            push!(ir,row);push!(ic,rface(i+1,j));push!(iv,1.0)
            push!(ir,row);push!(ic,rface(i,j));push!(iv,-1.0)
            push!(ir,row);push!(ic,zface(i,j+1));push!(iv,1.0)
            push!(ir,row);push!(ic,zface(i,j));push!(iv,-1.0)
            ids=((i-1)*nz+j,(i-1)*nz+j+1,i*nz+j,i*nz+j+1)
            active=count(k->mask[k],ids)
            cell_class[row]=active==4 ? :core : active==0 ? :exterior : :mask_cut
        end
        incidence=sparse(ir,ic,iv,ncell,nfaces)
        divergence=incidence*face_flux
        face_jacobian=_ccp_full_native_physical_row_pullback(state_domain,x,
            sparse(jr,jc,jv,nfaces,ndof))
        (status=:evaluated_axisymmetric_poloidal_current_face_flux,
            native_grid_shape=(nr,nz),face_flux_A=face_flux,
            face_flux_order=:positive_R_faces_then_positive_Z_faces,
            R_face_shape=(nr,nz-1),Z_face_shape=(nr-1,nz),
            cell_outward_incidence=incidence,cell_flux_divergence_A=divergence,
            cell_native_order=:R_then_Z,cell_support_class=cell_class,
            face_flux_jacobian=face_jacobian,
            face_flux_jacobian_columns=:full_state_Bphi_native_dofs,
            face_flux_definition=:two_pi_integral_RJpol_from_endpoint_delta_F,
            state_source=:actual_full_native_Bphi_state,F_definition=:R_times_Bphi,
            exterior_mask_retained=true,mask_cut_cells_are_not_LCFS=true,
            independent_TF_current=:authored_G3_source_outside_grid,
            TF_conductor_current_density=:typed_absent,
            independent_PF_loop_sources=d.pf_loop_support,
            PF_conductor_current_density=:separate_declared_ring_sources,
            toroidal_Jphi_scope=:periodic_phi_ring_no_reverse_leg_declared,
            full_current_vector_not_closed=true,return_path=:typed_absent,
            current_topology=:typed_absent,global_topology_closed=false,
            extra_solver_rows=0,claim_ceiling=screen_only)
    end

    # Source-derived core current is an observation of this changing state.
    # It is not an extra equation block or a full-domain/face-current closure.
    core_current_trace=function(state;region=nothing,with_full_curl=false,with_full_curl_jacobian=true,with_jphi_operator_budget=false)
        x=checked_state(state);u,v=profile_coefficients(x)
        physical_x=_ccp_full_native_physical_state_observation(state_domain,x)
        D_coordinate=_ccp_full_native_D_coordinate(state_domain)
        profile_span=_ccp_full_native_profile_span(state_domain,x)
        current=zeros(3length(core_ids));rows=Int[];cols=Int[];entries=Float64[]
        sizehint!(rows,11length(core_ids));sizehint!(cols,11length(core_ids));sizehint!(entries,11length(core_ids))
        toroidal=gs_current(x;profile_span=profile_span)
        for (j,k) in enumerate(core_ids)
            br,bp,bz=physical_x[4k-3],physical_x[4k-2],physical_x[4k-1]
            shape=_ccp_full_native_profile_shape(x[4k],profile_span.axis,profile_span.boundary)
            q=shape.q;f=R[k]*bp
            factor=v*law.Raxis_m*q^2/f
            dpsi=dynamic_profile_span ? 2v*law.Raxis_m*q/(profile_span.delta*f) :
                2v*law.Raxis_m*(x[4k]-law.psi_boundary_wb_per_rad)/(gs_delta^2*f)
            dbp=-factor/bp
            dv=law.Raxis_m*q^2/f
            current[3j-2]=factor*br;current[3j-1]=toroidal[k];current[3j]=factor*bz
            for (row,column,value) in ((3j-2,4k-3,factor),(3j-2,4k-2,dbp*br),
                    (3j-2,4k,dpsi*br),(3j,4k-1,factor),(3j,4k-2,dbp*bz),
                    (3j,4k,dpsi*bz),(3j-1,4k,2q*gs_coefficient(x,k)/profile_span.delta))
                push!(rows,row);push!(cols,column);push!(entries,value)
            end
            if dynamic_profile_span
                for (column,dshape) in zip(span_columns,(shape.shape_axis,shape.shape_boundary))
                    dpoloidal=v*law.Raxis_m*dshape/f
                    dtoroidal=gs_coefficient(x,k)*dshape
                    for (row,value) in ((3j-2,dpoloidal*br),(3j,dpoloidal*bz),(3j-1,dtoroidal))
                        push!(rows,row);push!(cols,column);push!(entries,value)
                    end
                end
            end
            if vary_profile_coefficients
                for (row,column,value) in ((3j-2,coefficient_columns[2],dv*br),
                        (3j,coefficient_columns[2],dv*bz),
                        (3j-1,coefficient_columns[1],q^2*R[k]/law.Raxis_m),
                        (3j-1,coefficient_columns[2],q^2*law.Raxis_m/R[k]))
                    push!(rows,row);push!(cols,column);push!(entries,value)
                end
            end
        end
        all(isfinite,current) && all(isfinite,entries) ||
            throw(ArgumentError("core constitutive current became nonfinite"))
        with_full_curl isa Bool && with_full_curl_jacobian isa Bool &&
            with_jphi_operator_budget isa Bool ||
            throw(ArgumentError("full-native curl/budget options must be Boolean"))
        native_curl_current_diagnostic = if with_full_curl
            # Regional curl uses the same profile-F plus spline-defect lift as
            # the moving-LCFS point sampler. The nodal F source rows are unchanged.
            continuous_model=native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1
            if continuous_model
                psi_plasma_nodes=_ccp_full_native_plasma_nodes(x,lcfs_dynamic_geometry_data,
                    native_field_model_id)
                psi_plasma_mat=permutedims(reshape(psi_plasma_nodes,nz,nr))
                native_Jphi_pf=zeros(n)
                for k in 1:n
                    i=cld(k,nz);j=mod1(k,nz)
                    pf=_ccp_full_native_exact_pf_jet(lcfs_dynamic_geometry_data,Raxis[i],Zaxis[j])
                    native_Jphi_pf[k]=-(pf.hessian[1,1]-pf.gradient[1]/Raxis[i]+pf.hessian[2,2])/
                        (law.mu0_N_per_A2*Raxis[i])
                end
                native_Jphi=_ccp_native_continuous_Jphi_core_v1(psi_plasma_mat,gs_operator,Raxis,nz,
                    law.mu0_N_per_A2,collect(1:n),native_Jphi_pf)
            else
                Brmat=permutedims(reshape(Float64[x[4k-3] for k in 1:n],nz,nr))
                Bzmat=permutedims(reshape(Float64[x[4k-1] for k in 1:n],nz,nr))
                Rmat=repeat(reshape(Raxis,nr,1),1,nz)
                native_Jphi=vec(permutedims((Brmat*transpose(Dz)-Dr*Bzmat)./law.mu0_N_per_A2))
            end
            lift_span_dynamic=dynamic_profile_span && vary_profile_coefficients
            lift_span=lift_span_dynamic ? profile_span :
                (axis=law.psi_axis_wb_per_rad,boundary=law.psi_boundary_wb_per_rad,
                    delta=law.psi_axis_wb_per_rad-law.psi_boundary_wb_per_rad)
            lift_v=vary_profile_coefficients ? v : accepted_coefficients[2]
            lift_v_column=vary_profile_coefficients ? coefficient_columns[2] : 0
            lift_A_column=lift_span_dynamic ? span_columns[1] : 0
            lift_B_column=lift_span_dynamic ? span_columns[2] : 0
            lift_samples=_ccp_full_native_state_toroidal_samples(state_domain,x)
            lift_profile=lift_samples.profile
            lift_Ppsi=Float64[p.psi for p in lift_profile]
            lift_Ppsipsi=Float64[p.psipsi for p in lift_profile]
            lift_partial_v_zr=reshape(Float64[p.v for p in lift_profile],nz,nr)
            lift_partial_A_zr=reshape(Float64[p.A for p in lift_profile],nz,nr)
            lift_partial_B_zr=reshape(Float64[p.B for p in lift_profile],nz,nr)
            lift_Ppsi_rz=permutedims(reshape(lift_Ppsi,nz,nr))
            lift_Ppsipsi_rz=permutedims(reshape(lift_Ppsipsi,nz,nr))
            continuous_model=native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1
            psi_interp=continuous_model ?
                _ccp_full_native_plasma_nodes(x,lcfs_dynamic_geometry_data,native_field_model_id) :
                Float64[lcfs_dynamic_geometry_data.support_psi[k]+x[4k]-lcfs_dynamic_geometry_data.anchor_psi[k] for k in 1:n]
            psi_mat=permutedims(reshape(psi_interp,nz,nr))
            psi_R=Dr*psi_mat;psi_Z=psi_mat*transpose(Dz)
            if continuous_model
                for k in 1:n
                    i=cld(k,nz);j=mod1(k,nz)
                    pf=_ccp_full_native_exact_pf_jet(lcfs_dynamic_geometry_data,Raxis[i],Zaxis[j])
                    psi_R[i,j]+=pf.gradient[1];psi_Z[i,j]+=pf.gradient[2]
                end
            end
            lift_current=_ccp_full_native_lift_poloidal_current(law,Raxis,Dr,Dz,
                nr,nz,lift_samples,psi_R,psi_Z)
            native_JR=lift_current.JR
            native_JZ=lift_current.JZ
            native_curl_current=Vector{Float64}(undef,3n)
            native_curl_current[1:3:end].=native_JR
            native_curl_current[2:3:end].=native_Jphi
            native_curl_current[3:3:end].=native_JZ
            accepted_source_Jphi=Float64[support.Jphi_A_per_m2[cld(k,nz)][mod1(k,nz)] for k in core_ids]
            profile_law_Jphi=Float64[toroidal[k] for k in core_ids]
            curl_minus_profile_Jphi=native_Jphi[core_ids].-profile_law_Jphi
            curl_minus_accepted_Jphi=native_Jphi[core_ids].-accepted_source_Jphi
            profile_minus_accepted_Jphi=profile_law_Jphi.-accepted_source_Jphi
            core_area=Float64[support.area_weight_m2[cld(k,nz)][mod1(k,nz)] for k in core_ids]
            curl_Ip_trapezoid=sum(core_area.*native_Jphi[core_ids])
            accepted_source_Ip_trapezoid=sum(core_area.*accepted_source_Jphi)
            curl_jacobian = if with_full_curl_jacobian
                jrows=Int[];jcols=Int[];jvalues=Float64[]
                sizehint!(jrows,3n*(nr+nz+4));sizehint!(jcols,3n*(nr+nz+4));sizehint!(jvalues,3n*(nr+nz+4))
                for i in 1:nr,j in 1:nz
                    target=(i-1)*nz+j
                    rowJR=3target-2;rowJphi=3target-1;rowJZ=3target
                    ptarget=lift_profile[target]
                    for l in 1:nz
                        dZ=Dz[j,l]
                        iszero(dZ) && continue
                        source=(i-1)*nz+l
                        dFZ_Bphi=dZ*(D_coordinate ? 1.0 : Raxis[i])
                        dFZ_psi=dZ*(ptarget.psi-(D_coordinate ? 0.0 : lift_Ppsi[source]))
                        push!(jrows,rowJR);push!(jcols,4source-2);push!(jvalues,-dFZ_Bphi/(law.mu0_N_per_A2*Raxis[i]))
                        push!(jrows,rowJR);push!(jcols,4source);push!(jvalues,-dFZ_psi/(law.mu0_N_per_A2*Raxis[i]))
                        continuous_model || (push!(jrows,rowJphi);push!(jcols,4source-3);push!(jvalues,dZ/law.mu0_N_per_A2))
                    end
                    local_psi_Z=lift_Ppsipsi_rz[i,j]*psi_Z[i,j]
                    iszero(local_psi_Z) || (push!(jrows,rowJR);push!(jcols,4target);push!(jvalues,-local_psi_Z/(law.mu0_N_per_A2*Raxis[i])))
                    for (column,point_partial,node_partials) in
                            ((lift_v_column,ptarget.psiv,view(lift_partial_v_zr,:,i)),
                             (lift_A_column,ptarget.psiA,view(lift_partial_A_zr,:,i)),
                             (lift_B_column,ptarget.psiB,view(lift_partial_B_zr,:,i)))
                        column>0 || continue
                        dFZ=point_partial*psi_Z[i,j]-(D_coordinate ? 0.0 : dot(view(Dz,j,:),node_partials))
                        iszero(dFZ) || (push!(jrows,rowJR);push!(jcols,column);push!(jvalues,-dFZ/(law.mu0_N_per_A2*Raxis[i])))
                    end
                    if continuous_model
                        source_ids,source_values=_ccp_native_spline_delta_star_row(
                            gs_operator.H_RR,gs_operator.radial_first,gs_operator.H_ZZ,i,j,nr,nz)
                        for (source,value) in zip(source_ids,source_values)
                            push!(jrows,rowJphi);push!(jcols,4source)
                            push!(jvalues,-value/(law.mu0_N_per_A2*Raxis[i]))
                        end
                    end
                    for l in 1:nr
                        dR=Dr[i,l]
                        iszero(dR) && continue
                        source=(l-1)*nz+j
                        continuous_model || (push!(jrows,rowJphi);push!(jcols,4source-1);push!(jvalues,-dR/law.mu0_N_per_A2))
                        dFR_Bphi=dR*(D_coordinate ? 1.0 : Raxis[l])
                        dFR_psi=dR*(ptarget.psi-(D_coordinate ? 0.0 : lift_Ppsi[source]))
                        push!(jrows,rowJZ);push!(jcols,4source-2);push!(jvalues,dFR_Bphi/(law.mu0_N_per_A2*Raxis[i]))
                        push!(jrows,rowJZ);push!(jcols,4source);push!(jvalues,dFR_psi/(law.mu0_N_per_A2*Raxis[i]))
                    end
                    local_psi_R=lift_Ppsipsi_rz[i,j]*psi_R[i,j]
                    iszero(local_psi_R) || (push!(jrows,rowJZ);push!(jcols,4target);push!(jvalues,local_psi_R/(law.mu0_N_per_A2*Raxis[i])))
                    for (column,point_partial,node_partials) in
                            ((lift_v_column,ptarget.psiv,view(lift_partial_v_zr,j,:)),
                             (lift_A_column,ptarget.psiA,view(lift_partial_A_zr,j,:)),
                             (lift_B_column,ptarget.psiB,view(lift_partial_B_zr,j,:)))
                        column>0 || continue
                        dFR=point_partial*psi_R[i,j]-(D_coordinate ? 0.0 : dot(view(Dr,i,:),node_partials))
                        iszero(dFR) || (push!(jrows,rowJZ);push!(jcols,column);push!(jvalues,dFR/(law.mu0_N_per_A2*Raxis[i])))
                    end
                end
                all(isfinite,jvalues) || throw(ArgumentError("full-state curl Jacobian is nonfinite"))
                sparse(jrows,jcols,jvalues,3n,ndof)
            else
                :typed_absent
            end
            native_Jphi_operator_budget = if with_jphi_operator_budget && gs_ready && hagenow_map!==nothing && continuous_model &&
                    hasproperty(flux_numeric_data,:pf_native_Br_T) &&
                    hasproperty(flux_numeric_data,:pf_native_Bz_T)
                budget=_ccp_native_jphi_operator_budget_kernel_v1(
                    Raxis=Raxis,Zaxis=Zaxis,Dr=Dr,Dz=Dz,psi_plasma_mat=psi_mat,psi_interp=psi_interp,
                    pf_native_Br_T=flux_numeric_data.pf_native_Br_T,pf_native_Bz_T=flux_numeric_data.pf_native_Bz_T,
                    lcfs_dynamic_geometry_data=lcfs_dynamic_geometry_data,gs_operator=gs_operator,
                    gs_source_operator=gs_source_operator,core_ids=core_ids,nz=nz,
                    mu0=Float64(law.mu0_N_per_A2),native_Jphi=native_Jphi,
                    profile_law_Jphi=profile_law_Jphi,toroidal=toroidal,
                    accepted_source_Jphi=accepted_source_Jphi,area_weight_m2=core_area)
                (status=:evaluated_signed_native_Jphi_operator_budget,
                    comparison_native_ids=budget.comparison_native_ids,core_sample_count=length(budget.comparison_native_ids),row_order=:accepted_core_native_support_order,
                    units=:A_per_m2,primitive_flux_source=:same_state_plasma_spline_nodes,
                    PF_source=:same_state_exact_PF_potential_jet,
                    GS4_operator_source=:external_FreeGS_A4h_provenance_and_difference_diagnostic_only,
                    GS4_operator_native_ids=budget.GS4_operator_native_ids,
                    current_operator_model_id=gs_operator.model_id,
                    GS4_operator_has_boundary_equation_rows=false,
                    GS4_boundary_equations=:enforced_by_existing_later_global_residual,
                    candidate_profile_current=:same_state_profile_span_GS4_law,
                    GS4_residual_current_equivalent_definition=:A4h_psi_plus_mu0_R_Jprofile_divided_by_mu0_R,
                    outer_H512_provider_interface=:artifacts_hagenow_source_response_plus_freegs_hagenow_source_metadata,
                    outer_H512_provider_status=hagenow_source_H===nothing ? :typed_absent : hagenow_full_source_validation,
                    outer_H512_required_boundary_native_ids=copy(hagenow_map.boundary_native_ids),
                    outer_H512_required_same_state_inputs=(:plasma_psi,:Jtor,:PF_currents),
                    outer_H512_not_part_of_A4h_or_signed_budget=true,
                    profile_normalization_row_count=normalization_rows,
                    Jphi_native_minus_accepted_GS4_A_per_m2=budget.target,
                    state_field_reconstruction_residual_A_per_m2=budget.state_field_reconstruction_residual,
                    PF_sampled_curl_minus_continuous_jet_A_per_m2=budget.pf_sampled_minus_continuous_jet,
                    plasma_spline_nodal_curl_minus_continuous_jet_A_per_m2=budget.plasma_spline_nodal_minus_continuous_jet,
                    GS4_operator_minus_continuous_primitive_jet_A_per_m2=budget.gs4_operator_minus_continuous_primitive_jet,
                    GS4_operator_minus_candidate_profile_Jphi_A_per_m2=budget.gs4_operator_minus_candidate_profile,
                    GS4_residual_current_equivalent_A_per_m2=budget.gs4_residual_current_equivalent,
                    candidate_profile_minus_accepted_source_Jphi_A_per_m2=budget.candidate_profile_minus_accepted_source,
                    GS4_operator_minus_accepted_source_A_per_m2=budget.gs4_operator_minus_accepted_source,
                    signed_budget_sum_A_per_m2=budget.signed_budget_sum,
                    signed_budget_closure_error_A_per_m2=budget.budget_closure_error,
                    PF_continuous_jet_Jphi_A_per_m2=budget.pf_continuous,
                    plasma_spline_continuous_jet_Jphi_A_per_m2=budget.plasma_continuous,
                    GS4_A4h_implied_Jphi_A_per_m2=budget.gs4_current,
                    plasma_psi_hessian_RR_RZ_ZZ_Wb_per_rad_m2=budget.hessian_core,
                    H_RR_map_size=budget.H_RR_map_size,H_ZZ_map_size=budget.H_ZZ_map_size,
                    A4h_size=budget.A4h_size,A4h_nnz=budget.A4h_nnz,
                    budget_is_diagnostic_only=true,no_global_rows_added=true,physical_validation=false)
            else
                (status=:typed_absent,
                    reason=with_jphi_operator_budget ? :absolute_PF_plasma_primitive_and_GS4_operator_required : :operator_budget_opt_in_required,
                    comparison_native_ids=copy(core_ids),units=:A_per_m2,
                    outer_H512_provider_interface=:artifacts_hagenow_source_response_plus_freegs_hagenow_source_metadata,
                    outer_H512_provider_status=hagenow_source_H===nothing ? :typed_absent : hagenow_full_source_validation,
                    outer_H512_required_boundary_native_ids=gs_ready ? copy(hagenow_map.boundary_native_ids) : Int[],
                    outer_H512_required_same_state_inputs=(:plasma_psi,:Jtor,:PF_currents),
                    global_topology_closed=false,physical_validation=false)
            end
            native_curl_current_diagnostic=(status=:evaluated_full_native_axisymmetric_spline_curl_current,
                native_ids=1:n,native_node_order=:native_R_then_Z,
                current_cylindrical_A_per_m2=native_curl_current,
                component_order=(:R,:phi,:Z),row_order=:native_node_major_interleaved_R_phi_Z,
                operator=continuous_model ? :continuous_total_psi_spline_gradient_hessian_plus_profile_F_lift :
                    :axisymmetric_curl_of_profile_F_lift_on_accepted_plasma_domain_and_native_BrBz,
                current_operator_model_id=continuous_model ? gs_operator.model_id : :native_BrBz_discrete_curl_legacy_model,
                B_source=:same_candidate_full_native_state_Br_Bphi_Bz,
                common_field_scope=:accepted_plasma_domain_only,
                outside_domain_profile_relation=:native_P_clamped_to_Fvac_while_LCFS_P_is_unclamped,
                relation_to_LCFS_canonical_F=:shared_profile_F_lift_only_on_accepted_plasma_domain,
                jacobian=curl_jacobian,
                jacobian_row_order=:native_node_major_interleaved_R_phi_Z,
                jacobian_columns=:full_state_Br_Bphi_Bz_psi_profile_v_A_B,
                Jphi_source_comparison_scope=:accepted_core_native_support_only,
                accepted_source_native_ids=copy(core_ids),
                native_Jphi_operator_budget=native_Jphi_operator_budget,
                curl_Jphi_core_A_per_m2=native_Jphi[core_ids],
                candidate_GS4_profile_Jphi_core_A_per_m2=profile_law_Jphi,
                candidate_profile_minus_accepted_GS4_Jphi_A_per_m2=profile_minus_accepted_Jphi,
                curl_minus_candidate_profile_Jphi_A_per_m2=curl_minus_profile_Jphi,
                accepted_GS4_source_Jphi_core_A_per_m2=accepted_source_Jphi,
                curl_minus_accepted_GS4_source_Jphi_A_per_m2=curl_minus_accepted_Jphi,
                ip_comparison=(quadrature=:accepted_native_RZ_trapezoid_on_core_cut,
                    curl_Jphi_integral_A=curl_Ip_trapezoid,
                    accepted_GS4_source_integral_A=accepted_source_Ip_trapezoid,
                    source_reported_trapezoid_A=support.current_integral_trapezoid_A,
                    solver_plasma_Ip_A=support.solver_plasma_current_A,
                    curl_minus_source_trapezoid_A=curl_Ip_trapezoid-support.current_integral_trapezoid_A,
                    curl_minus_solver_Ip_A=curl_Ip_trapezoid-support.solver_plasma_current_A,
                    no_additional_Ip_equation=true),
                physical_return_current_claim=false,extra_solver_rows=0,
                global_topology_closed=false,physical_validation=false)
            all(isfinite,native_curl_current) && all(isfinite,curl_minus_profile_Jphi) &&
                all(isfinite,curl_minus_accepted_Jphi) && isfinite(curl_Ip_trapezoid) ||
                throw(ArgumentError("full-native state curl current diagnostic is nonfinite"))
            native_curl_current_diagnostic
        else
            (status=:typed_absent,reason=:explicit_full_curl_opt_in_required,
                native_Jphi_operator_budget=(status=:typed_absent,
                    reason=with_jphi_operator_budget ? :full_native_curl_opt_in_required : :operator_budget_opt_in_required,
                    outer_H512_provider_interface=:artifacts_hagenow_source_response_plus_freegs_hagenow_source_metadata,
                    outer_H512_provider_status=hagenow_source_H===nothing ? :typed_absent : hagenow_full_source_validation,
                    outer_H512_required_boundary_native_ids=gs_ready ? copy(hagenow_map.boundary_native_ids) : Int[],
                    outer_H512_required_same_state_inputs=(:plasma_psi,:Jtor,:PF_currents),
                    global_topology_closed=false,physical_validation=false),
                jacobian=:typed_absent,extra_solver_rows=0,
                global_topology_closed=false,physical_validation=false)
        end
        face_map=poloidal_current_face_map(x)
        mhd_comparison=if region===nothing
            (status=:typed_absent,reason=:existing_native_mhd_region_not_supplied)
        else
            # This consumer gathers from physical_x, decoded before this block.
            mapping=regional_mhd_dof_map_impl(region;
                physical_state_already_decoded=true);gather=mapping.global_dofs
            native_ids=collect(region.grid_coverage.node_native_ids)
            core_position=Dict(k=>j for (j,k) in enumerate(core_ids))
            center_ids=Int[];mhd_phi=Float64[];profile_phi=Float64[]
            mr=Int[];mc=Int[];mv=Float64[];dr=Int[];dc=Int[];dvj=Float64[]
            for (row,stencil) in enumerate(region.local_stencils)
                local_state=Float64[];local_points=Tuple{Float64,Float64}[]
                local_global=Int[]
                for node in stencil
                    base=4(node-1)
                    append!(local_state,physical_x[gather[base+1:base+4]])
                    push!(local_points,region.coordinates_m[node])
                    push!(local_global,native_ids[node])
                end
                holdout=_ccp_axisymmetric_mhd_stencil(local_state,local_points,law.mu0_N_per_A2)
                center=local_global[1];position=get(core_position,center,0)
                position>0 || throw(ArgumentError("regional MHD center is outside core current support"))
                push!(center_ids,center);push!(mhd_phi,holdout.current_cylindrical_A_m2[2])
                push!(profile_phi,toroidal[center])
                minus_R,plus_R,minus_Z,plus_Z=stencil[2],stencil[3],stencil[4],stencil[5]
                dR=(region.coordinates_m[plus_R][1]-region.coordinates_m[minus_R][1])
                dZ=(region.coordinates_m[plus_Z][2]-region.coordinates_m[minus_Z][2])
                for (node,field,value) in ((minus_Z,2,-1/(law.mu0_N_per_A2*dZ)),
                        (plus_Z,2,1/(law.mu0_N_per_A2*dZ)),
                        (minus_R,4,1/(law.mu0_N_per_A2*dR)),
                        (plus_R,4,-1/(law.mu0_N_per_A2*dR)))
                    push!(mr,row);push!(mc,gather[4(node-1)+field]);push!(mv,value)
                end
                psi_column=4center
                shape=_ccp_full_native_profile_shape(x[psi_column],profile_span.axis,profile_span.boundary)
                q=shape.q;coefficient=gs_coefficient(x,center)
                push!(dr,row);push!(dc,psi_column);push!(dvj,-2q*coefficient/profile_span.delta)
                if dynamic_profile_span
                    for (column,dshape) in zip(span_columns,(shape.shape_axis,shape.shape_boundary))
                        push!(dr,row);push!(dc,column);push!(dvj,-coefficient*dshape)
                    end
                end
                if vary_profile_coefficients
                    push!(dr,row);push!(dc,coefficient_columns[1]);
                    push!(dvj,-q^2*R[center]/law.Raxis_m)
                    push!(dr,row);push!(dc,coefficient_columns[2]);
                    push!(dvj,-q^2*law.Raxis_m/R[center])
                end
            end
            curl_jacobian=sparse(mr,mc,mv,length(center_ids),ndof)
            difference_jacobian=curl_jacobian+sparse(dr,dc,dvj,length(center_ids),ndof)
            difference=mhd_phi-profile_phi
            (status=:compared_existing_centered_mhd_and_profile_Jphi,
                native_center_ids=center_ids,centered_MHD_curl_Jphi_A_m2=mhd_phi,
                continuous_profile_gs_current_Jphi_A_m2=profile_phi,
                centered_minus_profile_Jphi_A_m2=difference,
                centered_curl_jacobian=curl_jacobian,
                centered_minus_profile_jacobian=difference_jacobian,
                row_role=:existing_MHD_centered_curl_holdout,extra_solver_rows=0,
                independent_discretization_difference=true)
        end
        result=(status=:evaluated_native_core_constitutive_current,
            candidate_hash=d.candidate_hash,context_hash=d.context_hash,
            upstream_output_hash=d.upstream_output_hash,
            native_ids=copy(core_ids),current_cylindrical_A_m2=current,
            component_order=(:R,:phi,:Z),node_order=:native_core_R_then_Z,
            row_role=:constitutive_current_observation,row_units=:A_per_m2,
            row_scaling=:unscaled_physical_units,
            # rows/cols/entries are the constitutive physical-Bphi block.
            # The separate native curl jrows/jcols/jvalues are already Dy
            # and leave this function through curl_jacobian without pullback.
            jacobian=_ccp_full_native_physical_row_pullback(state_domain,x,
                sparse(rows,cols,entries,length(current),ndof)),
            poloidal_face_flux=face_map,mhd_Jphi_holdout=mhd_comparison,
            plasma_Jphi_periodic_phi_ring=true,
            PF_and_TF_sources_remain_independent=true,
            scope=:fixed_mask_axis_boundary_core_profile_current,
            curl_current_independently_verified=false,current_normal_trace=:typed_absent,
            exterior_current_vector=:typed_absent,extra_solver_rows=0,
            missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,global_topology_closed=false)
        merge(result,(full_native_state_curl_current=native_curl_current_diagnostic,))
    end
    regional_mhd_dof_map_impl=function(region;physical_state_already_decoded=false)
        physical_state_already_decoded isa Bool || throw(ArgumentError(
            "physical-state regional gather permission must be Boolean"))
        _ccp_full_native_D_coordinate(state_domain) && !physical_state_already_decoded &&
            throw(ArgumentError(
                "integer-only regional MHD gather cannot represent D coordinates; nonlinear physical-field map required"))
        region isa FreeGSAxisymmetricMHDRegionV4 ||
            throw(ArgumentError("native full-state gather requires the existing MHD region"))
        _ccp_validate_axisymmetric_region(region)
        region.candidate_hash==d.candidate_hash && region.context_hash==d.context_hash &&
            region.upstream_output_hash==d.upstream_output_hash ||
            throw(ArgumentError("regional gather source differs from full native state"))
        coverage=region.grid_coverage
        hasproperty(coverage,:node_native_ids) && hasproperty(coverage,:grid_shape) &&
            coverage.grid_shape==(nr,nz) ||
            throw(ArgumentError("regional gather requires the same actual native grid"))
        ids=collect(coverage.node_native_ids)
        length(ids)==length(region.coordinates_m) && length(unique(ids))==length(ids) ||
            throw(ArgumentError("regional native-node inventory is invalid"))
        gather=Int[];sizehint!(gather,4length(ids))
        for (local_node,k) in enumerate(ids)
            k isa Integer && 1<=k<=n && mask[k] && pressure_dofs[k]>0 ||
                throw(ArgumentError("regional gather requested unsupported pressure support"))
            region.coordinates_m[local_node]==(R[k],Z[k]) ||
                throw(ArgumentError("regional gather native-node order or coordinates differ"))
            append!(gather,(pressure_dofs[k],4k-3,4k-2,4k-1))
        end
        length(gather)==length(region.initial_state) &&
            physical_initial[gather]==collect(region.initial_state) ||
            throw(ArgumentError("regional gather initial state differs from its accepted source"))
        (global_dofs=gather,regional_node_native_ids=ids,
            candidate_hash=region.candidate_hash,region_hash=region.region_hash,
            upstream_output_hash=region.upstream_output_hash,
            field_coordinate_scope=:decoded_physical_B_fields,
            source_state_coordinate_id=state_domain.toroidal_coordinate,
            physical_state_decode_applied=physical_state_already_decoded ||
                !_ccp_full_native_D_coordinate(state_domain),
            regional_equation_ids=collect(_ccp_axisymmetric_region_ids(region)),
            row_role=:independent_centered_cross_force_and_divB_holdout,
            row_units=_CCP_AXISYMMETRIC_ROW_UNITS,row_scaling=:unscaled_physical_units,
            extra_solver_rows=0,missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,
            global_topology_closed=false)
    end

    # Other integer-only consumers retain the original D-coordinate rejection.
    regional_mhd_dof_map=function(region)
        regional_mhd_dof_map_impl(region;physical_state_already_decoded=false)
    end

    # Retain only 1-D point spline factors (four 64-by-129 matrices per mode),
    # never their 64-by-native-grid tensor products. Those tensor products are
    # evaluated directly below and would otherwise persist in both caches.
    lcfs_primary_tables=Ref{Any}(nothing);lcfs_oracle_tables=Ref{Any}(nothing)
    function lcfs_tables(independent)
        cache=independent ? lcfs_oracle_tables : lcfs_primary_tables
        cache[]!==nothing && return cache[]
        points=collect(d.coordinates_m);length(points)==64 || throw(ArgumentError("LCFS support must have 64 source points"))
        rr=first.(points);zz=last.(points)
        rw=independent ? _ccp_native_spline_point_weights_oracle(Raxis,rr) :
            _ccp_native_spline_point_weights(Raxis,Dr,rr)
        zw=independent ? _ccp_native_spline_point_weights_oracle(Zaxis,zz) :
            _ccp_native_spline_point_weights(Zaxis,Dz,zz)
        cache[]=(rw=rw,zw=zw,R=rr)
    end
    # Same-state moving LCFS geometry for the existing 64-ray source contract.
    # This intentionally stops before profile/current rows: their accepted
    # per-point source records are tied to d.coordinates_m and cannot be reused
    # at moved points.
    function lcfs_flux_value(state;independent=false)
        gs_ready || return (status=:typed_absent,reason=:absolute_native_plasma_flux_unavailable,
            missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,global_topology_closed=false)
        x=checked_state(state);w=lcfs_tables(independent)
        psi=x[4:4:4n]
        absolute_field_model=native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1
        plasma=absolute_field_model ?
            _ccp_full_native_plasma_nodes(x,lcfs_dynamic_geometry_data,component_geometry_model_id) :
            plasma_reference+(psi-anchor[4:4:4n])
        geometry_psi=zeros(64);br_spline=zeros(64);bz_spline=zeros(64)
        for a in 1:64,i in 1:nr,j in 1:nz
            k=(i-1)*nz+j
            wr=w.rw.value[a,i];wrd=w.rw.derivative[a,i]
            wz=w.zw.value[a,j];wzd=w.zw.derivative[a,j]
            geometry_psi[a]+=wr*wz*(absolute_field_model ? plasma[k] : psi[k])
            br_spline[a]+=wr*wzd*plasma[k]
            bz_spline[a]+=wrd*wz*plasma[k]
        end
        br=-br_spline./w.R
        bz=bz_spline./w.R
        if absolute_field_model
            for a in 1:64
                r,z=d.coordinates_m[a]
                pf=_ccp_full_native_exact_pf_jet(lcfs_dynamic_geometry_data,r,z)
                geometry_psi[a]+=pf.psi
                br[a]+=-pf.gradient[2]/r
                bz[a]+=pf.gradient[1]/r
            end
        else
            br .+= first.(d.coil_field_RZ_T)
            bz .+= last.(d.coil_field_RZ_T)
        end
        # Only B.n is consumed from the existing kernel. Its p/F/traction
        # outputs are neither mapped equations nor returned as this map's results.
        local_state=collect(d.initial_state)
        local_state[2:4:end].=br;local_state[4:4:end].=bz
        local_normal=independent ?
            _ccp_axisymmetric_lcfs_trace_oracle(local_state,d.normals_RZ,d.profile_boundary_pressure_Pa,d.mu0_N_per_A2) :
            _ccp_axisymmetric_lcfs_trace_values(local_state,d.normals_RZ,d.profile_boundary_pressure_Pa,d.mu0_N_per_A2)
        residual=local_normal.residual[1:2:end]
        # Build the sparse CSC outputs directly. Each psi column has a sorted
        # fixed row pattern; no full-size triplet vectors overlap the CSC data.
        field_colptr=Vector{Int}(undef,ndof+1);normal_colptr=Vector{Int}(undef,ndof+1)
        for c in 0:ndof
            prior=min(n,fld(c,4))
            field_colptr[c+1]=1+192prior
            normal_colptr[c+1]=1+64prior
        end
        field_rowval=Vector{Int}(undef,192n);field_nzval=Vector{Float64}(undef,192n)
        normal_rowval=Vector{Int}(undef,64n);normal_nzval=Vector{Float64}(undef,64n)
        for k in 1:n
            i=cld(k,nz);j=mod1(k,nz)
            fbase=192(k-1);nbase=64(k-1)
            for a in 1:64
                wr=w.rw.value[a,i];wrd=w.rw.derivative[a,i]
                wz=w.zw.value[a,j];wzd=w.zw.derivative[a,j]
                dr=-wr*wzd/w.R[a];dz=wrd*wz/w.R[a]
                fslot=fbase+3(a-1);frow=3(a-1)
                field_rowval[fslot+1]=frow+1;field_nzval[fslot+1]=wr*wz
                field_rowval[fslot+2]=frow+2;field_nzval[fslot+2]=dr
                field_rowval[fslot+3]=frow+3;field_nzval[fslot+3]=dz
                normal_rowval[nbase+a]=a
                normal_nzval[nbase+a]=d.normals_RZ[a][1]*dr+d.normals_RZ[a][2]*dz
            end
        end
        field_jacobian=SparseArrays.SparseMatrixCSC{Float64,Int}(192,ndof,
            field_colptr,field_rowval,field_nzval)
        normal_jacobian=SparseArrays.SparseMatrixCSC{Float64,Int}(64,ndof,
            normal_colptr,normal_rowval,normal_nzval)
        fields=[v for a in 1:64 for v in (geometry_psi[a],br[a],bz[a])]
        all(isfinite,fields) && all(isfinite,residual) && all(isfinite,field_nzval) && all(isfinite,normal_nzval) ||
            throw(ArgumentError("LCFS changing flux/field response became nonfinite"))
        result=(status=:evaluated_fixed_LCFS_absolute_flux_and_poloidal_field,
            candidate_hash=d.candidate_hash,upstream_output_hash=d.upstream_output_hash,
            trace_hash=t.trace_hash,coordinates_RZ_m=collect(d.coordinates_m),normals_RZ=collect(d.normals_RZ),
            fields=fields,field_order=(:geometry_psi,:Br,:Bz),field_jacobian=field_jacobian,
            residual=residual,jacobian=normal_jacobian,residual_units=:T,
            row_role=:existing_LCFS_normal_B_holdout,extra_solver_rows=0,
            geometry_psi_scope=:total_native_grid_spline_at_fixed_accepted_LCFS,
            Bpol_scope=:absolute_plasma_spline_plus_fixed_PF_field,
            pressure_trace_state_map=:typed_absent,toroidal_field_trace_state_map=:typed_absent,
            current_normal_trace=:typed_absent,fixed_geometry=true,fixed_PF_currents=true,
            missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,global_topology_closed=false,
            physical_validation=false)
        absolute_field_model ? merge(result,(
            geometry_psi_scope=:source_fixed_coordinates_plasma_spline_plus_exact_PF_psi_holdout,
            Bpol_scope=:source_fixed_coordinates_plasma_spline_plus_exact_PF_field_holdout,
            native_field_model_id=native_field_model_id,
            interface_geometry_scope=:fixed_source_coordinates_not_moving_LCFS_closure)) : result
    end
    pressure_domain_view=function(state)
        pressure_domain===nothing && return (status=:typed_absent,reason=:no_authored_pressure_domain,
            pressure_Pa=nothing,jacobian=nothing)
        pressure_geometry_map.status===:present || return (status=:typed_absent,
            reason=pressure_geometry_map.reason,pressure_Pa=nothing,jacobian=nothing,
            geometry_map=pressure_geometry_map)
        pressure_geometry_map.pressure_dof_support_status===:present ||
            return (status=:typed_absent,reason=:authored_lcfs_region_disagrees_with_native_pressure_dof_support,
                pressure_Pa=nothing,jacobian=nothing,geometry_map=pressure_geometry_map)
        x=checked_state(state)
        values=fill(pressure_domain.exterior_pressure_pa,n)
        if dynamic_profile_span
            geometry=_ccp_full_native_dynamic_geometry(lcfs_dynamic_geometry_data,x;
                model_id=_ccp_native_geometry_model_id(native_field_model_id))
            geometry.status===:evaluated_dynamic_LCFS_geometry || return (status=geometry.status,
                reason=geometry.reason,pressure_Pa=nothing,jacobian=nothing,geometry_map=pressure_geometry_map,
                dynamic_geometry=geometry,solver_rows_added=0,global_topology_closed=false,
                physical_validation=false)
            span=_ccp_full_native_profile_span(state_domain,x);u=profile_coefficients(x)[1]
            profile=profile_evaluate(x);inside_ids=findall(mask);outside_ids=findall(!,mask)
            profile_pressure=fill(pressure_domain.exterior_pressure_pa,n)
            for k in inside_ids
                shape=_ccp_full_native_profile_shape(geometry.candidate_total_psi_Wb_per_rad[k],
                    span.axis,span.boundary)
                profile_pressure[k]=u*shape.integral/law.Raxis_m
                values[k]=x[pressure_dofs[k]]
            end
            rows=copy(pressure_rows[inside_ids])
            jacobian=sparse(inside_ids,pressure_dofs[inside_ids],ones(Float64,length(inside_ids)),n,ndof)
            pressure_relation_jacobian=profile.jacobian[rows,:]
            pressure_relation_residual=profile.residual[rows]
            all(isfinite,profile_pressure) && all(isfinite,values) && all(isfinite,pressure_relation_residual) ||
                throw(ArgumentError("dynamic pressure-domain view became nonfinite"))
            return (status=:derived_same_state_dynamic_analytic_pressure_and_constrained_nodal_samples,
                pressure_Pa=values,profile_pressure_Pa=profile_pressure,jacobian=jacobian,
                dynamic_geometry=geometry,geometry_map=pressure_geometry_map,
                candidate_hash=d.candidate_hash,context_hash=d.context_hash,
                upstream_output_hash=d.upstream_output_hash,trace_hash=t.trace_hash,
                region_ids=(plasma=pressure_domain.plasma_region_id,vacuum=pressure_domain.vacuum_region_id),
                region_classification_rule=pressure_domain.classification_rule,
                interface_node_id=pressure_domain.interface_node_id,boundary_node_id=pressure_domain.boundary_node_id,
                native_node_ids=Tuple(1:n),plasma_native_node_ids=Tuple(inside_ids),
                exterior_native_node_ids=Tuple(outside_ids),pressure_dof_ids=Tuple(pressure_dofs[inside_ids]),
                pressure_row_ids=Tuple(rows),pressure_dof_to_existing_profile_row=Tuple(zip(pressure_dofs[inside_ids],rows)),
                pressure_row_residual=pressure_relation_residual,
                pressure_row_jacobian=pressure_relation_jacobian,
                pressure_row_scope=:existing_global_regional_pressure_constraint_p_minus_analytic_p_of_native_total_psi,
                continuous_pressure_field=:analytic_p_of_same_state_total_psi_with_dynamic_axis_boundary_and_u,
                nodal_pressure_dofs=:constrained_samples_of_continuous_analytic_pressure,
                exterior_pressure_scope=:authored_G1_vacuum_law,
                profile_endpoint_values=(axis=span.axis,boundary=span.boundary,delta=span.delta),
                profile_coefficient_values=(u=u,v=profile_coefficients(x)[2]),
                profile_endpoint_columns=span_columns,
                profile_coefficient_columns=(coefficient_columns[1],coefficient_columns[2]),
                endpoint_definition_residual=(x[span_columns[1]]-geometry.psi_axis_Wb_per_rad,
                    x[span_columns[2]]-geometry.psi_boundary_Wb_per_rad),
                region_id_by_native_node=pressure_geometry_map.region_id_by_native_node,
                dynamic_interface_coordinates_RZ_m=geometry.coordinates_RZ_m,
                dynamic_interface_normals_RZ=geometry.normals_RZ,
                dynamic_interface_surface_quadrature_m2=geometry.surface_quadrature_m2,
                dynamic_interface_ray_ids=Tuple(1:64),
                dynamic_interface_face_role=:dynamic_q_boundary_ray_intersections,
                dynamic_interface_rule=geometry.ray_rule,
                dynamic_mask_branch=:receipt_bound_native_flux_connected_core_mask_until_needs_rebuild,
                pressure_interface_to_native_region_relation=:dynamic_geometry_verified_existing_core_mask,
                pressure_interface_pressure_dof_map=:existing_nodal_profile_rows,
                pressure_cut_face_map=:not_required_for_declared_continuous_analytic_pressure_field,
                solver_rows_added=0,global_topology_closed=false,physical_validation=false)
        end
        rows=Int[];cols=Int[]
        for k in 1:n
            if pressure_geometry_map.native_role_inside[k]
                pressure_dofs[k]>0 || return (status=:typed_absent,
                    reason=:inside_pressure_dof_missing,pressure_Pa=nothing,jacobian=nothing)
                values[k]=x[pressure_dofs[k]];push!(rows,k);push!(cols,pressure_dofs[k])
            elseif pressure_dofs[k]!=0
                return (status=:typed_absent,reason=:outside_pressure_dof_present,
                    pressure_Pa=nothing,jacobian=nothing)
            end
        end
        jacobian=sparse(rows,cols,ones(Float64,length(rows)),n,ndof)
        (status=:derived_authored_fixed_geometry_pressure_view,
            pressure_Pa=values,jacobian=jacobian,geometry_map=pressure_geometry_map,
            plasma_region_id=pressure_domain.plasma_region_id,
            vacuum_region_id=pressure_domain.vacuum_region_id,
            interface_node_id=pressure_domain.interface_node_id,
            boundary_node_id=pressure_domain.boundary_node_id,
            exterior_pressure_Pa=pressure_domain.exterior_pressure_pa,
            exterior_pressure_scope=:authored_G1_vacuum_law,
            open_flux_policy=pressure_domain.open_flux_policy,
            solver_rows_added=0,global_topology_closed=false,physical_validation=false)
    end
    component_geometry_model_id=_ccp_native_geometry_model_id(native_field_model_id)
    lcfs_trace_identity=(missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,
        global_topology_closed=false,extra_solver_rows=0,physical_validation=false,
        candidate_hash=d.candidate_hash,context_hash=d.context_hash,
        upstream_output_hash=d.upstream_output_hash,trace_hash=t.trace_hash,
        fixed_geometry=true,fixed_PF_currents=true,fixed_source_mask=true)
    # Numerical/typed inputs only: no callback, closure or Ref enters global callback identity.
    lcfs_current_numeric_data=deepcopy((trace_identity=lcfs_trace_identity,
        state_domain=state_domain,profile_row_numeric_data=profile_numeric_data,
        lcfs_dynamic_geometry_data=lcfs_dynamic_geometry_data,
    source_data=(offgrid_source=d.offgrid_source,coordinates_m=d.coordinates_m,
            profile_boundary_pressure_Pa=d.profile_boundary_pressure_Pa),
        pressure_domain=pressure_domain,
        law=law,Raxis=copy(Raxis),Zaxis=copy(Zaxis),Dr=copy(Dr),Dz=copy(Dz),
        nr=nr,nz=nz,n=n,ndof=ndof,dynamic_profile_span=dynamic_profile_span,
        span_columns=span_columns,coefficient_columns=coefficient_columns,
        vary_profile_coefficients=vary_profile_coefficients,
        accepted_coefficients=accepted_coefficients,
        native_field_model_id=native_field_model_id,
        current_topology=declaration.current_topology,
        return_current_path=declaration.return_current_path))
    lcfs_F_B_numeric_data=(identity=lcfs_current_numeric_data.trace_identity,
        state_domain=lcfs_current_numeric_data.state_domain,
        geometry_data=lcfs_current_numeric_data.lcfs_dynamic_geometry_data,
        model_id=component_geometry_model_id,
        current_topology=declaration.current_topology,
        return_current_path=declaration.return_current_path)
    lcfs_plasma_trace_numeric_data=merge(lcfs_current_numeric_data,(lcfs_F_B_numeric_data=lcfs_F_B_numeric_data,))
    lcfs_pressure_trace_numeric_data=merge(lcfs_current_numeric_data,
        (pressure_geometry_map=pressure_geometry_map,gs_rows=gs_rows,model_id=component_geometry_model_id,gs_ready=gs_ready))
    function lcfs_profile_current_trace(state;with_jacobian=true,independent=false,pressure_only=false,
            dynamic_geometry=false,geometry_override=nothing)
        trace_identity=lcfs_current_numeric_data.trace_identity
        geometry_override===nothing || (dynamic_geometry && pressure_only) ||
            return merge(trace_identity,(status=:typed_absent,
                reason=:geometry_override_only_supported_for_dynamic_pressure_only_trace,
                pressure_status=:typed_absent,current_status=:typed_absent,
                current_normal_trace=:typed_absent,fields=nothing,residual=nothing,jacobian=nothing,
                fixed_geometry=false,fixed_source_mask=false,source_fields_reused=false,
                solver_rows_added=0,global_topology_closed=false,physical_validation=false))
        gs_ready || return merge(trace_identity,(status=:typed_absent,reason=:absolute_native_plasma_flux_unavailable))
        if native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 && !dynamic_geometry
            return merge(trace_identity,(status=:typed_absent,
                reason=:composite_native_field_model_requires_same_state_dynamic_geometry,
                pressure_status=:typed_absent,current_status=:typed_absent,
                current_normal_trace=:typed_absent,fields=nothing,residual=nothing,jacobian=nothing,
                fixed_geometry=false,fixed_source_mask=false,source_fields_reused=false,
                solver_rows_added=0,global_topology_closed=false,physical_validation=false))
        end
        if native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 &&
                dynamic_geometry && pressure_only && !dynamic_profile_span
            return merge(trace_identity,(status=:typed_absent,
                reason=:composite_pressure_only_requires_dynamic_profile_span,
                native_field_model_id=native_field_model_id,dynamic_geometry=true,
                pressure_only=true,dynamic_profile_span=false,
                pressure_status=:typed_absent,current_status=:not_evaluated_by_pressure_only_request,
                current_normal_trace=:not_evaluated_by_pressure_only_request,
                fields=nothing,residual=nothing,jacobian=nothing,
                fixed_geometry=false,fixed_source_mask=false,source_fields_reused=false,
                solver_rows_added=0,global_topology_closed=false,physical_validation=false))
        end
        if dynamic_profile_span && !dynamic_geometry
            return merge(trace_identity,(status=:typed_absent,
                reason=:dynamic_profile_span_offgrid_source_records_not_rebound,
                pressure_status=:typed_absent,current_status=:typed_absent,
                current_normal_trace=:typed_absent,fields=nothing,residual=nothing,jacobian=nothing,
                fixed_geometry=false,fixed_source_mask=true,source_fields_reused=false,
                dynamic_span_columns=span_columns,solver_rows_added=0))
        end
        if geometry_override!==nothing
            dynamic_profile_span || return merge(trace_identity,(status=:typed_absent,
                reason=:geometry_override_requires_dynamic_profile_span,
                dynamic_geometry=true,pressure_only=true,pressure_status=:typed_absent,
                current_status=:not_evaluated_by_pressure_only_request,
                current_normal_trace=:not_evaluated_by_pressure_only_request,
                fields=nothing,residual=nothing,jacobian=nothing,
                fixed_geometry=false,fixed_source_mask=false,source_fields_reused=false,
                solver_rows_added=0,global_topology_closed=false,physical_validation=false))
            return _ccp_full_native_dynamic_lcfs_pressure_trace(
                lcfs_pressure_trace_numeric_data,state;geometry_override=geometry_override,
                with_jacobian=with_jacobian)
        end
        if native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 &&
                dynamic_geometry && !pressure_only
            composite_current_data=merge(lcfs_current_numeric_data,
                (lcfs_F_B_numeric_data=lcfs_F_B_numeric_data,))
            return _ccp_full_native_dynamic_composite_lcfs_current_trace(
                composite_current_data,state;with_jacobian=with_jacobian)
        end
        if dynamic_geometry
            geometry=_ccp_full_native_dynamic_geometry(lcfs_dynamic_geometry_data,state;
                model_id=component_geometry_model_id)
            geometry.status===:evaluated_dynamic_LCFS_geometry || return merge(trace_identity,
                (status=geometry.status,reason=geometry.reason,dynamic_geometry=geometry,
                 pressure_status=:typed_absent,current_status=:typed_absent,
                 current_normal_trace=:typed_absent,fields=nothing,residual=nothing,jacobian=nothing,
                 fixed_geometry=false,fixed_source_mask=false,source_fields_reused=false,
                 global_topology_closed=false))
            if pressure_only && dynamic_profile_span
                return _ccp_full_native_dynamic_lcfs_pressure_trace(
                    lcfs_pressure_trace_numeric_data,state;geometry_override=geometry,with_jacobian=with_jacobian)
            end
            return merge(trace_identity,(status=:typed_absent,
                reason=:dynamic_geometry_only_profile_current_source_rebind_pending,
                dynamic_geometry=geometry,pressure_status=:typed_absent,
                current_status=:typed_absent,current_normal_trace=:typed_absent,
                fields=nothing,residual=nothing,jacobian=nothing,
                fixed_geometry=false,fixed_source_mask=true,source_fields_reused=false,solver_rows_added=0,
                global_topology_closed=false,physical_validation=false))
        end
        source=d.offgrid_source
        all(a->a.status===:present,source) || return merge(trace_identity,
            (status=:typed_absent,reason=:offgrid_source_not_emitted,
             source_reasons=Tuple(a.reason for a in source)))
        law.alpha_m==1 && law.alpha_n==2 || return merge(trace_identity,
            (status=:typed_absent,reason=:offgrid_profile_exponents_unsupported))
        x=checked_state(state);u,v=profile_coefficients(x);w=lcfs_tables(independent)
        plasma=plasma_reference+(x[4:4:4n]-anchor[4:4:4n])
        point_psi=zeros(64);point_R=zeros(64);point_Z=zeros(64)
        for a in 1:64,i in 1:nr,j in 1:nz
            value=plasma[(i-1)*nz+j]
            point_psi[a]+=w.rw.value[a,i]*w.zw.value[a,j]*value
            point_R[a]+=w.rw.derivative[a,i]*w.zw.value[a,j]*value
            point_Z[a]+=w.rw.value[a,i]*w.zw.derivative[a,j]*value
        end
        fields=fill(NaN,64,5);partials=Array{Float64}(undef,3,5,64)
        residual=Vector{Float64}(undef,192);actual_psi=zeros(64);fpol=zeros(64)
        pressure_residual=Vector{Float64}(undef,64);pressure_q_derivative=Vector{Float64}(undef,64)
        pressure_u_derivative=Vector{Float64}(undef,64)
        current_ready=all(a->a.coil_psi_gradient_status===:present,source)
        for a in 1:64
            s=source[a];actual_psi[a]=point_psi[a]+s.coil_psi_wb_per_rad
            span=s.eq_psi_boundary_wb_per_rad-s.eq_psi_axis_wb_per_rad
            q=(actual_psi[a]-s.eq_psi_axis_wb_per_rad)/span
            pressure=_ccp_lcfs_profile_pressure(q,u,s,law)
            pressure_residual[a]=pressure.pressure-d.profile_boundary_pressure_Pa
            pressure_q_derivative[a]=pressure.dp_dq
            pressure_u_derivative[a]=pressure.dp_du
            # Do not substitute a zero coil gradient into a current/Jn trace.
            if current_ready && !pressure_only
                cg=s.coil_psi_gradient_RZ_Wb_per_rad_m
                point=_ccp_lcfs_offgrid_profile_point(q,point_R[a]+cg[1],point_Z[a]+cg[2],
                    u,v,w.R[a],d.normals_RZ[a],s,law;compute_current=true)
                fields[a,1:5].=point.values;fpol[a]=point.fpol;partials[:,:,a].=point.partials
                residual[3a-2]=fields[a,1]-d.profile_boundary_pressure_Pa
                residual[3a-1]=w.R[a]*fields[a,2]-law.fvac_T_m
                residual[3a]=fields[a,5]
            else
                point=_ccp_lcfs_offgrid_profile_point(q,0.0,0.0,u,v,w.R[a],
                    d.normals_RZ[a],s,law;compute_current=false)
                fields[a,1:2].=point.values[1:2];fpol[a]=point.fpol
            end
        end
        common=merge(trace_identity,(profile_pressure_Pa=fields[:,1],Bphi_T=fields[:,2],
            fpol_T_m=fpol,psi_physical_wb_per_rad=actual_psi,
        pressure_scope=:offgrid_profile_evaluation_not_exterior_native_pressure,
        pressure_field_definition=:same_source_profile_p_of_actual_total_psi,
            pressure_state_representation=:constrained_native_nodal_samples,
            pressure_dof_interpolation=:not_used,
            pressure_trace_scope=:fixed_actual_source_lcfs_64_points,
            pressure_residual=pressure_residual,pressure_row_count=64,
            pressure_trace_extra_solver_rows=0,pressure_status=:evaluated_source_profile_pressure,
            mask_matches_refreshed_current_support=Tuple(s.mask_matches_refreshed_current_support for s in source),
            source_reference=source))
        pressure_jacobian=nothing
        if with_jacobian && (!current_ready || pressure_only)
            pr=Int[];pc=Int[];pv=Float64[]
            for node in 1:n
                col=4node;i=cld(node,nz);j=mod1(node,nz)
                for a in 1:64
                    span=source[a].eq_psi_boundary_wb_per_rad-source[a].eq_psi_axis_wb_per_rad
                    value=pressure_q_derivative[a]*w.rw.value[a,i]*w.zw.value[a,j]/span
                    iszero(value) || (push!(pr,a);push!(pc,col);push!(pv,value))
                end
            end
            if vary_profile_coefficients
                col=coefficient_columns[1]
                for a in 1:64
                    value=pressure_u_derivative[a]
                    iszero(value) || (push!(pr,a);push!(pc,col);push!(pv,value))
                end
            end
            all(isfinite,pv) || throw(ArgumentError("LCFS pressure-only Jacobian became nonfinite"))
            pressure_jacobian=sparse(pr,pc,pv,64,ndof)
        end
        pressure_only && return merge(common,(status=:evaluated_fixed_LCFS_pressure_only,
            reason=:explicit_pressure_only_request,
            current_status=current_ready ? :not_evaluated_by_pressure_only_request : :typed_absent,
            current_normal_trace=current_ready ? :not_evaluated_by_pressure_only_request : :typed_absent,
            gradient_reasons=current_ready ? nothing : Tuple(s.coil_psi_gradient_reason for s in source),
            pressure_jacobian=pressure_jacobian,residual=nothing,jacobian=nothing,
            fields=nothing,field_order=:typed_absent,current_jacobian=:typed_absent,
            physical_validation=false,global_topology_closed=false))
        current_ready || return merge(common,(status=:typed_absent,
            reason=:exact_coil_flux_gradient_unavailable,current_status=:typed_absent,
            current_normal_trace=:typed_absent,
            gradient_reasons=Tuple(s.coil_psi_gradient_reason for s in source),
            pressure_jacobian=pressure_jacobian,residual=nothing,jacobian=nothing))
        jac=nothing
        if with_jacobian
            # Direct CSC: one allocation, no 192*n dense matrix or triplet copy.
            colptr=Vector{Int}(undef,ndof+1);rows=Int[];vals=Float64[]
            sizehint!(rows,192n+384);sizehint!(vals,192n+384)
            for col in 1:ndof
                colptr[col]=length(vals)+1
                if col<=4n && mod(col,4)==0
                    k=div(col,4);i=cld(k,nz);j=mod1(k,nz)
                    for a in 1:64
                        S=w.rw.value[a,i]*w.zw.value[a,j]
                        SR=w.rw.derivative[a,i]*w.zw.value[a,j]
                        SZ=w.rw.value[a,i]*w.zw.derivative[a,j]
                        span=source[a].eq_psi_boundary_wb_per_rad-source[a].eq_psi_axis_wb_per_rad
                        for r in 1:3
                            value=partials[r,1,a]*S/span+partials[r,2,a]*SR+partials[r,3,a]*SZ
                            iszero(value) || (push!(rows,3a-3+r);push!(vals,value))
                        end
                    end
                elseif vary_profile_coefficients && col in coefficient_columns
                    q=col==coefficient_columns[1] ? 4 : 5
                    for a in 1:64,r in 1:3
                        value=partials[r,q,a]
                        iszero(value) || (push!(rows,3a-3+r);push!(vals,value))
                    end
                end
            end
            colptr[end]=length(vals)+1
            all(isfinite,vals) || throw(ArgumentError("LCFS profile/current Jacobian became nonfinite"))
            jac=SparseMatrixCSC(192,ndof,colptr,rows,vals)
            pressure_jacobian=jac[1:3:192,:]
        end
        merge(common,(status=:evaluated_fixed_LCFS_offgrid_profile_and_curl_Bphi,
            current_status=:evaluated,
            fields=fields,field_order=(:profile_pressure_Pa,:Bphi_T,:JR_A_per_m2,:JZ_A_per_m2,:Jn_A_per_m2),
            residual=residual,jacobian=jac,residual_order=(:pressure_minus_boundary,:R_Bphi_minus_fvac,:Jn),
            current_scope=:curl_of_actual_masked_Bphi_using_true_flux_gradient,
            normal_scope=:fixed_accepted_LCFS_normal_no_phi_component,
            current_normal_trace=:evaluated_holdout,pressure_jacobian=pressure_jacobian))
    end

    evaluate=function(state)
        x=checked_state(state);profile=profile_evaluate(x);gs=gs_block(x)
        normalization=normalization_block(x);span_rows=_ccp_full_native_dynamic_span_equations(state_domain,x)
        hagenow=hagenow_block(x);flux=_ccp_full_native_flux_values(flux_numeric_data,x)
        full_residual=dynamic_profile_span ?
            vcat(profile.residual,flux,gs.residual,normalization.residual[1:1],span_rows.residual,
                normalization.residual[2:2],hagenow.residual) :
            vcat(profile.residual,flux,gs.residual,normalization.residual,hagenow.residual)
        full_jacobian=dynamic_profile_span ?
            vcat(profile.jacobian,flux_jacobian,gs.jacobian,normalization.jacobian[1:1,:],
                span_rows.jacobian,normalization.jacobian[2:2,:],hagenow.jacobian) :
            vcat(profile.jacobian,flux_jacobian,gs.jacobian,normalization.jacobian,hagenow.jacobian)
        evaluated=(status=native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
                :evaluated_full_native_absolute_plasma_spline_exact_PF_field_and_Hagenow_boundary :
                :evaluated_full_native_profile_fixed_PF_flux_and_Hagenow_boundary,
            residual=full_residual,jacobian=full_jacobian,
            profile_row_count=nrows,flux_row_count=2n,gs_row_count=gs_rows,
            normalization_row_count=normalization_rows,dynamic_span_row_count=dynamic_profile_span ? 2 : 0,hagenow_row_count=hagenow_rows,
            hagenow_feedback=hagenow,
            missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,global_topology_closed=false,
            fixed_PF_currents=true,zero_anchor_is_physics_acceptance=false,
            current_operator_model_id=gs_ready ? gs_operator.model_id : :typed_absent)
        native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
            merge(evaluated,(native_field_model_id=native_field_model_id,
                native_field_initial_state=toroidal_coordinate===:native_F_defect_T_m_v1 ?
                :explicitly_reencoded_D_state_from_accepted_FreeGS_fields : :unchanged_accepted_FreeGS_field_samples,
                native_field_initial_state_adjustment=toroidal_coordinate===:native_F_defect_T_m_v1 ?
                :reported_finite_D_encoding_change : :none,
                native_field_source_fd_equivalence=:not_claimed,
                native_field_plasma_basis=:native_total_psi_minus_exact_pf_grid_psi,
                native_field_initial_plasma_identity=:derived_not_source_export,
                native_field_initial_plasma_source_equality=:not_assumed)) : evaluated
    end
    oracle=function(state)
        checked_state(state)
        if oracle_flux_jacobian[]===nothing
            Or=_ccp_native_spline_derivative_oracle(Raxis)
            Oz=_ccp_native_spline_derivative_oracle(Zaxis)
            oracle_flux_jacobian[]=_ccp_native_flux_jacobian(Raxis,Zaxis,Or,Oz,ndof)
        end
        x=checked_state(state);hagenow=hagenow_block(x)
        normalization_oracle=normalization_block(x;independent=true).jacobian
        span_oracle=_ccp_full_native_dynamic_span_equations(state_domain,x).jacobian
        dynamic_profile_span ?
            vcat(profile_oracle(state),oracle_flux_jacobian[],gs_block(x;independent=true).jacobian,
                normalization_oracle[1:1,:],span_oracle,normalization_oracle[2:2,:],hagenow_oracle_jacobian(x)) :
            vcat(profile_oracle(state),oracle_flux_jacobian[],gs_block(x;independent=true).jacobian,
                normalization_oracle,hagenow_oracle_jacobian(x))
    end
    boundary_trace_data=(state_domain=state_domain,anchor=anchor,Dr=Dr,Dz=Dz,
        Raxis=Raxis,R=R,Z=Z,n=n,nr=nr,nz=nz,ndof=ndof,law=law,faces=faces)
    boundary_trace=let trace_data=boundary_trace_data
        state->_ccp_full_native_boundary_trace(trace_data,state)
    end
    exterior_green_data=declaration.exterior_field_model===nothing ? nothing :
        _ccp_prepare_g2_exterior_green(context,d,state_domain,Raxis,Zaxis,R,mask,boundary_ids,
            exterior_ids,exterior_TF_Bphi,declaration.exterior_field_model)
    g2_outer_face_trace = if binding.declaration.outer_face_map===nothing
        state -> (status=:typed_absent,reason=:candidate_has_no_explicit_g2_outer_face_map,
            missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES)
    else
        map=binding.declaration.outer_face_map
        domain=binding.declaration.domain
        _validate_freegs_outer_face_map(map,domain)
        g2_trace_data=(boundary=boundary_trace_data,map=map,identity=identity,screen_only=screen_only,
            exterior=exterior_green_data)
        let trace_data=g2_trace_data
            state->_ccp_full_native_g2_outer_face_trace(trace_data,state)
        end
    end
    mask_cuts=Tuple((k,other) for k in 1:n for other in (k+nz,k+1)
        if other<=n && (other==k+nz || mod(k,nz)!=0) && mask[k]!=mask[other])
    source_reference_status=hagenow_source_reference===nothing ? :typed_absent :
        hagenow_source_reference.full_jacobian_status
    current_identity=(candidate_hash=identity.candidate_hash,context_hash=identity.context_hash,
        upstream_output_hash=identity.upstream_output_hash,trace_hash=t.trace_hash)
    loop_source=(native_ids=copy(core_ids),R_m=R[core_ids],Z_m=Z[core_ids],
        Jphi_A_per_m2=[support.Jphi_A_per_m2[cld(k,nz)][mod1(k,nz)] for k in core_ids],
        area_weight_m2=[support.area_weight_m2[cld(k,nz)][mod1(k,nz)] for k in core_ids],
        ring_current_A=[support.ring_current_A[cld(k,nz)][mod1(k,nz)] for k in core_ids],
        current_integral_trapezoid_A=support.current_integral_trapezoid_A,
        solver_plasma_current_A=support.solver_plasma_current_A)
    normalization_grid=(nr=nr,nz=nz,dr=Raxis[2]-Raxis[1],dz=Zaxis[2]-Zaxis[1])
    current_conservation_callbacks=payload->_ccp_full_native_current_callbacks(
        normalization_numeric_data,current_identity,loop_source,normalization_weights,
        normalization_grid,payload,nrows+2n+gs_rows+normalization_rows+(dynamic_profile_span ? 2 : 0),hagenow_rows,
        lcfs_current_numeric_data,lcfs_F_B_numeric_data,
        declaration.current_topology,declaration.return_current_path)
    regional_numeric_data=gs_ready && vary_profile_coefficients ?
        (profile=profile_numeric_data,flux=flux_numeric_data,gs=gs_numeric_data,
         gs_csc=(m=size(gs_operator.operator,1),n=size(gs_operator.operator,2),
            colptr=gs_operator.operator.colptr,rowval=gs_operator.operator.rowval,nzval=gs_operator.operator.nzval),
         normalization=normalization_numeric_data,normalization_weights=normalization_weights) : nothing
    regional_callbacks=(partition;region_id="freegs_g2_full_native")->_ccp_full_native_regional_callbacks(
        regional_numeric_data,identity.candidate_hash,identity.upstream_output_hash,partition;region_id=region_id)
    outer_callbacks=(;region_id="freegs_g2_full_native",lcfs_full64_inventory_provider=nothing)->begin
        g2_trace_data=binding.declaration.outer_face_map===nothing ? nothing :
            (boundary=boundary_trace_data,map=binding.declaration.outer_face_map,
             identity=identity,screen_only=screen_only,exterior=exterior_green_data)
        prepared=_ccp_full_native_outer_callbacks(hagenow_numeric_data,identity.candidate_hash,
            identity.upstream_output_hash,hagenow_full_source_validation,source_reference_status,
            nrows+2n+gs_rows+normalization_rows+(dynamic_profile_span ? 2 : 0)+1;
            region_id=region_id,g2_trace_data=g2_trace_data)
        prepared.status===:prepared_outer_evaluator || return prepared
        if lcfs_full64_inventory_provider===nothing
            return binding.declaration.outer_face_map===nothing ? prepared :
                merge(prepared,(g2_outer_face_map=binding.declaration.outer_face_map,
                    g2_outer_face_trace=g2_outer_face_trace,
                    g2_outer_face_state_dof_gather=:materialized_from_full_native_state))
        end
        provider_binding=_ccp_full_native_named_inventory_provider_binding(lcfs_full64_inventory_provider)
        mapped=binding.declaration.outer_face_map===nothing ? prepared :
            merge(prepared,(g2_outer_face_map=binding.declaration.outer_face_map,
                g2_outer_face_trace=g2_outer_face_trace,
                g2_outer_face_state_dof_gather=:materialized_from_full_native_state))
        provider_binding.status===:resolved_named_module_singleton_function ||
            return merge(mapped,(status=:typed_absent,reason=provider_binding.reason,
                lcfs_full64_provider_binding=provider_binding,global_rows_added=0,global_topology_closed=false,closure_evidence_created=false))
        # Match the existing frozen full-native field characteristic at the
        # candidate initial state. Do not rescale from this trial's field.
        bn_scale=abs(law.fvac_T_m/law.Raxis_m)
        for node in 1:n
            bn_scale=max(bn_scale,abs(anchor[4node-3]),abs(anchor[4node-2]),abs(anchor[4node-1]))
        end
        k_scale=bn_scale/law.mu0_N_per_A2
        flux_scale=abs(law.psi_boundary_wb_per_rad-law.psi_axis_wb_per_rad)
        all(isfinite,(bn_scale,k_scale,flux_scale)) && bn_scale>0 && k_scale>0 && flux_scale>0 ||
            throw(ArgumentError("authored LCFS outer row scales are invalid"))
        row_ids=Tuple("freegs_g2_lcfs_interface:ray_$(a):$(row)" for a in 1:64
            for row in (:Bn,:Kphi,:Kpoloidal))
        all_ids=(mapped.constraint_ids...,row_ids...)
        row_units=(ntuple(_->"Wb/rad",length(mapped.constraint_ids))...,
            Tuple(u for _ in 1:64 for u in ("T","A/m","A/m"))...)
        row_scales=(ntuple(_->flux_scale,length(mapped.constraint_ids))...,
            Tuple(s for _ in 1:64 for s in (bn_scale,k_scale,k_scale))...)
        lcfs_outer_numeric_data=(current_numeric_data=lcfs_current_numeric_data,
            plasma_trace_numeric_data=lcfs_plasma_trace_numeric_data,pressure_trace_numeric_data=lcfs_pressure_trace_numeric_data,
            provider_binding=provider_binding,authored_sources=d.authored_sources,mu0=law.mu0_N_per_A2,bn_scale=bn_scale,k_scale=k_scale)
        row_builder=let numeric_data=lcfs_outer_numeric_data
            state->_ccp_full_native_lcfs_outer_provider_rows(numeric_data,state)
        end
        base_eval=mapped.outer_evaluator
        base_oracle=mapped.jacobian_oracle
        h_ids=Tuple(mapped.constraint_ids)
        outer_eval=let base=base_eval,build=row_builder,ids=all_ids,hids=h_ids,
                rid_expected=String(region_id)
            (rid,state,closures,context)->begin
                rid==rid_expected || throw(ArgumentError("LCFS outer evaluation region differs"))
                h=Base.invokelatest(base,rid,state,closures,context)
                rows=Base.invokelatest(build,state)
                rows.status===:prepared_validated_same_state_full64_LCFS_outer_interface ||
                    throw(ArgumentError("LCFS full64 inventory failed closed: $(rows.reason)"))
                h.constraint_ids==hids && length(h.residual)==length(hids) &&
                    size(h.jacobian,2)==size(rows.jacobian,2) ||
                    throw(ArgumentError("H512/LCFS192 outer evaluation dimensions differ"))
                merge(h,(constraint_ids=ids,residual=vcat(h.residual,rows.residual),
                    jacobian=sparse(vcat(sparse(h.jacobian),sparse(rows.jacobian))),
                    row_units=row_units,row_characteristics=row_scales,
                    lcfs_interface_row_count=192,lcfs_interface_row_ids=rows.row_ids,
                    lcfs_interface_row_units=rows.row_units,
                    lcfs_interface_row_characteristics=rows.row_characteristics,
                    lcfs_full64_inventory_status=rows.inventory_status,
                    lcfs_interface_provider_record=rows,
                    global_rows_added=192,global_topology_closed=false))
            end
        end
        outer_oracle=let base=base_oracle,build=row_builder,ids=all_ids,hids=h_ids,
                rid_expected=String(region_id)
            (operation,rid,state,closures,context)->begin
                operation===:outer && rid==rid_expected ||
                    throw(ArgumentError("LCFS full64 oracle operation or region differs"))
                h=Base.invokelatest(base,operation,rid,state,closures,context)
                rows=Base.invokelatest(build,state)
                rows.status===:prepared_validated_same_state_full64_LCFS_outer_interface ||
                    throw(ArgumentError("LCFS full64 oracle inventory failed closed: $(rows.reason)"))
                h.constraint_ids==hids && size(h.jacobian,2)==size(rows.jacobian,2) ||
                    throw(ArgumentError("H512/LCFS192 outer oracle dimensions differ"))
                merge(h,(constraint_ids=ids,
                    jacobian=sparse(vcat(sparse(h.jacobian),sparse(rows.jacobian))),
                    lcfs_interface_row_count=192,lcfs_interface_row_ids=rows.row_ids))
            end
        end
        outer_first=first(mapped.outer_row_indices)
        first_row=nrows+2n+gs_rows+normalization_rows+(dynamic_profile_span ? 2 : 0)+2
        outer_first==first_row && length(mapped.outer_row_indices)==
            length(hagenow_numeric_data.boundary_native_ids) ||
            throw(ArgumentError("LCFS outer callback did not retain the original H512 row prefix"))
        merge(mapped,(outer_evaluator=outer_eval,global_hagenow_evaluator=outer_eval,
            jacobian_oracle=outer_oracle,constraint_ids=all_ids,
            outer_row_indices=outer_first:(last(mapped.outer_row_indices)+192),
            row_units=row_units,row_characteristics=row_scales,
            lcfs_interface_row_count=192,lcfs_interface_row_ids=row_ids,
            lcfs_interface_model_id=:actual_lcfs_full64_EG_Bn_Kphi_Kpoloidal_v1,
            outer_constraint_model_id=:freeBoundaryHagenow_H512_plus_LCFS64_192_v1,
            lcfs_interface_row_units=Tuple(u for _ in 1:64 for u in ("T","A/m","A/m")),
            lcfs_interface_row_characteristics=Tuple(s for _ in 1:64 for s in (bn_scale,k_scale,k_scale)),
            lcfs_full64_provider_contract=:actual_lcfs_full64_inventory_provider_v1,
            lcfs_full64_provider_status=:required_per_evaluation,
            lcfs_full64_provider_binding=provider_binding,
            global_rows_added=192,global_topology_closed=false,closure_evidence_created=false))
    end
    global_solver_jacobian_oracle=(regional,outer,current)->begin
        regional.status===:prepared_regional_evaluator &&
            outer.status===:prepared_outer_evaluator &&
            current.status===:prepared_conservation_evaluator &&
            regional.candidate_hash==outer.candidate_hash==current.candidate_hash==identity.candidate_hash &&
            regional.upstream_output_hash==outer.upstream_output_hash==current.upstream_output_hash==identity.upstream_output_hash &&
            regional.region_id==outer.region_id=="freegs_g2_full_native" &&
            outer.hagenow_full_jacobian_source_validation===:passed &&
            outer.source_reference_full_jacobian_status===:passed ||
            throw(ArgumentError("global diagnostic oracle providers are not the same validated full-native candidate"))
        normalization_oracle_weights=begin
            wr=_ccp_native_romberg_weights_oracle(nr)
            wz=_ccp_native_romberg_weights_oracle(nz)
            dr=Raxis[2]-Raxis[1];dz=Zaxis[2]-Zaxis[1]
            [wr[i]*wz[j]*dr*dz for i in 1:nr for j in 1:nz]
        end
        hagenow_rows=length(hagenow_numeric_data.boundary_native_ids)
        outer_lcfs_numeric=hasproperty(outer,:lcfs_full64_provider_binding) ?
            (current_numeric_data=current.lcfs_current_numeric_data,
             plasma_trace_numeric_data=merge(current.lcfs_current_numeric_data,(lcfs_F_B_numeric_data=current.lcfs_F_B_numeric_data,)),
             pressure_trace_numeric_data=merge(current.lcfs_current_numeric_data,
                (pressure_geometry_map=pressure_geometry_map,gs_rows=gs_rows,model_id=component_geometry_model_id,
                 gs_ready=current.lcfs_current_numeric_data.lcfs_dynamic_geometry_data.gs_ready)),
             provider_binding=outer.lcfs_full64_provider_binding,authored_sources=d.authored_sources,
             mu0=law.mu0_N_per_A2,bn_scale=outer.lcfs_interface_row_characteristics[1],
             k_scale=outer.lcfs_interface_row_characteristics[2]) : nothing
        oracle_data=(state_domain=state_domain,candidate_hash=identity.candidate_hash,
            region_id=regional.region_id,regional_numeric=regional_numeric_data,
            regional_equation_ids=Tuple(regional.equation_ids),hagenow_numeric=hagenow_numeric_data,
            hagenow_constraint_ids=Tuple(outer.constraint_ids[1:hagenow_rows]),
            outer_constraint_ids=Tuple(outer.constraint_ids),outer_lcfs_numeric=outer_lcfs_numeric,
            outer_jacobian_oracle=nothing,normalization_numeric=normalization_numeric_data,
            normalization_oracle_weights=normalization_oracle_weights,
            lcfs_current_numeric_data=current.lcfs_current_numeric_data,
            lcfs_F_B_numeric_data=current.lcfs_F_B_numeric_data,
            current_topology=current.current_topology,
            return_current_path=current.return_current_path,
            conservation_ids=Tuple(current.conservation_ids))
        let data=oracle_data
            (operation,region_id,state,closures,context)->
                _ccp_full_native_global_solver_oracle(data,operation,region_id,state,closures,context)
        end
    end
    component=merge(identity,(status=:prepared_full_native_profile_component,evaluate=evaluate,
        authored_sources=d.authored_sources,outer_callbacks=outer_callbacks,current_conservation_callbacks=current_conservation_callbacks,
        regional_callbacks=regional_callbacks,global_solver_jacobian_oracle=global_solver_jacobian_oracle,
        current_outer_partition=_ccp_full_native_current_outer_partition,
        core_current_trace=core_current_trace,regional_mhd_dof_map=regional_mhd_dof_map,
        lcfs_profile_current_trace=lcfs_profile_current_trace,
        lcfs_state_F_curl_trace=let trace_data=lcfs_F_B_numeric_data
            (state;with_jacobian=true,with_cut_jacobian=true,with_Bphi_field_jacobian=false)->
                _ccp_full_native_dynamic_lcfs_state_F_curl_trace(trace_data,state;
                    with_jacobian=with_jacobian,with_cut_jacobian=with_cut_jacobian,
                    with_Bphi_field_jacobian=with_Bphi_field_jacobian)
        end,
        lcfs_signed_fan_state_inputs=let domain=lcfs_current_numeric_data.state_domain, id=lcfs_current_numeric_data.trace_identity
            (record;kernel_calls_ref,max_kernel_calls=40_000_000,pf_ring_evaluations_ref=Ref(0))->_ccp_q1_lcfs_signed_fan_state_inputs(
                domain,record,id;kernel_calls_ref=kernel_calls_ref,max_kernel_calls=max_kernel_calls,
                pf_ring_evaluations_ref=pf_ring_evaluations_ref)
        end,
        lcfs_exterior_field_primal=function(state;kwargs...)
            _ccp_full_native_lcfs_exterior_field_primal(
                lcfs_current_numeric_data,state,d.authored_sources;kwargs...)
        end,
        lcfs_outer_interface_diagnostic_bridge=let authored=d.authored_sources,mu0=law.mu0_N_per_A2
            (trace,completed_exterior,pressure_trace;kwargs...)->
                _ccp_full_native_lcfs_outer_interface_diagnostic_bridge(
                    trace,completed_exterior,pressure_trace,authored,mu0;kwargs...)
        end,
        lcfs_dynamic_geometry_trace=function(state;model_id=component_geometry_model_id,
                defer_toroidal_profile_admission=false)
            model_id===component_geometry_model_id ||
                throw(ArgumentError("dynamic geometry probe cannot override the component field model"))
            _ccp_full_native_dynamic_geometry(lcfs_dynamic_geometry_data,state;
                model_id=component_geometry_model_id,
                defer_toroidal_profile_admission=defer_toroidal_profile_admission)
        end,
        lcfs_dynamic_geometry_data=lcfs_dynamic_geometry_data,
        lcfs_flux_trace=state->lcfs_flux_value(state),
        lcfs_flux_trace_oracle=state->lcfs_flux_value(state;independent=true),
        jacobian_oracle=oracle,boundary_trace=boundary_trace,
        g2_outer_face_map=binding.declaration.outer_face_map,
        g2_outer_face_trace=g2_outer_face_trace,initial_state=initial,
        initial_state_record=initial_coordinate_record,state_coordinate_id=toroidal_coordinate,
        toroidal_coordinate=toroidal_coordinate,
        admit_state_record=record->_ccp_full_native_admit_toroidal_state_record(state_domain,record),
        physical_state_observation=state->_ccp_full_native_physical_state_observation(state_domain,checked_state(state)),
        toroidal_coordinate_units=toroidal_coordinate===:native_F_defect_T_m_v1 ? "T m" : "T",
        toroidal_coordinate_metric_R_m=copy(R),
        toroidal_coordinate_metric_rule=:D_characteristic_equals_R_times_original_Bphi_characteristic,
        D_coordinate_unqualified_consumers=toroidal_coordinate===:native_F_defect_T_m_v1 ?
            (:legacy_direct_Fnode_LCFS_curl,:integer_only_regional_MHD_gather) : (),
        coordinates_RZ_m=collect(zip(R,Z)),core_mask=copy(mask),raw_constitutive_status=raw_status,
        raw_constitutive_reason=raw_reason,exterior_native_ids=exterior_ids,
        executed_exterior_TF_Bphi_T=exterior_TF_Bphi,internal_core_F_is_total=true,
        boundary_native_ids=boundary_ids,profile_law=law,grid_shape=(nr,nz),
        state_order=toroidal_coordinate===:native_F_defect_T_m_v1 ?
            :all_nodes_Br_D_T_m_Bz_psi_then_core_pressures_then_LBeta0_Lone_minus_Beta0_then_dynamic_psi_axis_psi_boundary :
            dynamic_profile_span ? :all_nodes_Br_Bphi_Bz_psi_then_core_pressures_then_LBeta0_Lone_minus_Beta0_then_dynamic_psi_axis_psi_boundary :
            vary_profile_coefficients ? :all_nodes_Br_Bphi_Bz_psi_then_core_pressures_then_LBeta0_Lone_minus_Beta0 :
            :all_nodes_Br_Bphi_Bz_psi_then_core_pressures,node_order=:R_then_Z,
        pressure_dofs=copy(pressure_dofs),pressure_rows=copy(pressure_rows),
        mask_cut_native_pairs=mask_cuts,frozen_mask_interface_continuity=:unverified,
        exterior_pressure_status=:typed_absent,
        pressure_domain_declaration_status=pressure_domain===nothing ? :typed_absent : :authored_law_only,
        pressure_domain_geometry_map_status=pressure_geometry_map.status,
        pressure_domain_geometry_map=pressure_geometry_map,
        pressure_domain_consumer_status=pressure_domain===nothing ? :typed_absent :
            (pressure_geometry_map.status===:present && pressure_geometry_map.pressure_dof_support_status===:present ?
                :derived_view_ready : :typed_absent),
        pressure_domain_view=pressure_domain_view,
        row_meanings=dynamic_profile_span ?
            (:all_native_R_Bphi_minus_F,:core_pressure_minus_profile,
                native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
                    :all_native_Br_Bz_absolute_plasma_spline_exact_PF_field : :all_native_Br_Bz_spline_response,
                :available_absolute_GS4_interior,:profile_axis_pressure_normalization,:dynamic_profile_axis_flux_definition,:dynamic_profile_boundary_flux_definition,:profile_Romberg_toroidal_current_normalization,:absolute_freeBoundaryHagenow_boundary_trace) :
            vary_profile_coefficients ?
                (:all_native_R_Bphi_minus_F,:core_pressure_minus_profile,
                    native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
                        :all_native_Br_Bz_absolute_plasma_spline_exact_PF_field : :all_native_Br_Bz_spline_response,
                    :available_absolute_GS4_interior,:profile_axis_pressure_normalization,:profile_Romberg_toroidal_current_normalization,:absolute_freeBoundaryHagenow_boundary_trace) :
                (:all_native_R_Bphi_minus_F,:core_pressure_minus_profile,
                    native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
                        :all_native_Br_Bz_absolute_plasma_spline_exact_PF_field : :all_native_Br_Bz_spline_response,
                    :available_absolute_GS4_interior,:absolute_freeBoundaryHagenow_boundary_trace),
        row_units=dynamic_profile_span ? ("T m","Pa","T","T","Pa","Wb/rad","Wb/rad","A","Wb/rad") :
            vary_profile_coefficients ? ("T m","Pa","T","T","Pa","A","Wb/rad") : ("T m","Pa","T","T","Wb/rad"),
        exterior_branch=:derived_FreeGS_native_masked_fpol_only,
        raw_exterior_constitutive_reclassified=false,fixed_accepted_mask=true,
        profile_row_count=nrows,flux_response_row_count=2n,flux_response_node_count=n,
        vary_profile_coefficients=vary_profile_coefficients,
        profile_coefficient_columns=vary_profile_coefficients ? coefficient_columns : (),
        dynamic_profile_span=dynamic_profile_span,profile_span_columns=span_columns,
        dynamic_profile_span_lcfs_unbound=dynamic_profile_span ?
            (:offgrid_LCFS_profile_current_source_records,:LCFS_pressure_trace,:LCFS_Jn_trace,:local_MHD_stencil_profile_law) : (),
        normalization_row_count=normalization_rows,
        normalization_row_range=dynamic_profile_span ?
            ((nrows+2n+gs_rows+1),(nrows+2n+gs_rows+4)) :
            ((nrows+2n+gs_rows+1):(nrows+2n+gs_rows+normalization_rows)),
        normalization_is_return_current_closure=false,
        normalization_equation_ids=vary_profile_coefficients ?
            ("profile_axis_pressure_normalization","profile_Romberg_toroidal_current_normalization") : (),
        normalization_evaluate=state->normalization_block(checked_state(state)),
        flux_response_scope=native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
            :absolute_plasma_spline_plus_exact_PF_potential_jet : :fixed_accepted_PF_affine_plasma_spline_response,
        fixed_PF_currents=true,fixed_PF_coil_ids=d.coil_ids,
        fixed_PF_currents_A_per_turn=d.coil_currents_A_per_turn,
        zero_anchor_is_physics_acceptance=false,
        gs_status=gs_input.status,gs_reason=gs_input.reason,gs_row_count=gs_rows,
        current_operator_model_id=gs_ready ? gs_operator.model_id : :typed_absent,
        gs_native_ids=gs_ready ? copy(gs_operator.native_ids) : Int[],
        gs_profile_scope=dynamic_profile_span ? :dynamic_axis_boundary_flux_with_frozen_source_mask_and_variable_profile_coefficients :
            vary_profile_coefficients ? :fixed_accepted_mask_axis_boundary_with_variable_profile_normalization : :fixed_accepted_mask_axis_boundary_and_profile_coefficients,
        gs_residual_baseline_subtracted=false,
        gs_boundary_feedback_executed=gs_ready,
        gs_final_profile_reference=gs_ready ? copy(gs_input.final_reference) : Float64[],
        gs_retained_current_reference=gs_ready ? copy(gs_input.retained_reference) : Float64[],
        gs_source_comparison_roundoff_bound=gs_comparison_bound,
        hagenow_status=gs_ready ? :present : :typed_absent,
        hagenow_reason=gs_ready ? :same_run_plasma_flux_and_profile_coefficients : gs_input.reason,
        hagenow_boundary_row_count=hagenow_rows,
        dynamic_span_row_range=dynamic_profile_span ?
            ((nrows+2n+gs_rows+2):(nrows+2n+gs_rows+3)) : (1:0),
        dynamic_span_equation_ids=dynamic_profile_span ?
            ("dynamic_profile_axis_flux_definition","dynamic_profile_boundary_flux_definition") : (),
        hagenow_boundary_row_range=(nrows+2n+gs_rows+normalization_rows+(dynamic_profile_span ? 2 : 0)+1):
            (nrows+2n+gs_rows+normalization_rows+(dynamic_profile_span ? 2 : 0)+hagenow_rows),
        hagenow_boundary_native_ids=gs_ready ? copy(hagenow_map.boundary_native_ids) : Int[],
        hagenow_core_native_ids=gs_ready ? copy(hagenow_map.core_native_ids) : Int[],
        hagenow_face_native_ids=gs_ready ? hagenow_map.face_native_ids : (),
        hagenow_face_normals_RZ=gs_ready ? hagenow_map.face_normals_RZ : (),
        hagenow_response_per_Jphi=hagenow_public_response,
        hagenow_source_reference=hagenow_source_reference,
        hagenow_source_operator_model_id=gs_ready ? gs_source_operator.model_id : :typed_absent,
        hagenow_source_comparison_error=hagenow_source_comparison_error,
        hagenow_source_comparison_bound=hagenow_source_comparison_bound,
        hagenow_source_directional_validation=gs_ready ? :base_plus_full_core_psi_u_v_dJ_directions : :typed_absent,
        hagenow_full_jacobian_source_validation=hagenow_full_source_validation,
        hagenow_full_source_map_error=hagenow_full_source_map_error,
        hagenow_full_source_map_bound=hagenow_full_source_map_bound,
        hagenow_initial_source_jacobian_error=hagenow_initial_source_jacobian_error,
        hagenow_initial_source_jacobian_bound=hagenow_initial_source_jacobian_bound,
        hagenow_adjoint_solve_max_backward_error=gs_ready ? hagenow_map.adjoint_solve_max_backward_error : nothing,
        hagenow_profile_scope=hagenow_profile_scope,
        hagenow_absolute_boundary_anchor_subtracted=false,
        hagenow_greens_source_arguments=:face_RZ,
        hagenow_greens_observation_arguments=:shifted_boundary_RZ,
        hagenow_outward_observation_epsilon_m=1e-2,
        hagenow_callSolver_direct_lu=true,hagenow_iterative_tolerance=:not_applicable,
        hagenow_boundary_feedback_executed=gs_ready,
        source_scope=:declared_ConstrainPaxisIp_alpha1_2_and_accepted_final_psi,
        pressure_current_profile_rows_executed=false,exterior_force_balance_executed=false,
        computational_outer_K=:typed_absent,full_current_conservation=:typed_absent,
        global_regional_dof_map=:typed_absent,PF_filament_sources=d.pf_loop_support))
    native_field_model_id===:plasma_spline_plus_exact_pf_potential_jet_v1 ?
        merge(component,(native_field_model_id=native_field_model_id,
            native_field_source_fd_equivalence=:not_claimed,
            native_field_initial_state=toroidal_coordinate===:native_F_defect_T_m_v1 ?
                :explicitly_reencoded_D_state_from_accepted_FreeGS_fields : :unchanged_accepted_FreeGS_field_samples,
            native_field_initial_state_adjustment=toroidal_coordinate===:native_F_defect_T_m_v1 ?
                :reported_finite_D_encoding_change : :none,
            native_field_initial_flux_residual_max_abs_T=maximum(abs,_ccp_full_native_flux_values(flux_numeric_data,initial)),
            native_field_plasma_basis=:native_total_psi_minus_exact_pf_grid_psi,
            native_field_initial_plasma_identity=:derived_not_source_export,
            native_field_plasma_nodes_definition=:xpsi_minus_cached_exact_pf_native_psi,
            native_field_continuous_psi_definition=:spline_of_derived_plasma_nodes_plus_exact_pf_offgrid,
            native_field_initial_plasma_identity_difference_scope=:measured_not_source_equivalent,
            native_field_initial_plasma_source_equality=:not_assumed,
            native_field_initial_plasma_source_max_abs_difference_Wb_per_rad=
                maximum(abs,(Float64[initial[4k] for k in 1:n]-native_pf_field_grid.psi_Wb_per_rad)-gs_input.plasma_psi),
            native_exact_pf_grid_field_model=native_pf_field_grid.model,
            native_exact_pf_grid_source_fd_anchor_use=:provenance_only)) : component
end

"""Independent signed-current poloidal field at the actual fixed LCFS points.

Each supported native RZ node is a circular filament with I=Jphi*area_weight;
each PF loop carries current-per-turn times turns. The dense analytic Jacobian
uses those same physical units. This finite-cell thin-ring quadrature is not a
converged continuum exterior trace, and does not supply TF or sheet-current laws.
"""
function evaluate_freegs_axisymmetric_lcfs_current_field(t::FreeGSAxisymmetricLCFSTraceV4;
        Jphi_A_per_m2=nothing,coil_currents_A_per_turn=nothing,
        observation_points_rz_m=nothing,TF_NI_A_turn=nothing,
        state::Symbol=:accepted_psi_profile)
    _ccp_validate_lcfs_trace(t); d=t.data; support=d.current_support
    state in (:accepted_psi_profile, :last_linear_solve_rhs) ||
        throw(ArgumentError("unsupported FreeGS current-field state"))
    identity=(candidate_hash=d.candidate_hash,context_hash=d.context_hash,
        upstream_output_hash=d.upstream_output_hash,trace_hash=t.trace_hash,
        missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,
        physical_validation=false,engineering_validation=false,coupled_solve_attempted=false,
        claim_ceiling=screen_only,p5_ready=false,terminal_authority=false)
    if state === :accepted_psi_profile
        support.status===:present || return merge(identity,
            (status=:typed_absent,reason=support.reason))
        source_R, source_Z = support.R_m, support.Z_m
        source_area = support.area_weight_m2
        source_dR, source_dZ = support.dR_m, support.dZ_m
        indices=Tuple((i,j) for i in eachindex(source_R) for j in eachindex(source_Z)
            if support.core_mask[i][j]==1.0)
        isempty(indices) && throw(ArgumentError("native plasma current support is empty"))
        initial_J=Tuple(support.Jphi_A_per_m2[i][j] for (i,j) in indices)
    else
        diagnostic=d.solver_jtor_diagnostic
        diagnostic.status===:present || return merge(identity,
            (status=:typed_absent,reason=diagnostic.reason,
             current_state=:last_linear_solve_rhs))
        Jphi_A_per_m2 === nothing ||
            throw(ArgumentError("last-solve RHS current cannot be replaced by caller densities"))
        source_R, source_Z = diagnostic.R_m, diagnostic.Z_m
        source_area = diagnostic.area_weight_m2
        source_dR, source_dZ = diagnostic.dR_m, diagnostic.dZ_m
        indices=Tuple((i,j) for i in eachindex(source_R) for j in eachindex(source_Z)
            if diagnostic.solver_eq_Jtor_A_per_m2[i][j] != 0.0)
        initial_J=Tuple(diagnostic.solver_eq_Jtor_A_per_m2[i][j] for (i,j) in indices)
    end
    densities=Jphi_A_per_m2===nothing ? initial_J : Jphi_A_per_m2
    currents=coil_currents_A_per_turn===nothing ? d.coil_currents_A_per_turn : coil_currents_A_per_turn
    for (values,n) in ((densities,length(indices)),(currents,length(d.coil_ids)))
        (values isa Tuple || values isa AbstractVector) && length(values)==n &&
            all(v -> v isa Real && !(v isa Bool) && isfinite(v),values) ||
            throw(ArgumentError("native current-field state shape or values are invalid"))
    end
    J=Float64.(collect(densities)); Icoil=Float64.(collect(currents))
    all(isfinite,J) && all(isfinite,Icoil) || throw(ArgumentError("current state overflows Float64"))
    coordinates = if observation_points_rz_m === nothing
        d.coordinates_m
    else
        observation_points_rz_m isa Tuple || observation_points_rz_m isa AbstractVector ||
            throw(ArgumentError("fixed observation points must be a finite RZ collection"))
        Tuple(begin
            (point isa Tuple || point isa AbstractVector) && length(point)==2 ||
                throw(ArgumentError("each fixed observation point must contain (R,Z)"))
            all(value -> value isa Real && !(value isa Bool),point) ||
                throw(ArgumentError("fixed observation coordinates must be real numbers"))
            R,Z=Float64(point[1]),Float64(point[2])
            all(isfinite,(R,Z)) && R>0 ||
                throw(ArgumentError("fixed observation coordinates must be finite with R>0"))
            source_R[1] <= R <= source_R[end] &&
                source_Z[1] <= Z <= source_Z[end] ||
                throw(ArgumentError("fixed observation point lies outside the source grid domain"))
            (R,Z)
        end for point in observation_points_rz_m)
    end
    isempty(coordinates) && throw(ArgumentError("observation points cannot be empty"))
    n=length(coordinates); nj=length(J); nc=length(Icoil)
    jacobian=zeros(2n,nj+nc); nearest=Inf
    for k in 1:n
        R,Z=coordinates[k]
        for (column,(i,j)) in enumerate(indices)
            a,z0=source_R[i],source_Z[j]
            unit=_ccp_ring_unit_field_RZ(R,Z,a,z0,d.mu0_N_per_A2)
            jacobian[2k-1,column]=unit[1]*source_area[i][j]
            jacobian[2k,column]=unit[2]*source_area[i][j]
            nearest=min(nearest,hypot(R-a,Z-z0))
        end
        for (column,coil) in enumerate(d.pf_loop_support)
            unit=_ccp_ring_unit_field_RZ(R,Z,coil.R_m,coil.Z_m,d.mu0_N_per_A2)
            jacobian[2k-1,nj+column]=unit[1]*coil.turns
            jacobian[2k,nj+column]=unit[2]*coil.turns
        end
    end
    plasma=jacobian[:,1:nj]*J; coil=jacobian[:,nj+1:end]*Icoil; field=plasma+coil
    all(isfinite,field) || throw(ArgumentError("native current-field sum is nonfinite"))
    pairs(x)=Tuple((x[2k-1],x[2k]) for k in 1:n)
    TF_NI_A_turn!==nothing && d.authored_sources.status!==:evaluated_authored_G1_G3_sources &&
        throw(ArgumentError("TF current change requires an actual candidate-owned G3 source"))
    authored=d.authored_sources.status===:evaluated_authored_G1_G3_sources ?
        evaluate_freegs_authored_sources(d.authored_sources;sample_RZ=coordinates,
            NI_A_turn=TF_NI_A_turn) : d.authored_sources
    result=merge(identity,(status=:evaluated_native_signed_current_poloidal_field,
        coordinates_m=coordinates,
        coordinates_source=observation_points_rz_m===nothing ? :actual_lcfs_trace : :fixed_physical_RZ_points,
        plasma_source_indices=indices,
        Jphi_A_per_m2=Tuple(J),coil_currents_A_per_turn=Tuple(Icoil),coil_ids=d.coil_ids,
        poloidal_field_RZ_T=pairs(field),plasma_poloidal_field_RZ_T=pairs(plasma),
        coil_poloidal_field_RZ_T=pairs(coil),field_vector_T=field,jacobian=jacobian,
        row_order=:interleaved_Br_Bz,column_order=:supported_Jphi_then_PF_current_per_turn,
        column_units=(plasma="A m^-2",coil="A per turn"),
        field_method=:independent_circular_filament_Biot_Savart_AGM,
        plasma_quadrature=:native_RZ_tensor_trapezoid_thin_rings,
        native_spacing_m=(source_dR,source_dZ),nearest_plasma_ring_distance_m=nearest,
        cell_quadrature_error=:unestimated,continuum_exterior_trace_validated=false,
        poloidal_field_executed=true,coil_only_is_total_exterior=false,
        independent_toroidal_field_source=authored.status===:evaluated_authored_G1_G3_sources ? authored :
            (support.status===:present ? support.independent_toroidal_field_source :
                (status=:typed_absent,reason=:candidate_bound_TF_coil_current_and_geometry_unavailable)),
        declared_exterior_B_cylindrical_T=authored.status===:evaluated_authored_G1_G3_sources ?
            Tuple((field[2k-1],authored.TF_Bphi_T[k],field[2k]) for k in 1:n) : nothing,
        declared_sheet_current_A_per_m=authored.status===:evaluated_authored_G1_G3_sources ?
            authored.K_cylindrical_A_per_m : nothing,
        source_model_complete_is_not_global_closure=true,
        exterior_total_field=:typed_absent,independent_sheet_law=:typed_absent,
        global_regional_dof_map=:typed_absent,equilibrium_recomputed=false,
        current_state_scope=state===:last_linear_solve_rhs ?
            :exact_nonzero_retained_rhs_nodes_fixed_geometry :
            :fixed_native_core_support_geometry_and_lcfs))
    state===:last_linear_solve_rhs ? merge(result,
        (current_state=:last_linear_solve_rhs,
         current_state_provenance=:FreeGS_eq_Jtor_last_linear_solve_RZ_nodes,
         initial_Jphi_A_per_m2=initial_J)) : result
end

function _ccp_lcfs_provider_identity(t,region_id,expected_region_id,context,ids)
    _ccp_validate_lcfs_trace(t)
    region_id==expected_region_id && hasproperty(context,:candidate_hash) &&
        context.candidate_hash==t.data.candidate_hash ||
        throw(ArgumentError("LCFS callback candidate or region differs"))
    all(k -> hasproperty(context,k) && getproperty(context,k) isa AbstractString &&
        occursin(r"^[0-9a-f]{64}$",getproperty(context,k)),
        (:provider_semantic_hash,:provider_context_hash,:jacobian_oracle_hash)) ||
        throw(ArgumentError("LCFS callback requires the solver provider identity"))
    (candidate_hash=t.data.candidate_hash,provider_semantic_hash=context.provider_semantic_hash,
        provider_context_hash=context.provider_context_hash,region_id=region_id,constraint_ids=ids)
end

"""Existing InHouse outer evaluator/oracle ABI for intrinsic LCFS conditions only.

External-total-field and independent sheet-current laws remain required. The
caller must connect this trace state to its regional state through actual
interpolation/DOF maps; this function does not fabricate that connection.
"""
function freegs_axisymmetric_lcfs_boundary_callbacks(t::FreeGSAxisymmetricLCFSTraceV4;
        region_id="freegs_actual_lcfs_trace")
    _ccp_validate_lcfs_trace(t)
    region_id isa AbstractString && !isempty(strip(region_id)) ||
        throw(ArgumentError("LCFS callback needs a region ID"))
    rid=String(region_id)
    authored_sheet=t.data.authored_sources.status===:evaluated_authored_G1_G3_sources
    sheet_law=authored_sheet ? :executed_G1_no_delta_sheet : :typed_absent
    sheet_current=authored_sheet ? t.data.authored_sources.K_cylindrical_A_per_m : nothing
    ids=Tuple("$(rid):point_$(i):$(field)" for i in eachindex(t.data.normals_RZ)
        for field in (:normal_B,:boundary_p,:boundary_F))
    outer_evaluator=function(region_id,state,closures,context)
        identity=_ccp_lcfs_provider_identity(t,region_id,rid,context,ids)
        value=evaluate_freegs_axisymmetric_lcfs_trace(t,state)
        merge(identity,(residual=value.residual,jacobian=value.jacobian))
    end
    jacobian_oracle=function(operation,region_id,state,closures,context)
        operation===:outer || throw(ArgumentError("LCFS callback only supplies the outer oracle"))
        identity=_ccp_lcfs_provider_identity(t,region_id,rid,context,ids)
        evaluate_freegs_axisymmetric_lcfs_trace(t,state)
        jacobian=zeros(length(ids),length(state)); step=1.0e-30
        for j in eachindex(state)
            z=ComplexF64.(collect(state)); z[j]+=im*step
            local_rows=_ccp_axisymmetric_lcfs_trace_oracle(z,t.data.normals_RZ,
                t.data.profile_boundary_pressure_Pa,t.data.mu0_N_per_A2).residual
            rows=ComplexF64[]
            for i in eachindex(t.data.normals_RZ)
                append!(rows,(local_rows[2i-1],local_rows[2i],
                    t.data.coordinates_m[i][1]*z[4i-1]-t.data.profile_law.fvac_T_m))
            end
            jacobian[:,j].=imag.(rows)./step
        end
        all(isfinite,jacobian) || throw(ArgumentError("LCFS oracle produced nonfinite values"))
        merge(identity,(jacobian=jacobian,jacobian_oracle_hash=context.jacobian_oracle_hash))
    end
    (outer_evaluator=outer_evaluator,jacobian_oracle=jacobian_oracle,
        candidate_hash=t.data.candidate_hash,region_id=rid,region_dofs=length(t.data.initial_state),
        constraint_ids=ids,pressure_indices=Tuple(1:4:length(t.data.initial_state)),
        external_total_field=:typed_absent,independent_sheet_current_law=sheet_law,
        declared_sheet_current_A_per_m=sheet_current,
        plasma_return_path=:typed_absent,regional_trace_state_map=:typed_absent,
        missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,
        full_model_constructed=false,coupled_solve_attempted=false,claim_ceiling=screen_only)
end

"""Native-cross pressure/current/flux topology rows at a supplied changing state.

State is node-major (p,Br,Bphi,Bz,psi) at (center,R-,R+,Z-,Z+). The law
coefficients come from the same final-psi FreeGS profile. Coordinates and law
coefficients stay fixed. These local derivative constraints need a connected
global flux/pressure state and actual boundary conditions before they close a
global topology. No integral pressure gauge or current return path is invented.
"""
function _ccp_axisymmetric_topology_stencil(state, coordinates_m, law)
    (state isa Tuple || state isa AbstractVector) && length(state) == 25 &&
        all(v -> v isa Real && !(v isa Bool) && isfinite(v), state) ||
        throw(ArgumentError("topology stencil needs twenty-five finite real values"))
    fields = (:L_A_per_m2,:Beta0,:alpha_m,:alpha_n,:Raxis_m,:fvac_T_m,
        :psi_axis_wb_per_rad,:psi_boundary_wb_per_rad,:mu0_N_per_A2)
    all(k -> hasproperty(law,k) && getproperty(law,k) isa Real &&
        !(getproperty(law,k) isa Bool) && isfinite(getproperty(law,k)),fields) ||
        throw(ArgumentError("final-psi profile law is incomplete or nonfinite"))
    vals = NamedTuple{fields}(Tuple(Float64(getproperty(law,k)) for k in fields))
    all(isfinite,values(vals)) && vals.alpha_m > 0 && vals.alpha_n > 0 &&
        vals.Raxis_m > 0 && vals.fvac_T_m > 0 && vals.mu0_N_per_A2 > 0 ||
        throw(ArgumentError("profile law has invalid positive parameters"))
    q = Float64.(collect(state))
    all(isfinite,q) && all(i -> q[i] >= 0.0,1:5:25) ||
        throw(ArgumentError("topology state must be finite with nonnegative pressure"))
    # Reuse only the existing coordinate/domain validation; its MHD values are
    # not used in the topology residual or analytic Jacobian below.
    mhd_state = [q[5(node-1)+field] for node in 1:5 for field in 1:4]
    checked = _ccp_axisymmetric_mhd_stencil(mhd_state,coordinates_m,vals.mu0_N_per_A2)
    pts = checked.coordinates_m; R = pts[1][1]; mu0 = vals.mu0_N_per_A2
    span = vals.psi_boundary_wb_per_rad-vals.psi_axis_wb_per_rad
    isfinite(span) && span != 0 || throw(ArgumentError("profile flux span is degenerate"))
    normalized = Tuple((q[5node]-vals.psi_axis_wb_per_rad)/span for node in 1:5)
    all(pn -> isfinite(pn) && 0 < pn < 1,normalized) ||
        throw(ArgumentError("topology derivative stencil requires strict core flux support"))
    pn = normalized[1]
    shape = (1-pn^vals.alpha_m)^vals.alpha_n
    shape_derivative = -vals.alpha_m*vals.alpha_n*pn^(vals.alpha_m-1)*
        (1-pn^vals.alpha_m)^(vals.alpha_n-1)/span
    pcoefficient = vals.L_A_per_m2*vals.Beta0/vals.Raxis_m
    fcoefficient = mu0*vals.L_A_per_m2*(1-vals.Beta0)*vals.Raxis_m
    pp = pcoefficient*shape; ff = fcoefficient*shape
    dpp = pcoefficient*shape_derivative; dff = fcoefficient*shape_derivative
    F = R*q[3]
    F > 0 && isfinite(F) || throw(ArgumentError("topology supports only positive F branch"))
    gp = zeros(2,25); gpsi = zeros(2,25); gF = zeros(2,25)
    curlphi = zeros(1,25); epsi = zeros(25); epsi[5]=1.0
    eF = zeros(25); eF[3]=R
    for (direction,minus,plus,h) in ((1,2,3,2*checked.dr_m),(2,4,5,2*checked.dz_m))
        for (node,sign) in ((minus,-1.0),(plus,1.0))
            offset = 5(node-1)
            gp[direction,offset+1]=sign/h
            gpsi[direction,offset+5]=sign/h
            gF[direction,offset+3]=sign*pts[node][1]/h
            # (curl B)_phi = dBr/dZ - dBz/dR.
            curlphi[1,offset+(direction==1 ? 4 : 2)] = (direction==1 ? -sign : sign)/h
        end
    end
    gradpsi = gpsi*q
    pressure_rows = gp*q-pp*gradpsi
    current_rows = gF*q-(ff/F)*gradpsi
    flux_jacobian = copy(gpsi); flux_jacobian[1,4]-=R; flux_jacobian[2,2]+=R
    current_density = only(curlphi*q)/mu0
    residual = [pressure_rows;current_rows;flux_jacobian*q;
        current_density-R*pp-ff/(mu0*R)]
    jacobian = [gp-pp*gpsi-gradpsi*(dpp*epsi)';
        gF-(ff/F)*gpsi-gradpsi*((dff/F)*epsi-(ff/F^2)*eF)';
        flux_jacobian;
        curlphi/mu0-(R*dpp+dff/(mu0*R))*epsi']
    all(isfinite,residual) && all(isfinite,jacobian) ||
        throw(ArgumentError("topology arithmetic produced nonfinite values"))
    (residual=residual,jacobian=jacobian,psi_normalized=normalized,
        pprime_Pa_per_flux=pp,ffprime_T2_m2_per_flux=ff,
        current_curl_phi_A_m2=current_density,
        row_meanings=(:pressure_R,:pressure_Z,:F_R,:F_Z,:flux_R,:flux_Z,:GS_current_phi),
        row_units=("Pa m^-1","Pa m^-1","T","T","T m","T m","A m^-2"),
        state_fields=(:pressure_Pa,:Br_T,:Bphi_T,:Bz_T,:psi_wb_per_rad),
        jacobian_scope=:sampled_core_state_at_fixed_profile_and_geometry,
        global_topology_closed=false,plasma_return_path_verified=false)
end

const _CCP_TOPOLOGY_TOKEN = Val(:freegs_topology_component_private)
struct FreeGSAxisymmetricTopologyComponentV4
    data::NamedTuple
    source_hash::String
    component_hash::String
    function FreeGSAxisymmetricTopologyComponentV4(::Val{:freegs_topology_component_private},data,source_hash,component_hash)
        new(data,source_hash,component_hash)
    end
end
semantic_view(t::FreeGSAxisymmetricTopologyComponentV4) =
    (data=t.data,source_hash=t.source_hash,component_hash=t.component_hash)

function _ccp_validate_topology_component(t::FreeGSAxisymmetricTopologyComponentV4)
    t.component_hash==string(canonical_hash((data=t.data,source_hash=t.source_hash))) ||
        throw(ArgumentError("topology prepared physical data changed"))
    t.component_hash
end

"Prepare actual core flux, p and B from the same output as the final profile law."
function freegs_axisymmetric_topology_component(context,artifacts,sample_indices,
        trace::FreeGSAxisymmetricLCFSTraceV4)
    _ccp_validate_lcfs_trace(trace)
    base=freegs_axisymmetric_mhd_component(context,artifacts,sample_indices)
    base.status===:sampled_axisymmetric_mhd_component || return base
    d=trace.data
    base.candidate_hash==d.candidate_hash && base.context_hash==d.context_hash &&
        base.upstream_output_hash==d.upstream_output_hash ||
        throw(ArgumentError("topology stencil and LCFS profile came from different outputs"))
    samples=Tuple(artifacts.field_samples_rz_m[i] for i in sample_indices)
    state=Tuple(v for s in samples for v in (s.constitutive.pressure_Pa,s.Br_T,
        s.constitutive.Btor_T,s.Bz_T,s.constitutive.psi_native_wb_per_rad))
    all(s -> s.constitutive.psi_axis_wb_per_rad==d.profile_law.psi_axis_wb_per_rad &&
        s.constitutive.psi_boundary_wb_per_rad==d.profile_law.psi_boundary_wb_per_rad &&
        s.constitutive.mu0_N_per_A2==d.profile_law.mu0_N_per_A2,samples) ||
        throw(ArgumentError("native constitutive support and LCFS profile law differ"))
    initial=_ccp_axisymmetric_topology_stencil(state,base.coordinates_m,d.profile_law)
    center=samples[1].constitutive
    for (computed,observed) in ((initial.pprime_Pa_per_flux,center.pprime_Pa_per_flux),
            (initial.ffprime_T2_m2_per_flux,center.ffprime_T2_m2_per_flux))
        isapprox(computed,observed;rtol=256eps(Float64),atol=256eps(Float64)) ||
            throw(ArgumentError("exported law does not reproduce actual native profile derivatives"))
    end
    data=(candidate_hash=base.candidate_hash,context_hash=base.context_hash,
        upstream_output_hash=base.upstream_output_hash,trace_hash=trace.trace_hash,
        coordinates_m=base.coordinates_m,sample_indices=Tuple(sample_indices),
        initial_state=state,profile_law=d.profile_law)
    source=""
    FreeGSAxisymmetricTopologyComponentV4(_CCP_TOPOLOGY_TOKEN,data,source,
        string(canonical_hash((data=data,source_hash=source))))
end

function evaluate_freegs_axisymmetric_topology_component(t::FreeGSAxisymmetricTopologyComponentV4,state)
    _ccp_validate_topology_component(t); d=t.data
    rows=_ccp_axisymmetric_topology_stencil(state,d.coordinates_m,d.profile_law)
    merge(rows,(status=:evaluated_actual_core_topology_component,
        candidate_hash=d.candidate_hash,context_hash=d.context_hash,
        upstream_output_hash=d.upstream_output_hash,component_hash=t.component_hash,
        pressure_topology_rows_executed=true,current_topology_rows_executed=true,
        missing_closures=_CCP_AXISYMMETRIC_MISSING_CLOSURES,
        pressure_gauge_closed=false,global_topology_closed=false,plasma_return_path_verified=false,
        coupled_solve_attempted=false,physical_validation=false,engineering_validation=false,
        claim_ceiling=screen_only,p5_ready=false,terminal_authority=false))
end

function _ccp_axisymmetric_topology_oracle(state, points, law)
    value(node,field)=state[5(node-1)+field]
    dr=points[3][1]-points[2][1]; dz=points[5][2]-points[4][2]
    dR(field)=(value(3,field)-value(2,field))/dr
    dZ(field)=(value(5,field)-value(4,field))/dz
    R=points[1][1]; mu=law.mu0_N_per_A2
    pn=(value(1,5)-law.psi_axis_wb_per_rad)/
        (law.psi_boundary_wb_per_rad-law.psi_axis_wb_per_rad)
    S=(1-pn^law.alpha_m)^law.alpha_n
    pp=law.L_A_per_m2*law.Beta0/law.Raxis_m*S
    ff=mu*law.L_A_per_m2*(1-law.Beta0)*law.Raxis_m*S
    F=R*value(1,3)
    [(dR(1)-pp*dR(5)),(dZ(1)-pp*dZ(5)),
        (points[3][1]*value(3,3)-points[2][1]*value(2,3))/dr-ff/F*dR(5),
        (points[5][1]*value(5,3)-points[4][1]*value(4,3))/dz-ff/F*dZ(5),
        dR(5)-R*value(1,4),dZ(5)+R*value(1,2),
        (dZ(2)-dR(4))/mu-R*pp-ff/(mu*R)]
end

# Default-off one-box directional Taylor certificate. It uses dual intervals
# (value, state-direction) at every Taylor coefficient; the 17th coefficient
# is enclosed over the full axis for the Peano remainder.
function _ccp_q1_lcfs_star_leaf_directional_gauss8_taylor_box(target,target_dot,
        parent,parent_dot,weights,bounds,bounds_dot,mu0,rbox,ubox;
        actual_triangle_points,basis_index=1,current=0.0,current_dot=0.0,
        _weighted_q1_coefficients=nothing,_weighted_q1_direction_coefficients=nothing,
        _q8_jacobian_probe=false,_fixed_stored_q8_moment_error=false,_stored_rule_tail_preflight=false,
        _quadrature_error_only=false,_ring_edge_moment_request=false,
        terms=16,precision_bits=256,interval_ops=Ref(0),max_interval_ops=8_000_000,
        exact_ops=Ref(0),max_exact_ops=2_000_000,
        _radial_depth=0,_true_gauss_rule=nothing,_shared_taylor_cache=nothing,
        _shared_geometry_cache=nothing,_shared_parent_star_bounds=nothing,
        _parent_child_jet_smoke=false,_parent_star_build_only=false,
        _parent_child_jet_containment_probe=false,
        _parent_star_scope_preflight=false,_range0_coarse_bound=false,chart_kind=:star)
    chart_kind in (:star,:nonstar) || return (status=:typed_absent,reason=:invalid_chart_kind,kernel_calls=0,interval_operations=interval_ops[])
    (_quadrature_error_only isa Bool && (!_quadrature_error_only ||
        (chart_kind===:nonstar && _radial_depth==1 && _weighted_q1_direction_coefficients!==nothing &&
         !_fixed_stored_q8_moment_error && !_stored_rule_tail_preflight))) ||
        return (status=:typed_absent,reason=:error_only_requires_weighted_nonrecursive_nonstar_peano,
            kernel_calls=0,interval_operations=interval_ops[])
    (_ring_edge_moment_request isa Bool && (!_ring_edge_moment_request ||
        (chart_kind===:nonstar && _radial_depth==0 && rbox[1]<=1<=rbox[2] &&
         ubox[1]==0 && ubox[2]==1 && _weighted_q1_coefficients===nothing &&
         _weighted_q1_direction_coefficients===nothing && !_q8_jacobian_probe &&
         !_fixed_stored_q8_moment_error && !_stored_rule_tail_preflight))) ||
        return (status=:typed_absent,reason=:ring_edge_moment_requires_full_nonstar_AB_chart,
            kernel_calls=0,interval_operations=interval_ops[])
    _q8_jacobian_probe isa Bool || return (status=:typed_absent,reason=:invalid_q8_jacobian_probe_mode,
        kernel_calls=0,interval_operations=interval_ops[])
    (!_q8_jacobian_probe || (chart_kind===:star && _radial_depth in (0,1) && _weighted_q1_coefficients!==nothing)) ||
        return (status=:typed_absent,reason=:q8_jacobian_probe_requires_weighted_star_parent_or_child,
            kernel_calls=0,interval_operations=interval_ops[])
    (_weighted_q1_coefficients===nothing ||
        (_weighted_q1_coefficients isa Tuple && length(_weighted_q1_coefficients)==4 &&
         all(x->typeof(x)===Float64 && isfinite(x),_weighted_q1_coefficients))) ||
        return (status=:typed_absent,reason=:invalid_weighted_q1_coefficients,kernel_calls=0,interval_operations=interval_ops[])
    (_weighted_q1_direction_coefficients===nothing ||
        (_weighted_q1_coefficients!==nothing && _weighted_q1_direction_coefficients isa Tuple &&
         length(_weighted_q1_direction_coefficients)==4 &&
         all(x->typeof(x)===Float64 && isfinite(x),_weighted_q1_direction_coefficients))) ||
        return (status=:typed_absent,reason=:invalid_weighted_q1_direction_coefficients,kernel_calls=0,interval_operations=interval_ops[])
    weighted_q1_direction_coefficients=_weighted_q1_direction_coefficients===nothing ? (0.0,0.0,0.0,0.0) :
        _weighted_q1_direction_coefficients
    _fixed_stored_q8_moment_error isa Bool || return (status=:typed_absent,
        reason=:invalid_stored_q8_moment_mode,kernel_calls=0,interval_operations=interval_ops[])
    (!_fixed_stored_q8_moment_error || (chart_kind===:nonstar && _weighted_q1_direction_coefficients!==nothing)) ||
        return (status=:typed_absent,reason=:stored_q8_moments_require_actual_weighted_nonstar_direction,
            kernel_calls=0,interval_operations=interval_ops[])
    moment_bound_order=_fixed_stored_q8_moment_error ? 17 : 16
    (_stored_rule_tail_preflight isa Bool && (!_stored_rule_tail_preflight ||
        (_fixed_stored_q8_moment_error && _radial_depth==1))) ||
