    taylor_cache isa AbstractDict || return (status=:typed_absent,reason=:invalid_shared_taylor_cache,kernel_calls=0,interval_operations=ops[])
    geometry_cache=_shared_geometry_cache===nothing ? Dict{Any,Any}() : _shared_geometry_cache
    geometry_cache isa AbstractDict || return (status=:typed_absent,reason=:invalid_shared_geometry_cache,kernel_calls=0,interval_operations=ops[])
    lane_count=try target_dot[1] isa Real ? 1 : length(target_dot[1]) catch; 0 end
