        x isa Tuple ? Tuple(freeze_geometry_key(y) for y in x) : x
    geometry_input_key=(:ccp_q1_lcfs_geometry_jet_v1,chart_kind,terms,precision_bits,17,_radial_depth,max_interval_ops,lane_count,
        freeze_geometry_key(target),freeze_geometry_key(target_dot),freeze_geometry_key(parent),
        freeze_geometry_key(parent_dot),freeze_geometry_key(weights),freeze_geometry_key(bounds),
        freeze_geometry_key(bounds_dot),freeze_geometry_key(actual_triangle_points),mu0,
