        x isa Tuple ? all(geometry_tuple_only,x) : x isa Symbol || x isa BigFloat || isbitstype(typeof(x))
    geometry_tuple_freeze(x::NamedTuple)=NamedTuple{keys(x)}(map(geometry_tuple_freeze,values(x)))
    geometry_tuple_freeze(x::Tuple)=map(geometry_tuple_freeze,x)
    geometry_tuple_freeze(x::AbstractArray)=Tuple(geometry_tuple_freeze(v) for v in x)
    geometry_tuple_freeze(x)=x isa Symbol || x isa BigFloat || isbitstype(typeof(x)) ? x :
        throw(ArgumentError("unsupported mutable pointwise geometry jet leaf $(typeof(x))"))
    phase_counts=Dict{Symbol,Int}();phase_origin=ops[];phase_stage=Ref(:q_lq_geometry);phase_start=Ref(phase_origin)
    phase_mark!(name)=begin
        phase_counts[phase_stage[]]=get(phase_counts,phase_stage[],0)+ops[]-phase_start[]
        phase_start[]=ops[];phase_stage[]=name;nothing
    end
    phase_total(name)=get(phase_counts,name,0)+(phase_stage[]===name ? ops[]-phase_start[] : 0)
    completed_child_phase_counts=Any[]
    point_counts=Dict{Symbol,Int}(:geometry_hits=>0,:geometry_misses=>0,
        :ke_hits=>0,:ke_misses=>0,:primal_evaluations=>0,:directional_evaluations=>0,
        :tail_target_met=>0,:tail_target_not_met_at_cap=>0)
    point_terms_histogram=Dict{Int,Int}()
    point_tail_max=Ref((K=BigFloat(0),E=BigFloat(0)))
    point_diagnostics()=(geometry_cache_hits=point_counts[:geometry_hits],
        geometry_cache_misses=point_counts[:geometry_misses],
        ke_cache_hits=point_counts[:ke_hits],ke_cache_misses=point_counts[:ke_misses],
        primal_DLMF_evaluations=point_counts[:primal_evaluations],
        directional_DLMF_evaluations=point_counts[:directional_evaluations],
        newly_evaluated_selected_terms_histogram=Tuple((terms=k,count=point_terms_histogram[k]) for k in sort!(collect(keys(point_terms_histogram)))),
        tail_target_met_count=point_counts[:tail_target_met],
        tail_target_not_met_at_original_cap_count=point_counts[:tail_target_not_met_at_cap],
        maximum_newly_evaluated_primal_tail=point_tail_max[],
        statistics_scope=:this_scalar_call_only_geometry_cache_hits_reuse_previously_included_tails,
        relative_tail_selection_target=2.0^-64,
        tail_policy=chart_kind===:nonstar ? :adaptive_terms_full_rigorous_tail_retained : :original_fixed_terms,
        qualification_scope=:selection_target_is_not_an_error_gate_all_tail_is_in_Q8)
