    function qualify_gauss8_rule(nodes)
        phase_mark!(:gauss_rule_proof)
        rule=_true_gauss_rule===nothing ? _ccp_q1_green_gauss_interval(8;
            seed_nodes=nodes,precision_bits=precision_bits,root_width=2.0^-128,
            max_interval_ops=max_interval_ops,interval_ops=ops) : _true_gauss_rule
        rule.status===:evaluated_true_Gauss_rule_interval && rule.root_count==8 &&
            length(rule.mapped_nodes_and_weights)==8 &&
            all(nw->nw.weight[1]>0 && nw.node[1]<=nw.node[2] && nw.weight[1]<=nw.weight[2],
                rule.mapped_nodes_and_weights) || throw(DomainError(rule,"Gauss8 rule not qualified"))
