    end
    function run()
        down(f)=setrounding(BigFloat,RoundDown) do;f();end
        up(f)=setrounding(BigFloat,RoundUp) do;f();end
        exact(x)=(BigFloat(x),BigFloat(x))
        lane_count in (1,4) || throw(ArgumentError("directional Taylor lane count must be one or four"))
        lane_interval(x)=x isa Real ? ntuple(_->exact(x),lane_count) :
            ((x isa Tuple || x isa AbstractVector) && length(x)==lane_count ?
                ntuple(i->exact(x[i]),lane_count) : throw(ArgumentError("directional input lane shape mismatch")))
        charge!(n=1)=begin
            n isa Integer && n>=0 && ops[]<=typemax(Int)-n && ops[]<=max_interval_ops-n ||
                throw(OverflowError("directional Taylor operation cap"))
