            nothing
        end
        exact_zero_interval(a)=iszero(a[1]) && iszero(a[2])
        finite_interval(a)=isfinite(a[1]) && isfinite(a[2])
        add(a,b)=begin
            exact_zero_interval(a) && finite_interval(b) && return b
            exact_zero_interval(b) && finite_interval(a) && return a
