        lane_add(a,b)=ntuple(i->add(a[i],b[i]),lane_count)
        lane_sub(a,b)=ntuple(i->sub(a[i],b[i]),lane_count)
        mul(a,b)=begin
            exact_zero_interval(a) && finite_interval(b) && return a
            exact_zero_interval(b) && finite_interval(a) && return b
            charge!(4);(minimum(down(()->x*y) for x in a for y in b),maximum(up(()->x*y) for x in a for y in b))
        end
