        divi(a,b)=mul(a,inv(b)); sqr(a)=a[1]<=0<=a[2] ? (BigFloat(0),up(()->max(a[1]^2,a[2]^2))) : (down(()->min(a[1]^2,a[2]^2)),up(()->max(a[1]^2,a[2]^2)))
        sqrt_i(a)=begin charge!();a[1]>0 || throw(DomainError(a,"dual Taylor sqrt nonpositive"));(down(()->sqrt(a[1])),up(()->sqrt(a[2]))) end
        log_i(a)=begin charge!();a[1]>0 || throw(DomainError(a,"dual Taylor log nonpositive"));(down(()->log(a[1])),up(()->log(a[2]))) end
