        dneg(a)=(neg(a[1]),ntuple(i->neg(a[2][i]),lane_count))
        dmul(a,b)=(mul(a[1],b[1]),ntuple(i->add(mul(a[2][i],b[1]),mul(a[1],b[2][i])),lane_count))
        dinv(a)=(inv(a[1]),ntuple(i->neg(divi(a[2][i],sqr(a[1]))),lane_count))
        ddiv(a,b)=dmul(a,dinv(b))
        dsqrt(a)=begin v=sqrt_i(a[1]);(v,ntuple(i->divi(a[2][i],mul(exact(2),v)),lane_count)) end
        dlog(a)=(log_i(a[1]),ntuple(i->divi(a[2][i],a[1]),lane_count))
        zdual=dc(exact(0)); one=dc(exact(1))
