        # Taylor constants have one nonzero coefficient only; all higher
        # coefficients are the exact zero dual interval.
        jc(a)=vcat([a],fill(zdual,17)); ja(a,b)=[dadd(a[k],b[k]) for k=1:18]; jn(a)=[dneg(a[k]) for k=1:18]
        js(a,b)=ja(a,jn(b))
        function jm(a,b)
            o=fill(zdual,18)
