        # qhat_box/logqhat_box/q_upper are externally certified whole-box ranges for qhat, log(qhat), and r^2*qhat on the
        # whole local box. Each jet coefficient is (value_interval, lanes).
        function star_ke_log_split_jet(qhat,logqhat,rj,qhat_box,logqhat_box,q_upper,qhat_dot_box,qdot_box,logqhat_dot_box;
                max_terms=256,tail_target=BigFloat(1)/BigFloat(2)^64,baseline_compare=false)
            op_origin=ops[]
            length(qhat)==18 && length(logqhat)==18 && length(rj)==18 ||
                throw(ArgumentError("star K/E split expects 18-coefficient jets"))
            qhat_box isa Tuple && length(qhat_box)==2 && 0<qhat_box[1]<=qhat_box[2] && all(isfinite,qhat_box) ||
                throw(DomainError(qhat_box,"whole-box qhat range must be finite and strictly positive"))
            logqhat_box isa Tuple && length(logqhat_box)==2 && all(isfinite,logqhat_box) ||
               throw(DomainError(logqhat_box,"whole-box log(qhat) range must be finite"))
           q_upper isa Tuple && length(q_upper)==2 && 0<=q_upper[1]<=q_upper[2]<1 ||
                throw(DomainError(q_upper,"certified q upper bound must lie in [0,1)"))
            qhat_dot_box isa Tuple && qdot_box isa Tuple && logqhat_dot_box isa Tuple &&
                length(qhat_dot_box)==length(qdot_box)==length(logqhat_dot_box) &&
                length(qdot_box)==length(qhat[1][2]) &&
                all(x->x isa Tuple && length(x)==2 && x[1]<=x[2] && all(isfinite,x),qhat_dot_box) &&
                all(x->x isa Tuple && length(x)==2 && x[1]<=x[2] && all(isfinite,x),qdot_box) &&
                all(x->x isa Tuple && length(x)==2 && x[1]<=x[2] && all(isfinite,x),logqhat_dot_box) ||
                throw(DomainError((qhat_dot_box,qdot_box,logqhat_dot_box),"full-box directional qhat/q/log(qhat) ranges are required"))
            max_terms isa Integer && 1<=max_terms<=4096 ||
                throw(ArgumentError("invalid DLMF term cap"))
            tail_target>0 && isfinite(tail_target) || throw(ArgumentError("invalid absolute tail target"))
            # q = r^2*qhat. The logarithmic lane multiplies log(r); its
            # analytic companion uses log(1/qhat), which remains finite at r=0.
            q=jm(jm(rj,rj),qhat)
            L=jn(logqhat)
            L=[dmul(dc(exact(BigFloat(1)/2)),v) for v in L]
            zerojet=fill(zdual,18); K_a=copy(zerojet);K_l=copy(zerojet)
            E_a=copy(zerojet);E_l=copy(zerojet);E_a[1]=dc(exact(1))
            E_l_over_r=copy(zerojet);E_l_over_r2=copy(zerojet)
            i_mul(a,b)=begin
                charge!(4);(minimum(down(()->x*y) for x in a for y in b),
                    maximum(up(()->x*y) for x in a for y in b))
            end
            i_add(a,b)=begin charge!(2);(down(()->a[1]+b[1]),up(()->a[2]+b[2])) end
            i_sub(a,b)=i_add(a,(-b[2],-b[1]))
