            majorant_add(a,b)=begin
                (a>=0 && b>=0) || throw(DomainError((a,b),"positive tail-majorant add required"))
                iszero(a) ? b : iszero(b) ? a : (charge!();up(()->a+b))
            end
            down_sub(a,b)=(charge!();down(()->a-b))
            up_sub(a,b)=(charge!();up(()->a-b))
            up_mul(a,b)=begin
                (a>=0 && b>=0) || throw(DomainError((a,b),"positive tail-majorant multiply required"))
                iszero(a) || iszero(b) ? BigFloat(0) : (charge!();up(()->a*b))
