                    UMref=reference_poly_pow(U,M);UMm1ref=reference_poly_pow(U,M-1)
                    S0ref=reference_poly_mul(UMref,Vref)
                    S1ref=reference_poly_add(reference_poly_scale(reference_poly_mul(UMm1ref,Vref),BigFloat(M)),
                        reference_poly_mul(UMref,reference_poly_mul(Vref,Vref)))
                    exact_match=Vref==V && UMref==UM && UMm1ref==UMm1 && S0ref==S0 && S1ref==S1
                    exact_match || throw(DomainError((M,exact_match),"cached tail coefficients disagree with dense baseline"))
                    tail_baseline_equivalence[]=(schema=:actual_q_jet_tail_majorant_dense_baseline_equivalence_v1,
                        sampled_M=M,exact_BigFloat_coefficient_match=true,
                        compared=(:V,:U_power_M,:U_power_M_minus_1,:S0,:S1),
                        baseline_interval_operations=ops[]-baseline_start,
                        finite_difference_is_separate_diagnostic=true)
