                Elog=poly_scale(US0,BigFloat(1)/2)
                Eanalytic=poly_mul(Elog,Lplus)
                qhat_abs=abs_jet_coefficients(qhat);r_abs=abs_jet_coefficients(rj)
                Eover2=poly_scale(poly_mul(qhat_abs,S0),BigFloat(1)/2)
                Eover=poly_mul(r_abs,Eover2)
                directional=ntuple(l->begin
                    Qdot=abs_jet_coefficients(q,l);Ldot=abs_jet_coefficients(L,l)
                    Qhatdot=abs_jet_coefficients(qhat,l);Rdot=abs_jet_coefficients(rj,l)
                    Klogdot=poly_mul(S1,Qdot)
                    Kandot=poly_add(poly_mul(Klogdot,Lplus),poly_mul(S0,Ldot))
                    Elogdot=poly_scale(poly_mul(poly_add(US1,S0),Qdot),BigFloat(1)/2)
                    Eandot=poly_add(poly_mul(Elogdot,Lplus),poly_scale(poly_mul(US0,Ldot),BigFloat(1)/2))
                    Eover2dot=poly_scale(poly_add(poly_mul(Qhatdot,S0),poly_mul(qhat_abs,poly_mul(S1,Qdot))),BigFloat(1)/2)
                    Eoverdot=poly_add(poly_mul(Rdot,Eover2),poly_mul(r_abs,Eover2dot))
                    (K_analytic=Kandot,K_log_r=Klogdot,E_analytic=Eandot,E_log_r=Elogdot,
                     E_log_r_over_r2=Eover2dot,E_log_r_over_r=Eoverdot)
                end,lane_count)
                (K_analytic=Kanalytic,K_log_r=Klog,E_analytic=Eanalytic,E_log_r=Elog,
                    E_log_r_over_r=Eover,E_log_r_over_r2=Eover2,directional=directional)
            end
            function j_add_tails(jet,tail,taildot)
                ntuple(n->begin
                    v=jet[n][1];d=jet[n][2]
                    ((down_sub(v[1],tail[n]),up_add(v[2],tail[n])),
                     ntuple(l->(down_sub(d[l][1],taildot[l][n]),up_add(d[l][2],taildot[l][n])),lane_count))
                end,18)
            end
            function pow_up(a,n)
                v=BigFloat(1)
                for _ in 1:n;v=up_mul(v,a);end
                v
            end
            function pow_down(a,n)
                v=BigFloat(1)
                for _ in 1:n;charge!();v=down(()->v*a);end
                v
            end
            rat(a,b)=i_div(exact(a),exact(b))
            c=exact(1);e=rat(1,2)
            charge!();log2I=(down(()->log(BigFloat(2))),up(()->log(BigFloat(2))))
            d=i_mul(exact(2),log2I)
            qm=jc(dc(exact(1)))
            qhat_pow=jc(dc(exact(1)));r2_pow=jc(dc(exact(1)));r2=jm(rj,rj)
            qhat_log_abs=max(abs(logqhat_box[1]),abs(logqhat_box[2]))
            charge!();Lbound=up(()->qhat_log_abs/2)
            qmax=max(abs(q[1][1][1]),abs(q[1][1][2]))
            0<qmax<1 || throw(DomainError(qmax,"actual q jet does not prove 0<q<1"))
            rmax=max(abs(rj[1][1][1]),abs(rj[1][1][2]))
            valid_interval(v)=v isa Tuple && length(v)==2 &&
                all(x->x isa BigFloat && isfinite(x),v) && v[1]<=v[2]
            valid_dual(v)=v isa Tuple && length(v)==2 && valid_interval(v[1]) &&
                v[2] isa Tuple && length(v[2])==lane_count && all(valid_interval,v[2])
            function assert_jet_shape(jet,name)
                (jet isa Tuple || jet isa AbstractVector) && length(jet)==18 && all(valid_dual,jet) ||
                    throw(DomainError((name,typeof(jet)),"star series operand is not an 18-coefficient dual interval jet"))
                jet
            end
            tailK=BigFloat(Inf);tailKl=BigFloat(Inf);tailE=BigFloat(Inf);tailEl=BigFloat(Inf)
            coefficient_tails=nothing
            coefficient_tail_max=BigFloat(Inf)
            used=0
            # Keep an outer, fail-closed binding for the post-loop result.
            directional_tail_bounds=ntuple(_->(K_analytic=BigFloat(Inf),K_log_r=BigFloat(Inf),
                E_analytic=BigFloat(Inf),E_log_r=BigFloat(Inf)),length(qdot_box))
            for m=0:max_terms-1
                # K: c_m q^m (L+d_m) and signed coefficient -c_m q^m.
                assert_jet_shape(qm,:q_power);assert_jet_shape(L,:log_qhat)
                assert_jet_shape(r2_pow,:r2_power);assert_jet_shape(qhat_pow,:qhat_power)
                kd=jc(dc(d)); termK=jm(jc(dc(c)),jm(qm,ja(L,kd)))
                termKl=jm(jc(dc((-c[2],-c[1]))),qm)
                K_a=ja(K_a,termK);K_l=ja(K_l,termKl)
                # E: e_m q^(m+1) (L+d_m-1/((2m+1)(2m+2))).
                qnext=jm(qm,q)
                assert_jet_shape(qnext,:q_next_power)
                ec=i_div(exact(1),exact((2m+1)*(2m+2)))
                ed=i_sub(d,ec)
                E_a=ja(E_a,jm(jc(dc(e)),jm(qnext,ja(L,jc(dc(ed))))))
                E_l=ja(E_l,jm(jc(dc((-e[2],-e[1]))),qnext))
                E_l_over_r2=ja(E_l_over_r2,jm(jc(dc((-e[2],-e[1]))),jm(r2_pow,jm(qhat_pow,qhat))))
                E_l_over_r=ja(E_l_over_r,jm(rj,jm(jc(dc((-e[2],-e[1]))),jm(r2_pow,jm(qhat_pow,qhat)))))
                used=m+1
                coefficient_tails=coefficient_tail_majorants(used)
                coefficient_tail_max=max(maximum(coefficient_tails.K_analytic),maximum(coefficient_tails.K_log_r),
                    maximum(coefficient_tails.E_analytic),maximum(coefficient_tails.E_log_r),
                    maximum(coefficient_tails.E_log_r_over_r),maximum(coefficient_tails.E_log_r_over_r2),
                    maximum(maximum(v) for x in coefficient_tails.directional for v in values(x)))
                # c_m<=1, e_m<=1/2, 0<=d_m<=2log(2); bound the omitted
                # value tails by a geometric majorant for every q<=qmax.
                one_minus_q=down_sub(BigFloat(1),BigFloat(qmax))
                one_minus_q>0 || throw(DomainError(one_minus_q,"q upper bound rounded to one"))
                den=up_div(BigFloat(1),one_minus_q)
                qpow=pow_up(BigFloat(qmax),used)
                qpowE=pow_up(BigFloat(qmax),used+1)
                charge!();log2upper=up(()->log(BigFloat(2)))
                Lplus=up_add(Lbound,up_mul(BigFloat(2),log2upper))
                LplusE=up_add(Lplus,BigFloat(1)/2)
                tailK=up_mul(up_mul(qpow,den),Lplus)
                tailKl=up_mul(qpow,den)
                tailE=up_div(up_mul(up_mul(BigFloat(1)/2,qpowE),up_mul(den,LplusE)),BigFloat(1))
                tailEl=up_mul(up_mul(BigFloat(1)/2,qpowE),den)
                geom0(Q,p)=begin
                    om=down_sub(BigFloat(1),BigFloat(Q));om>0 || throw(DomainError(om,"geometric denominator"))
                    up_div(pow_up(BigFloat(Q),p),om)
                end
                geom1(Q,p)=begin
                    om=down_sub(BigFloat(1),BigFloat(Q));om>0 || throw(DomainError(om,"geometric denominator"))
                    den2=pow_down(om,2)
                    qpower=pow_up(BigFloat(Q),p-1)
                    subtrahend=down_mul(BigFloat(p-1),BigFloat(Q))
                    numerator=up_sub(BigFloat(p),subtrahend)
                    up_div(up_mul(qpower,numerator),den2)
                end
                directional_tail_bounds=ntuple(l->begin
                    qhatdot=max(abs(qhat_dot_box[l][1]),abs(qhat_dot_box[l][2]))
                    qdot_from_qhat=up_mul(up_mul(rmax,rmax),qhatdot)
                    qdot=max(qdot_from_qhat,max(abs(qdot_box[l][1]),abs(qdot_box[l][2])))
                    ldot=up_div(max(abs(logqhat_dot_box[l][1]),abs(logqhat_dot_box[l][2])),BigFloat(2))
                    g0=geom0(qmax,used);g1=geom1(qmax,used)
                    g0e=geom0(qmax,used+1);g1e=geom1(qmax,used+1)
                    ka=up_add(up_mul(up_mul(qdot,g1),Lplus),up_mul(ldot,g0))
                    ea=up_div(up_add(up_mul(up_mul(qdot,g1e),LplusE),up_mul(ldot,g0e)),BigFloat(2))
                    (K_analytic=ka,K_log_r=up_mul(qdot,g1),
                     E_analytic=ea,E_log_r=up_div(up_mul(qdot,g1e),BigFloat(2)))
                end,length(qdot_box))
                if max(tailK,tailKl,tailE,tailEl,maximum(maximum(values(x)) for x in directional_tail_bounds),
                    coefficient_tail_max)<=tail_target;break;end
                # DLMF recurrences, with interval enclosures for scalar constants.
                cr=rat(2m+1,2m+2);c=i_mul(c,i_mul(cr,cr))
                e_series_ratio=i_div(i_mul(rat(2m+1,2),rat(2m+3,2)),i_mul(rat(m+2,1),rat(m+1,1)))
                e=i_mul(e,e_series_ratio)
                d=i_sub(d,i_mul(exact(2),rat(1,(2m+1)*(2m+2))))
                qm=jm(qm,q)
                qhat_pow=jm(qhat_pow,qhat);r2_pow=jm(r2_pow,r2)
            end
            bounded=max(tailK,tailKl,tailE,tailEl,maximum(maximum(values(x)) for x in directional_tail_bounds),
                coefficient_tail_max)<=tail_target
            # Enclose omitted terms separately at all 18 coefficients and in every
            # state lane before these jets reach the real weighted-star fj algebra.
            K_a=j_add_tails(K_a,coefficient_tails.K_analytic,ntuple(l->coefficient_tails.directional[l].K_analytic,lane_count))
            K_l=j_add_tails(K_l,coefficient_tails.K_log_r,ntuple(l->coefficient_tails.directional[l].K_log_r,lane_count))
            E_a=j_add_tails(E_a,coefficient_tails.E_analytic,ntuple(l->coefficient_tails.directional[l].E_analytic,lane_count))
            E_l=j_add_tails(E_l,coefficient_tails.E_log_r,ntuple(l->coefficient_tails.directional[l].E_log_r,lane_count))
            E_l_over_r2=j_add_tails(E_l_over_r2,coefficient_tails.E_log_r_over_r2,
                ntuple(l->coefficient_tails.directional[l].E_log_r_over_r2,lane_count))
            E_l_over_r=j_add_tails(E_l_over_r,coefficient_tails.E_log_r_over_r,
                ntuple(l->coefficient_tails.directional[l].E_log_r_over_r,lane_count))
            (status=bounded ? :evaluated_star_ke_log_split_jet : :typed_absent,
                reason=bounded ? :none : :absolute_series_tail_target_not_met,
                K_analytic=K_a,K_log_r=K_l,E_analytic=E_a,E_log_r=E_l,
                E_log_r_over_r=E_l_over_r,E_log_r_over_r2=E_l_over_r2,
                terms_used=used,qhat_box=qhat_box,logqhat_box=logqhat_box,q_upper=q_upper,
                coefficient_tail_bounds=coefficient_tails,
                tail_value_bounds=(K_analytic=tailK,K_log_r=tailKl,
                    E_analytic=tailE,E_log_r=tailEl),
                directional_tail_bounds=directional_tail_bounds,
                directional_tail_reason=:directed_geometric_majorant_over_full_box,
                interval_operations_delta=ops[]-op_origin,
                shared_interval_operations=ops[],operation_cap=max_interval_ops,
                tail_cost_profile=(poly_mul_calls=poly_profile[:mul_calls],
                    exact_zero_product_skips=poly_profile[:zero_product_skips],
                    exact_zero_sum_skips=poly_profile[:zero_sum_skips],
                    cached_power_updates=tail_cache_profile[:power_updates],
                    cached_S0_updates=tail_cache_profile[:S0_updates],
                    fixed_setup_interval_operations=tail_cache_setup_ops,
                    comparison=tail_baseline_equivalence[]),
                coefficient_convention="f(r)=analytic(r)+log(r)*signed_log_coefficient(r)",
                q_definition=:r_squared_times_qhat)
        end
        # Whole-box range provider for the target-rooted star chart. rho and D are
        # dual Taylor jets formed from the mapped child-edge vectors and affine
        # source map; their zeroth coefficients enclose the complete (r,u) box.
        # Since r is dimensionless and rho,D both have units m^2, qhat is unitless.
        # Keep the captured Float64 geometry target distinct from the local
        # `target=chart.T` dual-jet keyword below; the chord proof binds the raw input.
        raw_target_geometry=target
        function star_qhat_fullbox_ranges(rho,D,rj;anchor=chart.P,target=chart.T)
            all(k->anchor[k][1]==target[k][1] && anchor[k][2]==target[k][2],1:2) ||
                throw(DomainError((anchor,target),"star target value/velocity must equal the affine apex before differentiating"))
            qhat=jd(rho,D)
            qhat_box=qhat[1][1]
            chord_proof=nothing
            if qhat_box[1]<=0 && all(x->x isa Float64 && isfinite(x),raw_target_geometry) &&
                    all(p->all(x->x isa Float64 && isfinite(x),p),parent) &&
                    all(w->all(x->x isa Float64 && isfinite(x),w),weights)
                # Exact binary-rational minimum distance from the target to the
                # finite affine chord. Reserve conversions, all branch arithmetic,
                # one directed lower conversion, and margin before rational work.
                chord_key=(:ccp_q1_lcfs_star_chord_segment_min_rho2_lower_v2,
                    freeze_geometry_key(raw_target_geometry),freeze_geometry_key(parent),freeze_geometry_key(weights))
                chord_proof=get!(geometry_cache,chord_key) do
                    ops[]<=max_interval_ops-80 && ops[]<=typemax(Int)-80 ||
                        throw(OverflowError("star chord-segment interval-operation budget exceeded"))
                    charge!(80)
                    rat_endpoint(x)=rationalize(BigInt,x;tol=0)
                    rational_weights=ntuple(i->ntuple(j->rat_endpoint(weights[i][j]),3),3)
                    rational_parent=ntuple(j->ntuple(k->rat_endpoint(parent[j][k]),2),3)
                    chart_point(i,k)=sum(rational_weights[i][j]*rational_parent[j][k] for j in 1:3)
                    pR=chart_point(1,1);pZ=chart_point(1,2)
                    aR=chart_point(2,1)-pR;aZ=chart_point(2,2)-pZ
                    bR=chart_point(3,1)-pR;bZ=chart_point(3,2)-pZ
                    dR=bR-aR;dZ=bZ-aZ
                    chord_length2=dR^2+dZ^2
                    chord_length2>0 || throw(DomainError(chord_length2,"positive-q affine chord segment is degenerate"))
                    projection_dot=aR*dR+aZ*dZ
                    endpoint_b_test=projection_dot+chord_length2
                    segment_case=projection_dot>=0 ? :endpoint_a : endpoint_b_test<=0 ? :endpoint_b : :interior
                    segment_min2=segment_case===:endpoint_a ? aR^2+aZ^2 :
                        segment_case===:endpoint_b ? bR^2+bZ^2 :
                        begin
                            chord_cross=aR*bZ-aZ*bR
                            chord_cross^2/chord_length2
                        end
                    segment_min2>0 || throw(DomainError((segment_case,segment_min2),"target intersects affine chord segment"))
                    (rho2_lower=down(()->BigFloat(segment_min2)),
                     source=:exact_binary_rational_affine_chord_segment_min,units=:m2,
                     closest_point_case=segment_case)
                end
                chord_proof isa NamedTuple && propertynames(chord_proof)==(:rho2_lower,:source,:units,:closest_point_case) &&
                    chord_proof.source===:exact_binary_rational_affine_chord_segment_min &&
                    chord_proof.closest_point_case in (:endpoint_a,:endpoint_b,:interior) &&
                    chord_proof.units===:m2 && chord_proof.rho2_lower isa BigFloat &&
                    isfinite(chord_proof.rho2_lower) && chord_proof.rho2_lower>0 ||
                    throw(DomainError(chord_proof,"cached affine chord segment proof is malformed"))
                rho_box=rho[1][1]
                rho_box[1]<=rho_box[2] && chord_proof.rho2_lower<=rho_box[2] ||
                    throw(DomainError((chord_proof,rho_box),"chord lower bound exceeds the enclosed rho upper bound"))
                # The same exact affine-chord separation bounds rho itself,
                # which later field quotients invert independently of qhat.
                # Tighten only the primal value; preserve dual lanes and higher
                # Taylor coefficients from the natural jet enclosure.
                rho_value=(max(rho_box[1],chord_proof.rho2_lower),rho_box[2])
                rho[1]=(rho_value,rho[1][2])
                D_box=D[1][1]
                D_box[1]>0 && D_box[1]<=D_box[2] && isfinite(D_box[2]) ||
                    throw(DomainError(D_box,"positive-q denominator lacks a finite positive upper bound"))
                ops[]<=max_interval_ops-1 && ops[]<typemax(Int) ||
                    throw(OverflowError("star normalized chord-bound operation cap exceeded"))
                charge!()
                qhat_chord_lower=down(()->chord_proof.rho2_lower/D_box[2])
                isfinite(qhat_chord_lower) && qhat_chord_lower>0 ||
                    throw(DomainError((chord_proof,D_box),"normalized chord lower bound is not finite and positive"))
                qhat_lower=max(qhat_box[1],qhat_chord_lower)
                qhat_lower<=qhat_box[2] ||
                    throw(DomainError((qhat_lower,qhat_box[2]),"normalized chord lower bound exceeds qhat upper bound"))
                qhat_box=(qhat_lower,qhat_box[2])
                # Tighten only the primal value range; keep the complete
                # directional derivative interval and every higher Taylor term.
                qhat[1]=(qhat_box,qhat[1][2])
            end
            qhat_box[1]>0 && all(isfinite,qhat_box) ||
                throw(DomainError(qhat_box,"full-box qhat lacks a finite positive lower bound"))
            logqhat=jl(qhat)
            logqhat_box=logqhat[1][1]
            all(isfinite,logqhat_box) ||
                throw(DomainError(logqhat_box,"full-box log(qhat) is unresolved"))
            q=jm(jm(rj,rj),qhat)
            q_box=q[1][1]
            0<q_box[1]<=q_box[2]<1 && all(isfinite,q_box) ||
                throw(DomainError(q_box,"full-box q=r^2*qhat must be strictly positive and below one"))
            qhat_dot_box=qhat[1][2]
            qdot_box=q[1][2]
            logqhat_dot_box=logqhat[1][2]
            length(qhat_dot_box)==lane_count && length(qdot_box)==lane_count && length(logqhat_dot_box)==lane_count &&
                all(finite_interval,qhat_dot_box) && all(finite_interval,qdot_box) && all(finite_interval,logqhat_dot_box) ||
                throw(DomainError((qhat_dot_box,qdot_box,logqhat_dot_box),"full-box directional qhat/q/log(qhat) ranges are incomplete"))
            (status=:evaluated_star_qhat_fullbox_ranges,
                qhat=qhat,logqhat=logqhat,q=q,
                qhat_box=qhat_box,logqhat_box=logqhat_box,q_upper=q_box,
                qhat_dot_box=qhat_dot_box,qdot_box=qdot_box,logqhat_dot_box=logqhat_dot_box,
                rho_box=rho[1][1],D_box=D[1][1],
                rho2_chord_support_lower=chord_proof===nothing ? :typed_absent : chord_proof.rho2_lower,
                qhat_chord_support_lower=chord_proof===nothing ? :typed_absent : qhat_chord_lower,
                chord_support_units=chord_proof===nothing ? :typed_absent : chord_proof.units,
                chord_support_case=chord_proof===nothing ? :typed_absent : chord_proof.closest_point_case,
                geometry_source=:affine_parent_vertices_to_target_rooted_child_chart,
                motion_source=:dtarget_and_dparent_vertices_through_existing_dual_map,
                dimensionless_q_definition=:r_squared_times_rho_over_D)
        end
        peano=up(()->BigFloat(factorial(big(8))^4)/(BigFloat(17)*BigFloat(factorial(big(16))^3)))
        exact_midpoint(a,b)=begin x=(BigFloat(a)+BigFloat(b))/BigFloat(2);(x,x) end
        # Bind exact affine motion, target-rooted chart, determinant and Q1 basis.
        target_dots=ntuple(k->lane_interval(target_dot[k]),2)
        chart_key=(geometry_input_key,:target_rooted_affine_chart)
        chart=get!(geometry_cache,chart_key) do
            par=ntuple(i->ntuple(k->dinput(parent[i][k],parent_dot[i][k]),2),3)
            child=ntuple(i->ntuple(k->begin s=dc(exact(0));for j=1:3;s=dadd(s,dmul(dc(exact(weights[i][j])),par[j][k]));end;s end,2),3)
            P=child[1]
            T=ntuple(k->dinput(target[k],target_dot[k]),2)
            chart_kind===:star && !(all(k->P[k][1][1]<=BigFloat(target[k])<=P[k][1][2] &&
                all(l->P[k][2][l][1]<=target_dots[k][l][1]<=target_dots[k][l][2]<=P[k][2][l][2],1:lane_count),1:2)) &&
                throw(DomainError(P,"target/apex value or directional interval does not contain the bound target"))
            e1=(dsub(child[2][1],P[1]),dsub(child[2][2],P[2]));e2=(dsub(child[3][1],P[1]),dsub(child[3][2],P[2]))
            det=dsub(dmul(e1[1],e2[2]),dmul(e1[2],e2[1])); area=det[1][1]>0 ? det : det[1][2]<0 ? dneg(det) : throw(DomainError(det,"moving child determinant crosses zero"))
            (P=P,T=T,e1=e1,e2=e2,area=area)
        end
        geometry_tuple_only(chart) || throw(ArgumentError("shared affine geometry chart must be tuple-structured"))
        P=chart.P;T=chart.T;e1=chart.e1;e2=chart.e2;area=chart.area
        function pointcalc(rI,uI)
            # Exact point intervals plus the full invocation key share only basis-independent geometry.
            geometry_point_key=(geometry_input_key,:degree_zero_pointcalc,freeze_geometry_key(rI),freeze_geometry_key(uI))
            point_counts[haskey(geometry_cache,geometry_point_key) ? :geometry_hits : :geometry_misses]+=1
            common=get!(geometry_cache,geometry_point_key) do
                r=dc(rI);u=dc(uI);oneD=dc(exact(1))
                A=dadd(dmul(dsub(oneD,u),e1[1]),dmul(u,e2[1]))
                B=dadd(dmul(dsub(oneD,u),e1[2]),dmul(u,e2[2]))
                rA=dmul(r,A);rB=dmul(r,B);a=dadd(P[1],rA);z=dadd(P[2],rB)
                R=chart_kind===:star ? P[1] : T[1];Z=chart_kind===:star ? P[2] : T[2];dz=chart_kind===:star ? dneg(rB) : dsub(Z,z)
                rho=dadd(dmul(A,A),dmul(B,B))
                if chart_kind===:star
                    radial=dadd(dmul(dc(exact(2)),P[1]),rA);D=dadd(dmul(radial,radial),dmul(rB,rB))
                    q=ddiv(dmul(dmul(r,r),rho),D)
                else
                    dr=dsub(a,R);distance2=dadd(dmul(dr,dr),dmul(dz,dz))
                    distance2[1][1]>0 || throw(DomainError(distance2[1],"nonstar separation is not strict"))
                    D=dadd(dmul(dadd(R,a),dadd(R,a)),dmul(dz,dz));q=ddiv(distance2,D)
                end
                0<q[1][1] && q[1][2]<1 || throw(DomainError(q[1],"degree-zero point q outside (0,1)"))
                # q binds both primal geometry and its captured direction; the cache
                # may be reused only for identical elliptic arguments and controls.
                phase_mark!(:q_lq_geometry)
                point_key=(:point,chart_kind,terms,precision_bits,q[1],q[2])
                phase_mark!(:point_ke)
                cached=get(taylor_cache,point_key,nothing)
                if cached===nothing
                    point_counts[:ke_misses]+=1
                    # q thresholds choose only the first trial. Acceptance uses the
                    # existing rigorous tails; every returned K/E interval keeps its
                    # complete tail, including when the original cap is reached.
                    point_terms=chart_kind===:nonstar ? min(terms,
                        q[1][2]<=2.0^-20 ? 2 : q[1][2]<=2.0^-12 ? 4 :
                        q[1][2]<=2.0^-8 ? 8 : terms) : terms
                    ke=nothing;tail_target_met=false
                    while true
                        point_counts[:primal_evaluations]+=1
                        ke=_ccp_q1_dlmf_ke_interval(q[1];terms=point_terms,precision_bits=precision_bits,
                            interval_ops=ops,max_interval_ops=max_interval_ops)
                        ke.status===:evaluated_DLMF_K_E_interval || throw(DomainError(ke,"degree-zero point K/E absent"))
                        if chart_kind===:nonstar
                            charge!(4) # two directed products and two tail comparisons
                            tail_target_met=ke.tail_K<=down(()->BigFloat(2)^(-64)*ke.K[1]) &&
                                ke.tail_E<=down(()->BigFloat(2)^(-64)*ke.E[1])
                        end
                        (chart_kind!==:nonstar || tail_target_met || point_terms==terms) && break
                        point_terms=min(terms,max(point_terms+1,2*point_terms))
                    end
                    point_terms_histogram[point_terms]=get(point_terms_histogram,point_terms,0)+1
                    chart_kind===:nonstar &&
                        (point_counts[tail_target_met ? :tail_target_met : :tail_target_not_met_at_cap]+=1)
                    point_tail_max[]=(K=max(point_tail_max[].K,ke.tail_K),E=max(point_tail_max[].E,ke.tail_E))
                    kd=ntuple(l->begin
                        eta=divi(q[2][l],q[1])
                        point_counts[:directional_evaluations]+=1
                        d=_ccp_q1_dlmf_ke_directional_interval(q[1],eta;terms=point_terms,
                            precision_bits=precision_bits,interval_ops=ops,max_interval_ops=max_interval_ops,
                            primal_interval=ke)
                        d.status===:evaluated_DLMF_K_E_directional_interval ||
                            throw(DomainError(d,"degree-zero production K/E direction absent"))
                        d
                    end,lane_count)
                    cached=(K=(ke.K,ntuple(l->kd[l].dK_interval,lane_count)),
                        E=(ke.E,ntuple(l->kd[l].dE_interval,lane_count)));taylor_cache[point_key]=cached
                else
                    point_counts[:ke_hits]+=1
                end
                phase_mark!(:q_lq_geometry)
                K=cached.K;E=cached.E
                piI=(down(()->BigFloat(pi)),up(()->BigFloat(pi)))
                pref=ddiv(dc(exact(mu0)),dmul(dc(mul(exact(2),piI)),dsqrt(D)))
                hx=(sub(exact(bounds[2]),exact(bounds[1])),lane_sub(lane_interval(bounds_dot[2]),lane_interval(bounds_dot[1])))
                hz=(sub(exact(bounds[4]),exact(bounds[3])),lane_sub(lane_interval(bounds_dot[4]),lane_interval(bounds_dot[3])))
                xi=ddiv(dsub(a,dinput(bounds[1],bounds_dot[1])),hx)
                yy=ddiv(dsub(z,dinput(bounds[3],bounds_dot[3])),hz)
                0<=xi[1][1] && xi[1][2]<=1 && 0<=yy[1][1] && yy[1][2]<=1 ||
                    throw(DomainError((xi,yy),"degree-zero point left the bound Q1 cell"))
                if chart_kind===:star
                    N=dadd(dadd(dmul(a,a),dmul(P[1],P[1])),dmul(dz,dz))
                    M=dadd(dmul(dc(exact(2)),dmul(P[1],A)),dmul(r,dsub(dmul(A,A),dmul(B,B))))
                    br=dsub(ddiv(dmul(dmul(dmul(r,r),B),K),P[1]),ddiv(dmul(dmul(B,N),E),dmul(P[1],rho)))
                    bz=dadd(dmul(r,K),ddiv(dmul(M,E),rho))
                else
                    C=ddiv(dadd(dadd(dmul(a,a),dmul(R,R)),dmul(dz,dz)),distance2)
                    H=ddiv(dsub(dmul(dsub(a,R),dadd(a,R)),dmul(dz,dz)),distance2)
                    br=dmul(r,dmul(ddiv(dz,R),dadd(dneg(K),dmul(C,E))));bz=dmul(r,dadd(K,dmul(H,E)))
                end
                (pref=pref,br=br,bz=bz,area=area,xi=xi,yy=yy)
            end
            geometry_tuple_only(common) || throw(ArgumentError("shared degree-zero geometry must be tuple-structured"))
            ox=dsub(one,common.xi);oy=dsub(one,common.yy)
            if _weighted_q1_coefficients===nothing
                phi=basis_index==1 ? dmul(ox,oy) : basis_index==2 ? dmul(common.xi,oy) :
                    basis_index==3 ? dmul(ox,common.yy) : dmul(common.xi,common.yy)
                coeff=(exact(current),lane_interval(current_dot));density=dmul(coeff,phi)
            elseif _weighted_q1_direction_coefficients===nothing
                phi=(dmul(ox,oy),dmul(common.xi,oy),dmul(ox,common.yy),dmul(common.xi,common.yy))
                density=dc(exact(0))
                for k in 1:4
                    density=dadd(density,dmul(dc(exact(_weighted_q1_coefficients[k])),phi[k]))
                end
            else
                a0,ax,ay,axy=weighted_density_polynomial_coefficients
                density=dadd(dadd(a0,dmul(ax,common.xi)),
                    dmul(dadd(ay,dmul(axy,common.xi)),common.yy))
            end
            factor=dmul(common.area,density)
            (dmul(dmul(common.pref,factor),common.br),dmul(dmul(common.pref,factor),common.bz))
        end
        fj_operation_profile=Ref{Any}(nothing)
        function fj(axis,range_axis;at_r=nothing,at_u=nothing,radial_domain=nothing)
            fj_operation_start=ops[]
            phase_mark!(:q_lq_geometry)
            rdomain=radial_domain===nothing ? rbox : radial_domain
            length(rdomain)==2 && rbox[1]<=rdomain[1]<rdomain[2]<=rbox[2] ||
                throw(DomainError((rbox,rdomain),"star parent radial jet domain must be contained by the invocation box"))
            rr=at_r===nothing ? (axis===:r ? (range_axis ? (exact(rdomain[1])[1],exact(rdomain[2])[2]) : exact_midpoint(rdomain[1],rdomain[2])) : (exact(rdomain[1])[1],exact(rdomain[2])[2])) : at_r
            uu=at_u===nothing ? (axis===:u ? (range_axis ? (exact(ubox[1])[1],exact(ubox[2])[2]) : exact_midpoint(ubox[1],ubox[2])) : (exact(ubox[1])[1],exact(ubox[2])[2])) : at_u
            if at_r!==nothing && at_u!==nothing
                p=pointcalc(rr,uu)
                return ([p[1]],[p[2]]) # degree-zero point control; no 18-term K/E Taylor recurrence
            end
            rj=jc(dc(rr));uj=jc(dc(uu)); axis===:r && at_r===nothing && (rj[2]=dc(exact(1))); axis===:u && at_u===nothing && (uj[2]=dc(exact(1)))
            # Key covers every primal/moving-geometry input, point, axis and Taylor control;
            # basis/current coefficients are deliberately applied only after this lookup.
            geometry_point_key=(geometry_input_key,:fj_geometry,axis,range_axis,at_r===nothing,at_u===nothing,rr,uu)
            common=get!(geometry_cache,geometry_point_key) do
                A=ja(jm(js(jc(one),uj),jc(e1[1])),jm(uj,jc(e2[1]))); B=ja(jm(js(jc(one),uj),jc(e1[2])),jm(uj,jc(e2[2])))
                R=chart_kind===:star ? jc(P[1]) : jc(T[1]);Z=chart_kind===:star ? jc(P[2]) : jc(T[2])
                rrj=(axis===:r && at_r===nothing) ? rj : jc(dc(rr))
                rA=jm(rrj,A);rB=jm(rrj,B);a=ja(jc(P[1]),rA);z=ja(jc(P[2]),rB);dz=chart_kind===:star ? jn(rB) : js(Z,z)
                rho=ja(jm(A,A),jm(B,B))
                if chart_kind===:star
                    radial=ja(jc(dmul(dc(exact(2)),P[1])),rA);D=ja(jm(radial,radial),jm(rB,rB))
                    star_ranges=star_qhat_fullbox_ranges(rho,D,rrj)
                    qhat=star_ranges.qhat;lqhat=star_ranges.logqhat;q=star_ranges.q
                    star_split=star_ke_log_split_jet(qhat,lqhat,rrj,
                        star_ranges.qhat_box,star_ranges.logqhat_box,star_ranges.q_upper,
                        star_ranges.qhat_dot_box,star_ranges.qdot_box,star_ranges.logqhat_dot_box;max_terms=256,
                        baseline_compare=(radial_domain!==nothing && get(ENV,"FUSION_NEAR_TARGET_FAN_TAIL_BASELINE_PROBE","0")=="1"))
                    star_split.status===:evaluated_star_ke_log_split_jet ||
                        throw(DomainError(star_split,"whole-box star K/E split or directional tail absent"))
                    star_terms=star_split.terms_used
                    lq=jl(q) # r-box is strictly positive here; r=0 is owned by the endpoint consumer.
                else
                    dr=js(a,R);distance2=ja(jm(dr,dr),jm(dz,dz))
                    distance2[1][1][1]>0 || throw(DomainError(distance2[1][1],"nonstar Taylor separation is not strict"))
                    D=ja(jm(ja(R,a),ja(R,a)),jm(dz,dz));q=jd(distance2,D);lq=js(jl(distance2),jl(D))
                    star_split=nothing;star_ranges=nothing;star_terms=terms
                end
                0<q[1][1][1] && q[1][1][2]<1 || throw(DomainError(q[1][1],"Taylor complement outside (0,1)"))
                # The complete q/log-q dual jets bind the recurrence to this geometry,
                # tangent and axis box. Cached K/E arrays are read-only after creation.
                phase_mark!(:taylor_ke_recurrence)
                taylor_key=(:taylor,terms,star_terms,precision_bits,Tuple(q),Tuple(lq))
                cached=get(taylor_cache,taylor_key,nothing)
                if cached===nothing
                    if chart_kind===:star
                        K_analytic=star_split.K_analytic;K_log_r=star_split.K_log_r
                        E_analytic=star_split.E_analytic;E_log_r=star_split.E_log_r
                        log_r=jl(rrj)
                        K=ja(K_analytic,jm(log_r,K_log_r))
                        E=ja(E_analytic,jm(log_r,E_log_r))
                    else
                        K_analytic=nothing;K_log_r=nothing;E_analytic=nothing;E_log_r=nothing
                    ke=_ccp_q1_dlmf_ke_interval(q[1][1];terms=star_terms,precision_bits=precision_bits,interval_ops=ops,max_interval_ops=max_interval_ops)
                    ke.status===:evaluated_DLMF_K_E_interval || throw(DomainError(ke,"initial DLMF K/E interval absent"))
                    K=fill(zdual,18); E=fill(zdual,18)
                    qdot=q[1][2]; one_minus_q=sub(exact(1),q[1][1])
                    K[1]=(ke.K,ntuple(l->divi(mul(qdot[l],sub(mul(q[1][1],ke.K),ke.E)),
                        mul(exact(2),mul(q[1][1],one_minus_q))),lane_count))
                    E[1]=(ke.E,ntuple(l->divi(mul(qdot[l],sub(ke.K,ke.E)),
                        mul(exact(2),one_minus_q)),lane_count))
                    eta=fill(zdual,18);for n=0:16;eta[n+1]=dmul(dc(exact(n+1)),lq[n+2]);end
                    den2=jm(jc(dc(exact(2))),js(jc(one),q));inv2=ji(den2)
                    ek=jm(eta,inv2); eq=jm(ek,q)
                    for n=0:16
                        rk=zdual; re=zdual
                        for j=0:n
                            qk=zdual;for i=0:j;qk=dadd(qk,dmul(q[i+1],K[j-i+1]));end
                            rk=dadd(rk,dmul(ek[n-j+1],dsub(qk,E[j+1])));re=dadd(re,dmul(eq[n-j+1],dsub(K[j+1],E[j+1])))
                        end
                        K[n+2]=ddiv(rk,dc(exact(n+1)));E[n+2]=ddiv(re,dc(exact(n+1)))
                    end
                    end
                    cached=(K=K,E=E,K_analytic=K_analytic,K_log_r=K_log_r,
                        E_analytic=E_analytic,E_log_r=E_log_r,
                        star_split_status=star_split===nothing ? :not_applicable : star_split.status,
                        star_range_status=chart_kind===:star ? star_ranges.status : :not_applicable,
                        star_split_profile=star_split===nothing ? :not_applicable :
                            (interval_operations_delta=star_split.interval_operations_delta,
                             terms_used=star_split.terms_used,tail_cost_profile=star_split.tail_cost_profile))
                    star_split_profile=cached.star_split_profile
                    taylor_cache[taylor_key]=cached
                else
                    K=cached.K;E=cached.E
                    K_analytic=cached.K_analytic;K_log_r=cached.K_log_r
                    E_analytic=cached.E_analytic;E_log_r=cached.E_log_r
                    star_split_profile=cached.star_split_profile
                end
                phase_mark!(:q_lq_geometry)
                piI=(down(()->BigFloat(pi)),up(()->BigFloat(pi))); pref=jd(jc(dc(exact(mu0))),jm(jc(dc(mul(exact(2),piI))),jq(D)))
                hxv=sub(exact(bounds[2]),exact(bounds[1]));hx=(hxv,lane_sub(lane_interval(bounds_dot[2]),lane_interval(bounds_dot[1])))
                hzv=sub(exact(bounds[4]),exact(bounds[3]));hz=(hzv,lane_sub(lane_interval(bounds_dot[4]),lane_interval(bounds_dot[3])))
                xi=jd(js(a,jc(dinput(bounds[1],bounds_dot[1]))),jc(hx)); yy=jd(js(z,jc(dinput(bounds[3],bounds_dot[3]))),jc(hz))
                if chart_kind===:star
                    N=ja(ja(jm(a,a),jm(R,R)),jm(dz,dz))
                    M=ja(jm(jc(dc(exact(2))),jm(R,A)),jm(rrj,js(jm(A,A),jm(B,B))))
                    br=js(jd(jm(jm(jm(rrj,rrj),B),K),R),jd(jm(jm(B,N),E),jm(R,rho)))
                    bz=ja(jm(rrj,K),jd(jm(M,E),rho));Br_jac=br;Bz_jac=bz
                    Br_analytic=js(jd(jm(jm(jm(rrj,rrj),B),K_analytic),R),
                        jd(jm(jm(B,N),E_analytic),jm(R,rho)))
                    Br_log_r=js(jd(jm(jm(jm(rrj,rrj),B),K_log_r),R),
                        jd(jm(jm(B,N),E_log_r),jm(R,rho)))
                    Bz_analytic=ja(jm(rrj,K_analytic),jd(jm(M,E_analytic),rho))
                    Bz_log_r=ja(jm(rrj,K_log_r),jd(jm(M,E_log_r),rho))
                else
                    dr=js(a,R);distance2=ja(jm(dr,dr),jm(dz,dz))
                    C=jd(ja(ja(jm(a,a),jm(R,R)),jm(dz,dz)),distance2)
                    H=jd(js(jm(dr,ja(a,R)),jm(dz,dz)),distance2)
                    br=jm(jd(dz,R),js(jm(C,E),K));bz=ja(K,jm(H,E))
                    Br_jac=jm(rrj,br);Bz_jac=jm(rrj,bz)
                    Br_analytic=nothing;Br_log_r=nothing;Bz_analytic=nothing;Bz_log_r=nothing
                end
                pointwise=(pref=Tuple(pref),br=Tuple(Br_jac),bz=Tuple(Bz_jac),
                    br_analytic=Br_analytic===nothing ? nothing : Tuple(Br_analytic),
                    br_log_r=Br_log_r===nothing ? nothing : Tuple(Br_log_r),
                    bz_analytic=Bz_analytic===nothing ? nothing : Tuple(Bz_analytic),
                    bz_log_r=Bz_log_r===nothing ? nothing : Tuple(Bz_log_r),
                    star_qhat_bounds=chart_kind===:star ?
                        (rho_box=star_ranges.rho_box,D_box=star_ranges.D_box,qhat_box=star_ranges.qhat_box,
                         logqhat_box=star_ranges.logqhat_box,q_upper=star_ranges.q_upper,
                         qhat_dot_box=star_ranges.qhat_dot_box,qdot_box=star_ranges.qdot_box,
                         logqhat_dot_box=star_ranges.logqhat_dot_box) : :not_applicable,
                    area=area,xi=Tuple(xi),yy=Tuple(yy),star_split_profile=star_split_profile)
                _ring_edge_moment_request ? geometry_tuple_freeze(pointwise) : pointwise
            end
            if _ring_edge_moment_request
                # Shared geometry caches may already contain vector-backed jets
                # from a normal request. The edge proof consumes the same values
                # but its cache ABI is recursively immutable tuple structure.
                common=geometry_tuple_freeze(common)
                geometry_cache[geometry_point_key]=common
            end
            all(k->k===:star_split_profile || geometry_tuple_only(getproperty(common,k)),keys(common)) ||
                throw(ArgumentError("shared pointwise geometry jets must be tuple-structured"))
            if _ring_edge_moment_request
                # A pure AB-edge request asks for the canonical ring field itself.
                # For the nonstar chart, r=1 and u is the affine P1-to-P2 edge
                # parameter, so omit the triangle Jacobian and Q1 density here.
                return (jm(common.pref,common.br),jm(common.pref,common.bz),nothing,nothing,nothing,nothing)
            end
            xi=common.xi;yy=common.yy
            if _weighted_q1_coefficients===nothing
                phi=jm(js(jc(one),xi),js(jc(one),yy))
                basis_index==1 ? (phi=phi) : basis_index==2 ? (phi=jm(xi,js(jc(one),yy))) : basis_index==3 ? (phi=jm(js(jc(one),xi),yy)) : (phi=jm(xi,yy))
                coeff=(exact(current),lane_interval(current_dot));density=jm(jc(coeff),phi)
            elseif _weighted_q1_direction_coefficients===nothing
                ox=js(jc(one),xi);oy=js(jc(one),yy)
                phi=(jm(ox,oy),jm(xi,oy),jm(ox,yy),jm(xi,yy))
                density=fill(zdual,18)
                for k in 1:4
                    density=ja(density,jm(jc(dc(exact(_weighted_q1_coefficients[k]))),phi[k]))
                end
            else
                a0,ax,ay,axy=weighted_density_polynomial_coefficients
                density=ja(ja(jc(a0),jm(jc(ax),xi)),
                    jm(ja(jc(ay),jm(jc(axy),xi)),yy))
            end
            factor=jm(jc(common.area),density)
            prefactor=jm(common.pref,factor)
            fj_operation_profile[]=(axis=axis,range_axis=range_axis,radial_domain=rdomain,
                interval_operations=ops[]-fj_operation_start,star_split_profile=common.star_split_profile,
                star_qhat_bounds=common.star_qhat_bounds)
            # Preserve the 0:17 primal and dual lanes separately for exact radial log-moment contraction.
            (jm(prefactor,common.br),jm(prefactor,common.bz),
                common.br_analytic===nothing ? nothing : jm(prefactor,common.br_analytic),
                common.br_log_r===nothing ? nothing : jm(prefactor,common.br_log_r),
                common.bz_analytic===nothing ? nothing : jm(prefactor,common.bz_analytic),
                common.bz_log_r===nothing ? nothing : jm(prefactor,common.bz_log_r))
        end
        if _ring_edge_moment_request
            # For the canonical triangle chart, r=1 and u∈[0,1] parameterize
            # the complete AB edge. The center pass supplies Taylor coefficients
            # about u=1/2; the range pass supplies a uniform order-13 derivative
            # coefficient over every base point on that same edge.
            center_edge=fj(:u,false;at_r=exact(1))
            whole_edge=fj(:u,true;at_r=exact(1))
            coefficient(component,n)=begin
                v=component[n+1][1]
                v isa Tuple && length(v)==2 && all(x->x isa BigFloat && isfinite(x),v) && v[1]<=v[2] ||
                    throw(DomainError(v,"edge Taylor coefficient interval is malformed"))
                v
            end
            derivative(component)=begin
                v=component[14][1]
                v isa Tuple && length(v)==2 && all(x->x isa BigFloat && isfinite(x),v) && v[1]<=v[2] ||
                    throw(DomainError(v,"edge order-13 coefficient interval is malformed"))
                charge!(2)
                max(abs(v[1]),abs(v[2]))
            end
            edge_p1=(dadd(P[1],e1[1]),dadd(P[2],e1[2]))
            edge_p2=(dadd(P[1],e2[1]),dadd(P[2],e2[2]))
            return (schema=:ccp_canonical_ring_edge_taylor_majorant_v1,
                status=:evaluated_canonical_nonstar_AB_edge_taylor_majorant,
                edge_id=2,orientation=:P1_to_P2,center=0.5,parameter_domain=(0.0,1.0),
                coefficients_Br=ntuple(n->coefficient(center_edge[1],n),13),
                coefficients_Bz=ntuple(n->coefficient(center_edge[2],n),13),
                derivative_abs_over_factorial_Br=(order13=derivative(whole_edge[1]),),
                derivative_abs_over_factorial_Bz=(order13=derivative(whole_edge[2]),),
                interval_operation_delta=ops[]-ring_edge_request_ops_start,
                interval_operations=ops[],kernel_calls=0,new_quadrature_nodes=0,
                field_source=:canonical_ccp_ring_unit_field_RZ,
                geometry=(target=T,edge_P1=edge_p1,edge_P2=edge_p2,
                    mu0=mu0,
                    exact_edge_parameter=:r_equals_one_u_from_zero_to_one,
                    edge_field_coeff0_ranges=(Br=whole_edge[1][1],Bz=whole_edge[2][1])))
        end
        gauss_nodes,gauss_weights=_ccp_q1_green_gauss(8)
        true_gauss=qualify_gauss8_rule(gauss_nodes)
        if _q8_jacobian_probe
            # Diagnostic-only: use the same pointcalc/fj and weighted source polynomial,
            # stopping before either Taylor remainder axis (no full certificate).
            probe_lanes=[(exact(0),exact(0)) for _ in 1:lane_count]
            probe_primal=(exact(0),exact(0))
            wr=sub(exact(rbox[2]),exact(rbox[1]));wu=sub(exact(ubox[2]),exact(ubox[1]))
            for i in eachindex(gauss_nodes),j in eachindex(gauss_nodes)
                r=add(exact(rbox[1]),mul(wr,exact(gauss_nodes[i])))
                u=add(exact(ubox[1]),mul(wu,exact(gauss_nodes[j])))
                f=fj(:r,false;at_r=r,at_u=u)
                wt=mul(exact(gauss_weights[i]),exact(gauss_weights[j]))
                for l in 1:lane_count
                    probe_lanes[l]=(add(probe_lanes[l][1],mul(wt,f[1][1][2][l])),
                        add(probe_lanes[l][2],mul(wt,f[2][1][2][l])))
                end
                probe_primal=(add(probe_primal[1],mul(wt,f[1][1][1])),
                    add(probe_primal[2],mul(wt,f[2][1][1])))
            end
            scale=mul(wr,wu)
            primal=ntuple(k->mul(scale,probe_primal[k]),2)
            directional_by_lane=ntuple(l->ntuple(k->mul(scale,probe_lanes[l][k]),2),lane_count)
            return (status=:evaluated_weighted_q8_jacobian_probe_v1,
                scope=:weighted_star_chart_direct_gauss8_only_no_Taylor_certificate,
                primal_Gauss8_interval_RZ=primal,directional_Gauss8_interval_RZ=directional_by_lane[1],
                directional_Gauss8_interval_RZ_by_lane=directional_by_lane,lane_count=lane_count,
                gauss_order=8,weighted_q1_coefficients=_weighted_q1_coefficients,
                weighted_q1_direction_coefficients=weighted_q1_direction_coefficients,
                interval_operations=ops[],max_interval_operations=max_interval_ops,kernel_calls=0,
                full_certificate=false,global_closure=false,physical_validation=false)
        end
        # The positive-distance ring kernel is mu/(4pi) * N / D^(3/2),
        # D = dr^2 + dz^2 + 2R*a*x, x = 1-cos(theta).  Along either real
        # chart axis the source is affine.  At every center in the box,
        # D(s)=D0(1-alpha*s)(1-conj(alpha)*s), |alpha|=B/sqrt(D0).
        # The positive binomial convolution therefore bounds coefficient n
        # of D^(-p/2) by binomial(n+p-1,p-1)*B^n*D0^(-(n+p)/2).
        # Only the low-degree numerator polynomials are formed below.  Their
        # full geometry tangents supply Wdot*N + W*Ndot and -3/2*W*N*Ddot.
        function nonstar_ring_coefficient_bounds(axis)
            phase_mark!(:nonstar_ring_remainder)
            pc(a)=[a]
            pa(a,b)=[dadd(k<=length(a) ? a[k] : zdual,
                k<=length(b) ? b[k] : zdual) for k in 1:max(length(a),length(b))]
            pn(a)=[dneg(v) for v in a]
            ps(a,b)=pa(a,pn(b))
            function pm(a,b)
                c=fill(zdual,length(a)+length(b)-1)
                for i in eachindex(a),j in eachindex(b)
                    c[i+j-1]=dadd(c[i+j-1],dmul(a[i],b[j]))
                end
                c
            end
            pdiv(a,b)=[ddiv(v,b) for v in a]
            pvalue(a)=[v[1] for v in a]
            pdirection(a,l)=[v[2][l] for v in a]
            izero=exact(0)
            ia(a,b)=[add(k<=length(a) ? a[k] : izero,
                k<=length(b) ? b[k] : izero) for k in 1:max(length(a),length(b))]
            function im(a,b)
                c=fill(izero,length(a)+length(b)-1)
                for i in eachindex(a),j in eachindex(b)
                    c[i+j-1]=add(c[i+j-1],mul(a[i],b[j]))
                end
                c
            end
            iscale(a,b)=[mul(v,b) for v in a]
            absmax(a)=max(abs(a[1]),abs(a[2]))
            square(a)=(charge!(2);sqr(a))
            key=(geometry_input_key,:nonstar_ring_coefficient_geometry,axis)
            common=get!(geometry_cache,key) do
                rr=pc(dc((exact(rbox[1])[1],exact(rbox[2])[2])))
                uu=pc(dc((exact(ubox[1])[1],exact(ubox[2])[2])))
                axis===:r ? push!(rr,one) : push!(uu,one)
                A=pa(pm(ps(pc(one),uu),pc(e1[1])),pm(uu,pc(e2[1])))
                Bz=pa(pm(ps(pc(one),uu),pc(e1[2])),pm(uu,pc(e2[2])))
                a=pa(pc(P[1]),pm(rr,A));z=pa(pc(P[2]),pm(rr,Bz))
                R=pc(T[1]);Z=pc(T[2]);dr=ps(a,R);dz=ps(Z,z)
                # True squares are essential when one separation component
                # crosses zero; a generic interval product is not a square.
                d2=add(square(dr[1][1]),square(dz[1][1]))[1]
                a[1][1][1]>0 && R[1][1][1]>0 && d2>0 ||
                    throw(DomainError((a[1][1],R[1][1],d2),"nonstar ring separation/radii not strict"))
                qa=mul(R[1][1],a[1][1])[1]
                qa>0 || throw(DomainError(qa,"nonstar ring angular metric not positive"))
                slope_a=length(a)>1 ? a[2][1] : izero
                slope_z=length(z)>1 ? z[2][1] : izero
                B2=add(square(slope_a),square(slope_z))[2]
                charge!()
                speed=iszero(B2) ? BigFloat(0) : up(()->sqrt(B2))
                powers=fill(BigFloat(0),moment_bound_order+1);powers[1]=BigFloat(1)
                for n in 1:moment_bound_order
                    charge!();powers[n+1]=up(()->powers[n]*speed)
                end
                piI=(down(()->BigFloat(pi)),up(()->BigFloat(pi)))
                qI=exact(qa);d2I=exact(d2);rootq=sqrt_i(qI);d=sqrt_i(d2I)
                arg=divi(mul(exact(2),rootq),d)
                charge!()
                ash=(down(()->asinh(arg[1])),up(()->asinh(arg[2])))
                J=fill(BigFloat(0),moment_bound_order+5)
                # D0 >= d2 + 4*qa*theta^2/pi^2 on [-pi,pi].  J1 uses
                # that finite interval; Jm, m>=2, uses the whole real line.
                J[1]=mul(divi(piI,rootq),ash)[2]
                J[2]=divi(mul(piI,piI),mul(exact(2),mul(rootq,d)))[2]
                J[3]=divi(piI,mul(rootq,d2I))[2]
                for m in 4:moment_bound_order+5
                    J[m]=divi(mul(exact(m-3),exact(J[m-2])),mul(exact(m-2),d2I))[2]
                end
                # x^j <= D0^j/(2*qa)^j removes the angular numerator
                # without an angular quadrature or an uncounted tail.
                xfactor=fill(BigFloat(1),3)
                xfactor[2]=inv(mul(exact(2),qI))[2]
                charge!();xfactor[3]=up(()->xfactor[2]*xfactor[2])
                D0=pa(pm(dr,dr),pm(dz,dz))
                D1=pm(pc(dc(exact(2))),pm(R,a))
                hx=(sub(exact(bounds[2]),exact(bounds[1])),
                    lane_sub(lane_interval(bounds_dot[2]),lane_interval(bounds_dot[1])))
                hz=(sub(exact(bounds[4]),exact(bounds[3])),
                    lane_sub(lane_interval(bounds_dot[4]),lane_interval(bounds_dot[3])))
                xi=pdiv(ps(a,pc(dinput(bounds[1],bounds_dot[1]))),hx)
                yy=pdiv(ps(z,pc(dinput(bounds[3],bounds_dot[3]))),hz)
                pref=absmax(divi(exact(mu0),mul(exact(4),piI)))
                (a=Tuple(a),R=Tuple(R),dr=Tuple(dr),dz=Tuple(dz),r=Tuple(rr),
                    xi=Tuple(xi),yy=Tuple(yy),D0=Tuple(D0),D1=Tuple(D1),
                    J=Tuple(J),powers=Tuple(powers),xfactor=Tuple(xfactor),pref=pref,
                    distance_squared_lower=d2,axis_source_speed_upper=speed,
                    angular_radius_product_lower=qa)
            end
            geometry_tuple_only(common) || throw(ArgumentError("nonstar ring geometry must be tuple-structured"))
            # Integrate the same n=16 coefficient majorant against the ideal
            # GL8 Peano kernel while retaining radial distance dependence.
            # Geometry/knots/moments are independent of Q1 coefficients and
            # tangent lanes, so one table serves all physical contractions.
            correlated_radial = axis===:r && _weighted_q1_direction_coefficients!==nothing &&
                !_fixed_stored_q8_moment_error
            radial_distance_moments = if correlated_radial
                # Tangent lanes and current coefficients do not change these
                # scalar moments. Bind the actual injected ideal-rule intervals
                # instead, so a distinct qualified rule cannot hit this cache.
                moment_key=(:directed_peano_distance_moments_v1,precision_bits,
                    freeze_geometry_key(actual_triangle_points),freeze_geometry_key(target),
                    freeze_geometry_key(rbox),common.angular_radius_product_lower,
                    Tuple((nw.node,nw.weight) for nw in true_gauss.mapped_nodes_and_weights))
                get!(geometry_cache,moment_key) do
                    centers=Tuple((nw.node[1]+nw.node[2])/2 for nw in true_gauss.mapped_nodes_and_weights)
                    wcenters=Tuple((nw.weight[1]+nw.weight[2])/2 for nw in true_gauss.mapped_nodes_and_weights)
                    X3NonnearPeanoDistanceMoments.evaluate_enclosed(
                        actual_triangle_points[1],actual_triangle_points[2],actual_triangle_points[3],
                        target,rbox,centers,wcenters,true_gauss;
                        interval_ops=ops,max_interval_ops=max_interval_ops,
                        interval_api=(exact=exact,add=add,sub=sub,mul=mul,divi=divi,
                            sqrt_i=sqrt_i,log_i=log_i,charge! = charge!),
                        exact_ops=exact_ops,max_exact_ops=max_exact_ops,
                        shared_geometry_cache=geometry_cache,
                        qa_lower=common.angular_radius_product_lower,m_values=10:21)
                end
            else
                nothing
            end
            ox=ps(pc(one),common.xi);oy=ps(pc(one),common.yy)
            phi=if _weighted_q1_coefficients===nothing
                basis_index==1 ? pm(ox,oy) : basis_index==2 ? pm(common.xi,oy) :
                    basis_index==3 ? pm(ox,common.yy) : pm(common.xi,common.yy)
            elseif _weighted_q1_direction_coefficients===nothing
                phi_basis=(pm(ox,oy),pm(common.xi,oy),pm(ox,common.yy),pm(common.xi,common.yy))
                acc=pc(zdual)
                for k in 1:4
                    acc=pa(acc,pm(pc(dc(exact(_weighted_q1_coefficients[k]))),phi_basis[k]))
                end
                acc
            else
                a0,ax,ay,axy=weighted_density_polynomial_coefficients
                pa(pa(pc(a0),pm(pc(ax),common.xi)),
                    pm(pa(pc(ay),pm(pc(axy),common.xi)),common.yy))
            end
            coeff=(exact(current),lane_interval(current_dot))
            W=_weighted_q1_coefficients===nothing ?
                pm(pc(dmul(area,coeff)),pm(common.r,phi)) :
                pm(pc(area),pm(common.r,phi))
            nr0=pm(common.a,common.dz)
            numerators=((nr0,pn(nr0)),(pm(common.a,common.dr),pm(common.a,common.R)))
            function coefficient_upper(polys,p,n; integrated_radial=false)
                total=BigFloat(0)
                for j in eachindex(polys),k in 0:min(n,length(polys[j])-1)
                    order=n-k;angular_order=order+p-2*(j-1)
                    1<=angular_order<=moment_bound_order+5 || throw(DomainError(angular_order,"ring angular moment outside proved range"))
                    magnitude=absmax(polys[j][k+1])
                    charge!(6)
                    angular_moment = integrated_radial ?
                        radial_distance_moments.positive_distance_moments[angular_order][2] : common.J[angular_order]
                    total=up(()->total+magnitude*BigFloat(binomial(order+p-1,p-1))*
                        common.powers[order+1]*common.xfactor[j]*angular_moment)
                end
                charge!();up(()->common.pref*total)
            end
            out=ntuple(c->begin
                P3=(pm(W,numerators[c][1]),pm(W,numerators[c][2]))
                E3=map(pvalue,P3)
                G3=ntuple(l->map(p->pdirection(p,l),P3),lane_count)
                G5=ntuple(l->begin
                    d0=pdirection(common.D0,l);d1=pdirection(common.D1,l)
                    v=(im(E3[1],d0),ia(im(E3[1],d1),im(E3[2],d0)),im(E3[2],d1))
                    map(p->iscale(p,exact(-1.5)),v)
                end,lane_count)
                # Keep the complete weighted directional numerator signed.
                # With x=1-cos(theta), P3 and D each have two angular
                # coefficients.  Combine P3dot*D - (3/2)*P3*Ddot before
                # taking an absolute coefficient bound over D^(5/2).
                # im convolves source-axis coefficients; the three outer
                # entries below are the distinct angular x coefficients.
                joint_G5=if _weighted_q1_direction_coefficients===nothing
                    nothing
                else
                    Dbase0=pvalue(common.D0);Dbase1=pvalue(common.D1)
                    ntuple(l->begin
                        g=G3[l]
                        product=(im(g[1],Dbase0),
                            ia(im(g[1],Dbase1),im(g[2],Dbase0)),
                            im(g[2],Dbase1))
                        ntuple(j->ia(product[j],G5[l][j]),3)
                    end,lane_count)
                end
                bound_degrees=_fixed_stored_q8_moment_error ? (0,1,16,17) : (0,1,16)
                degrees=ntuple(i->begin
                    n=bound_degrees[i]
                    primal=coefficient_upper(E3,3,n)
                    lanes=ntuple(l->begin
                        if joint_G5===nothing
                            g3=coefficient_upper(G3[l],3,n);g5=coefficient_upper(G5[l],5,n)
                            charge!();up(()->g3+g5)
                        else
                            coefficient_upper(joint_G5[l],5,n)
                        end
                    end,lane_count)
                    (primal,lanes)
                end,length(bound_degrees))
                if correlated_radial
                    integrated_primal=coefficient_upper(E3,3,16;integrated_radial=true)
                    integrated_lanes=ntuple(l->coefficient_upper(joint_G5[l],5,16;integrated_radial=true),lane_count)
                    (degrees...,(integrated_primal,integrated_lanes))
                else
                    degrees
                end
            end,2)
            (Br=out[1],Bz=out[2],distance_squared_lower=common.distance_squared_lower,
                axis_source_speed_upper=common.axis_source_speed_upper,
                angular_radius_product_lower=common.angular_radius_product_lower,
                correlated_radial_peano=correlated_radial,
                radial_distance_moments=radial_distance_moments)
        end
        parent_child_r_jet_containment=false;parent_child_u_jet_containment=false
        parent_child_r_center_containment=false
        parent_qhat_direction_bounds=:typed_absent
        function build_parent_star_bounds()
            chart_kind===:star || throw(ArgumentError("parent star bounds require the star chart"))
            parent_domain=(rbox[1],rbox[2]);parent_start=ops[]
            radial=fj(:r,true;radial_domain=parent_domain);radial_profile=fj_operation_profile[]
            angular=fj(:u,true;radial_domain=parent_domain);angular_profile=fj_operation_profile[]
            (schema=:star_parent_radial_jet_enclosure_v1,parent_rbox=parent_domain,
                parent_ubox=ubox,binding_key=parent_geometry_binding_key,radial=radial,angular=angular,
                interval_profile=(total_interval_operations=ops[]-parent_start,
                    radial=radial_profile,angular=angular_profile),proof=:interval_jet_domain_containment)
        end
        parent_builder_scope_ok=@isdefined(fj) && applicable(build_parent_star_bounds)
        if _parent_star_scope_preflight
            return (status=parent_builder_scope_ok ? :evaluated_star_parent_builder_scope_preflight_v1 : :typed_absent,
                reason=parent_builder_scope_ok ? :local_builder_and_fj_binding_visible : :fj_binding_not_visible,
                parent_builder_scope_ok=parent_builder_scope_ok,entry_depth=_radial_depth,
                parent_rbox=(rbox[1],rbox[2]),parent_ubox=ubox,binding_key=parent_geometry_binding_key,
                taylor_started=false,interval_operations=ops[],kernel_calls=0,
                global_closure=false,physical_validation=false)
        end
        if _parent_star_build_only
            parent_builder_scope_ok || throw(ArgumentError("parent star jet builder is not in fj lexical scope"))
            return build_parent_star_bounds()
        end
        function oneaxis(axis,width,nodes,ws)
            shared_parent=_shared_parent_star_bounds
            bound=chart_kind===:nonstar ? nonstar_ring_coefficient_bounds(axis) :
                shared_parent===nothing ? fj(axis,true) : (axis===:r ? shared_parent.radial : shared_parent.angular)
            # A parent interval jet encloses the child midpoint derivatives as
            # well as its full-box derivatives. Reusing it is conservative and
            # avoids recomputing the 18-term kernel jet in every radial child.
            center=_stored_rule_tail_preflight ? nothing : _fixed_stored_q8_moment_error ? fj(axis,false) : chart_kind===:star && axis===:r ?
                (shared_parent===nothing ? fj(:r,false) : shared_parent.radial) : nothing
            if _parent_child_jet_containment_probe && shared_parent!==nothing
                child_jet=fj(axis,true)
                child_profile=fj_operation_profile[]
                contains_iv(p,c)=p[1]<=c[1] && c[2]<=p[2]
                contains_dual(p,c)=p isa Tuple && c isa Tuple && length(p)==2 && length(c)==2 &&
                    contains_iv(p[1],c[1]) && length(p[2])==lane_count && length(c[2])==lane_count &&
                    all(l->contains_iv(p[2][l],c[2][l]),eachindex(p[2]))
                contains_jet(p,c)=(p isa Tuple || p isa AbstractVector) &&
                    (c isa Tuple || c isa AbstractVector) && length(p)==18 && length(c)==18 &&
                    all(n->contains_dual(p[n],c[n]),eachindex(p))
                contains_intervals(p,c)=length(p)==length(c) && all(n->contains_iv(p[n],c[n]),eachindex(p))
                parent_profile=axis===:r ? shared_parent.interval_profile.radial : shared_parent.interval_profile.angular
                parent_qh=parent_profile.star_qhat_bounds;child_qh=child_profile.star_qhat_bounds
                qh_scalar=(:rho_box,:D_box,:qhat_box,:logqhat_box,:q_upper)
                qh_directional=(:qhat_dot_box,:qdot_box,:logqhat_dot_box)
                all(k->contains_iv(getproperty(parent_qh,k),getproperty(child_qh,k)),qh_scalar) &&
                    all(k->contains_intervals(getproperty(parent_qh,k),getproperty(child_qh,k)),qh_directional) ||
                    throw(DomainError((axis,parent_qh,child_qh),"parent star q/qhat or state-direction bounds fail child containment"))
                length(bound)==6 && length(child_jet)==6 &&
                    all(i->contains_jet(bound[i],child_jet[i]),eachindex(bound)) ||
                    throw(DomainError((axis,bound,child_jet),"parent star six-jet tuple fails child coefficient or state-direction containment"))
                axis===:r && (parent_child_r_jet_containment=true)
                axis===:u && (parent_child_u_jet_containment=true)
                if axis===:r
                    parent_qhat_direction_bounds=parent_qh.qhat_dot_box
                    child_center=fj(:r,false)
                    child_center_qh=fj_operation_profile[].star_qhat_bounds
                    length(bound)==6 && length(child_center)==6 &&
                        all(i->contains_jet(bound[i],child_center[i]),eachindex(bound)) &&
                        all(k->contains_iv(getproperty(parent_qh,k),getproperty(child_center_qh,k)),qh_scalar) &&
                        all(k->contains_intervals(getproperty(parent_qh,k),getproperty(child_center_qh,k)),qh_directional) ||
                        throw(DomainError((bound,child_center),"parent star jet fails child-center Taylor coefficient or direction containment"))
                    parent_child_r_center_containment=true
                end
            end
            phase_mark!(:peano_stored_rule)
            absmax(x)=max(abs(x[1]),abs(x[2]))
            function interval_power(x,n)
                value=exact(1)
                for _ in 1:n;value=mul(value,x);end
                value
            end
            function log_moment_delta(n,a,b,true_rule)
                # Scale r=c+(h/2)t. The ratio-limited radial subbox gives s=h/(2c)<=1/3.
                h=sub(b,a);c=mul(add(a,b),exact(BigFloat(1)/2));half=mul(h,exact(BigFloat(1)/2))
                s=divi(half,c);s[1]>0 && s[2]<=BigFloat(1)/3 ||
                    throw(DomainError(s,"radial log-moment series requires h/(2c)<=1/3"))
                logc=log_i(c)
                scaled_poly=iseven(n) ? divi(exact(2),exact(n+1)) : exact(0)
                series=exact(0);spow=exact(1);tail=BigFloat(Inf);k=0
                while k<4096
                    k+=1;spow=mul(spow,s)
                    if iseven(n+k)
                        coefficient=divi(exact(2),exact(k*(n+k+1)))
                        isodd(k) || (coefficient=(-coefficient[2],-coefficient[1]))
                        series=add(series,mul(coefficient,spow))
                    end
                    # Charge before each directed operation; the power charge
                    # conservatively covers its repeated multiplications.
                    charge!(k+1);s_power=up(()->s[2]^(k+1))
                    charge!(1);tail_numerator=up(()->BigFloat(2)*s_power)
                    charge!(1);one_minus_s_lower=down(()->BigFloat(1)-s[2])
                    charge!(1);tail_denominator=down(()->BigFloat(k+1)*one_minus_s_lower)
                    tail_denominator>0 || throw(DomainError(tail_denominator,"log-moment tail denominator is not positive"))
                    charge!(1);tail=up(()->tail_numerator/tail_denominator)
                    tail<=eps(BigFloat(1)) && break
                end
                tail<=eps(BigFloat(1)) || throw(OverflowError("directed log-moment series did not converge at working precision"))
                charge!(2)
                series=(down(()->series[1]-tail),up(()->series[2]+tail))
                exact_integral=mul(interval_power(half,n+1),add(mul(logc,scaled_poly),series))
                q=(BigFloat(0),BigFloat(0))
                for nw in true_rule.mapped_nodes_and_weights
                    delta=mul(half,sub(mul(exact(2),nw.node),exact(1)))
                    r=add(c,delta)
                    term=mul(mul(mul(h,nw.weight),interval_power(delta,n)),log_i(r))
                    q=add(q,term)
                end
                sub(exact_integral,q)
            end
            function poly16_moment_delta(a,b,true_rule)
                h=sub(b,a);half=mul(h,exact(BigFloat(1)/2))
                exact_integral=divi(interval_power(h,17),exact(BigFloat(65536*17)))
                q=(BigFloat(0),BigFloat(0))
                for nw in true_rule.mapped_nodes_and_weights
                    delta=mul(half,sub(mul(exact(2),nw.node),exact(1)))
                    q=add(q,mul(mul(h,nw.weight),interval_power(delta,16)))
                end
                sub(exact_integral,q)
            end
            radial_moments=if chart_kind===:star && axis===:r
                a=exact(rbox[1]);b=exact(rbox[2])
                (poly16=poly16_moment_delta(a,b,true_gauss),
                 log=ntuple(n->log_moment_delta(n-1,a,b,true_gauss),17))
            else
                nothing
            end
            # Moment defects of the *stored* production rule.  Build once per
            # parameter axis, then reuse across components and tangent lanes.
            # This preserves the exact same Q8 functional, including its
            # binary64 node/weight defects, without another kernel evaluation.
            stored_rule_moments=if _fixed_stored_q8_moment_error
                all(w->w isa Float64 && isfinite(w) && w>0,ws) ||
                    throw(ArgumentError("stored Q8 remainder requires positive finite weights"))
                h=width;half=mul(h,exact(0.5))
                hp=[exact(1) for _ in 0:18]
                for n in 1:18;hp[n+1]=mul(hp[n],half);end
                qmom=[exact(0) for _ in 0:16];qabs17=exact(0)
                for i in eachindex(nodes)
                    delta=mul(h,sub(exact(nodes[i]),exact(0.5)))
                    power=exact(1);wi=exact(ws[i])
                    for n in 0:16
                        qmom[n+1]=add(qmom[n+1],mul(wi,power))
                        power=mul(power,delta)
                    end
                    qabs17=add(qabs17,mul(wi,exact(absmax(power))))
                end
                defects=ntuple(n->begin
                    k=n-1
                    integral=iseven(k) ? divi(mul(exact(2),hp[k+2]),exact(k+1)) : exact(0)
                    sub(integral,mul(h,qmom[n]))
                end,17)
                absolute_integral=divi(mul(exact(2),hp[19]),exact(18))
                remainder_mass=add(absolute_integral,mul(h,qabs17))[2]
                (defects=defects,absolute_degree17_remainder_mass_upper=remainder_mass,
                    rule=:same_stored_binary64_Gauss8,axis=axis)
            else
                nothing
            end
            if _stored_rule_tail_preflight
                mass=stored_rule_moments.absolute_degree17_remainder_mass_upper
                tail_bound(v)=begin charge!();up(()->v*mass) end
                return (status=:evaluated_stored_q8_tail_axis_preflight_v1,axis=axis,
                    primal_tail_upper_RZ=(tail_bound(bound.Br[4][1]),tail_bound(bound.Bz[4][1])),
                    directional_tail_upper_RZ_by_lane=ntuple(l->
                        (tail_bound(bound.Br[4][2][l]),tail_bound(bound.Bz[4][2][l])),lane_count),
                    degree17_coefficient_upper=(Br=bound.Br[4],Bz=bound.Bz[4]),
                    absolute_degree17_remainder_mass_upper=mass,
                    positive_distance_geometry=(distance_squared_lower=bound.distance_squared_lower,
                        axis_source_speed_upper=bound.axis_source_speed_upper,
                        angular_radius_product_lower=bound.angular_radius_product_lower),
                    interval_operations=ops[],new_center_jets=0,new_Q8_points=0,kernel_calls=0)
            end
            function star_radial_error(full,mid,lane,analytic_index,log_index)
                a=exact(rbox[1]);b=exact(rbox[2]);h=sub(b,a)
                maxlog=max(absmax(log_i(a)),absmax(log_i(b)))
                iv(field,n)=lane==0 ? field[n][1] : field[n][2][lane]
                total=BigFloat(0)
                for n in 0:16
                    cA=absmax(iv(mid[analytic_index],n+1));cL=absmax(iv(mid[log_index],n+1))
                    dA=n==16 ? absmax(radial_moments.poly16) : BigFloat(0)
                    dL=absmax(radial_moments.log[n+1])
                    charge!(4)
                    total=up(()->total+cA*dA+cL*dL)
                end
                M17A=absmax(iv(full[analytic_index],18));M17L=absmax(iv(full[log_index],18))
                charge!(4);M17=up(()->M17A+maxlog*M17L)
                radius=mul(h,exact(BigFloat(1)/2));charge!(2)
                charge!(17);radius_power=up(()->radius[2]^17)
                charge!(1);remainder_prefactor=up(()->BigFloat(2)*h[2])
                charge!(1);remainder_scaled=up(()->remainder_prefactor*radius_power)
                charge!(1);remainder=up(()->remainder_scaled*M17)
                charge!(1);moment_plus_remainder=up(()->total+remainder)
                # Degree-16 coefficient diagnostic for the split approximation.
                m16A=absmax(iv(mid[analytic_index],17));m16L=absmax(iv(mid[log_index],17))
                charge!(2);m16=up(()->m16A+maxlog*m16L)
                (ideal_exact_gauss8_error_upper=total,taylor_remainder_upper=remainder,
                    split_center_coefficients=(analytic=ntuple(n->iv(mid[analytic_index],n),17),
                        log_r=ntuple(n->iv(mid[log_index],n),17)),
                    log_moment_deltas=radial_moments.log,
                    poly16_moment_delta=radial_moments.poly16,
                    derivative_coefficient_abs_upper=(degree_16=m16,degree_17_analytic=M17A,
                        degree_17_log=M17L,max_abs_log_r=maxlog),
                    certified_error_upper=moment_plus_remainder)
            end
            function err(b,lane;mid=nothing,analytic_index=1,log_index=1,component=1)
                if _fixed_stored_q8_moment_error
                    moment_bound_at(n)=lane==0 ? b[n][1] : b[n][2][lane]
                    signed=exact(0)
                    coefficients=ntuple(n->lane==0 ? mid[component][n][1] : mid[component][n][2][lane],17)
                    for n in 1:17
                        signed=add(signed,mul(coefficients[n],stored_rule_moments.defects[n]))
                    end
                    moment_upper=absmax(signed);M17=moment_bound_at(4)
                    charge!();tail=up(()->M17*stored_rule_moments.absolute_degree17_remainder_mass_upper)
                    charge!();total=up(()->moment_upper+tail)
                    return (ideal_exact_gauss8_error_upper=moment_upper,
                        ideal_exact_gauss8_peano_upper=moment_upper,
                        legacy_ideal_field_semantics=:alias_for_signed_stored_rule_moment_defect,
                        derivative_coefficient_abs_upper=(degree_0=moment_bound_at(1),degree_1=moment_bound_at(2),degree_16=moment_bound_at(3),degree_17=M17),
                        taylor_remainder_upper=tail,split_center_coefficients=coefficients,
                        log_moment_deltas=nothing,poly16_moment_delta=stored_rule_moments.defects[17],
                        fixed_stored_rule_moment_defects=stored_rule_moments.defects,
                        signed_stored_rule_moment_interval=signed,
                        absolute_degree17_remainder_mass_upper=stored_rule_moments.absolute_degree17_remainder_mass_upper,
                        stored_rule_drift_upper=BigFloat(0),stored_rule_drift_semantics=:included_in_exact_stored_moment_defects,
                        quadrature_error_plus_stored_rule_upper=total,peano_plus_stored_rule_upper=total,
                        certified_error_upper=total,same_stored_production_Q8=true,
                        remainder_bound_method=:signed_centered_stored_rule_moments_with_degree17_tail)
                end
                if chart_kind===:star && axis===:r
                    radial=star_radial_error(b,mid,lane,analytic_index,log_index)
                    ideal_error=radial.ideal_exact_gauss8_error_upper
                    taylor_remainder=radial.taylor_remainder_upper
                    star_split_proof=(split_center_coefficients=radial.split_center_coefficients,
                        log_moment_deltas=radial.log_moment_deltas,poly16_moment_delta=radial.poly16_moment_delta)
                    coeffs=radial.derivative_coefficient_abs_upper
                    m16=coeffs.degree_16
                    M0=absmax(lane==0 ? b[1][1][1] : b[1][1][2][lane])
                    M1=absmax(lane==0 ? b[1][2][1] : b[1][2][2][lane])
                else
                    iv(n)=lane==0 ? b[n][1] : b[n][2][lane]
                    m16=chart_kind===:nonstar ? iv(3) : max(abs(iv(17)[1]),abs(iv(17)[2]))
                    if chart_kind===:nonstar && bound.correlated_radial_peano
                        # Fourth entry is the already integrated κ H^17 bound;
                        # neither the Peano constant nor H^17 is applied twice.
