                    else
                        charge!(3)
                        ideal_error=up(()->peano*width[2]^17*BigFloat(factorial(big(16)))*m16)
                    end
                    # MVT bounds drift from exact Gauss nodes/weights to the stored certified rule.
                    M0=chart_kind===:nonstar ? iv(1) : max(abs(iv(1)[1]),abs(iv(1)[2]))
                    M1=chart_kind===:nonstar ? iv(2) : max(abs(iv(2)[1]),abs(iv(2)[2]))
                    taylor_remainder=BigFloat(0)
                    coeffs=(degree_16=m16,)
                    star_split_proof=nothing
                end
                drift_mass=BigFloat(0)
                for i in eachindex(nodes)
                    nw=true_gauss.mapped_nodes_and_weights[i]
