                end
                charge!(2)
                stored_rule_drift=up(()->width[2]*drift_mass)
                charge!(2)
                certified_error=up(()->ideal_error+taylor_remainder+stored_rule_drift)
                (ideal_exact_gauss8_error_upper=ideal_error,ideal_exact_gauss8_peano_upper=ideal_error,
                    derivative_coefficient_abs_upper=(degree_0=M0,degree_1=M1,degree_16=m16,
                        split=coeffs),
                    taylor_remainder_upper=taylor_remainder,
                    split_center_coefficients=star_split_proof===nothing ? nothing : star_split_proof.split_center_coefficients,
                    log_moment_deltas=star_split_proof===nothing ? nothing : star_split_proof.log_moment_deltas,
                    poly16_moment_delta=star_split_proof===nothing ? nothing : star_split_proof.poly16_moment_delta,
                    stored_rule_drift_upper=stored_rule_drift,
                    quadrature_error_plus_stored_rule_upper=certified_error,peano_plus_stored_rule_upper=certified_error,
                    certified_error_upper=certified_error)
            end
            Br_by_lane=ntuple(l->chart_kind===:star && axis===:r ?
