            Bz_by_lane=ntuple(l->chart_kind===:star && axis===:r ?
                err(bound,l;mid=center,analytic_index=5,log_index=6) : err(bound[2],l;mid=center,component=2),lane_count)
            out=(Br=Br_by_lane[1],Bz=Bz_by_lane[1],Br_by_lane=Br_by_lane,Bz_by_lane=Bz_by_lane,
                primal_Br=chart_kind===:star && axis===:r ? err(bound,0;mid=center,analytic_index=3,log_index=4) : err(bound[1],0;mid=center,component=1),
                primal_Bz=chart_kind===:star && axis===:r ? err(bound,0;mid=center,analytic_index=5,log_index=6) : err(bound[2],0;mid=center,component=2),
                remainder_bound_method=_fixed_stored_q8_moment_error ? :signed_centered_stored_rule_moments_with_degree17_tail : chart_kind===:nonstar ? :positive_distance_ring_coefficient_bound :
                    (axis===:r ? :star_split_exact_log_moments_plus_degree17_remainder : :interval_Taylor_jet),
