        end
        wr=sub(exact(rbox[2]),exact(rbox[1]));wu=sub(exact(ubox[2]),exact(ubox[1]))
        er=oneaxis(:r,wr,gauss_nodes,gauss_weights);eu=oneaxis(:u,wu,gauss_nodes,gauss_weights)
        weight_mass=foldl(add,(exact(w) for w in gauss_weights);init=exact(0))
        if _stored_rule_tail_preflight
            charge!(6*lane_count+6)
            combined=ntuple(l->ntuple(c->up(()->wu[2]*er.directional_tail_upper_RZ_by_lane[l][c]+
                wr[2]*weight_mass[2]*eu.directional_tail_upper_RZ_by_lane[l][c]),2),lane_count)
            primal=ntuple(c->up(()->wu[2]*er.primal_tail_upper_RZ[c]+
                wr[2]*weight_mass[2]*eu.primal_tail_upper_RZ[c]),2)
            return (status=:evaluated_stored_q8_tail_preflight_v1,
                directional_degree17_tail_upper_RZ=combined[1],
                directional_degree17_tail_upper_RZ_by_lane=combined,
                primal_degree17_tail_upper_RZ=primal,
                same_stored_Q8_remainder_mass_by_axis=(r=er,u=eu),
                weighted_q1_coefficients=_weighted_q1_coefficients,
                weighted_q1_direction_coefficients=weighted_q1_direction_coefficients,
                interval_operations=ops[],max_interval_operations=max_interval_ops,
                phase_operation_counts=phase_snapshot(),new_center_jets=0,new_Q8_points=0,
                kernel_calls=0,global_closure=false,physical_validation=false)
        end
        charge!(6*lane_count)
        err_by_lane=ntuple(l->(
            up(()->wu[2]*er.Br_by_lane[l].certified_error_upper+wr[2]*weight_mass[2]*eu.Br_by_lane[l].certified_error_upper),
            up(()->wu[2]*er.Bz_by_lane[l].certified_error_upper+wr[2]*weight_mass[2]*eu.Bz_by_lane[l].certified_error_upper)),lane_count)
        err=err_by_lane[1]
        charge!(6)
