                weighted_q1_coefficients=_weighted_q1_coefficients,
                weighted_q1_direction_coefficients=weighted_q1_direction_coefficients,
                primal_taylor_error_upper_RZ=primal_err,
                directional_taylor_error_upper_RZ=err,
                directional_taylor_error_upper_RZ_by_lane=err_by_lane,directional_lane_count=lane_count,
