            r=add(exact(rbox[1]),mul(wr,exact(gauss_nodes[i])));u=add(exact(ubox[1]),mul(wu,exact(gauss_nodes[j])))
            f=fj(:r,false;at_r=r,at_u=u)
            phase_mark!(:q8)
            wt=mul(exact(gauss_weights[i]),exact(gauss_weights[j]))
            point_lanes=ntuple(l->(f[1][1][2][l],f[2][1][2][l]),lane_count)
            i==1 && j==1 && (first_point=lane_count==1 ?
                (r_interval=r,u_interval=u,directional_integrand_RZ=point_lanes[1]) :
                (r_interval=r,u_interval=u,directional_integrand_RZ=point_lanes[1],
