        end
        q8_by_lane=ntuple(l->(mul(mul(wr,wu),q8_lanes[l][1]),mul(mul(wr,wu),q8_lanes[l][2])),lane_count)
        q8=q8_by_lane[1]
        q8_primal=(mul(mul(wr,wu),q8_primal[1]),mul(mul(wr,wu),q8_primal[2]))
        enc_by_lane=ntuple(l->ntuple(k->(sub(q8_by_lane[l][k],exact(err_by_lane[l][k]))[1],
            add(q8_by_lane[l][k],exact(err_by_lane[l][k]))[2]),2),lane_count)
        enc=enc_by_lane[1]
        primal_enc=ntuple(k->(sub(q8_primal[k],exact(primal_err[k]))[1],add(q8_primal[k],exact(primal_err[k]))[2]),2)
        q8_inside_final=all(l->all(k->enc_by_lane[l][k][1]<=q8_by_lane[l][k][1] &&
            q8_by_lane[l][k][2]<=enc_by_lane[l][k][2],1:2),1:lane_count) &&
            all(k->primal_enc[k][1]<=q8_primal[k][1] && q8_primal[k][2]<=primal_enc[k][2],1:2)
        q8_inside_final || throw(DomainError((q8_by_lane,enc_by_lane,q8_primal,primal_enc),
