                (chart_kind===:star ? :one_actual_star_leaf_weighted_q1_directional_integral :
                    :one_actual_nonstar_leaf_weighted_q1_directional_integral),
            weighted_q1_coefficients=_weighted_q1_coefficients,
            weighted_q1_direction_coefficients=weighted_q1_direction_coefficients,
            directional_Gauss8_interval_RZ=q8,directional_integral_enclosure_RZ=enc,
            directional_Gauss8_interval_RZ_by_lane=q8_by_lane,
            directional_integral_enclosure_RZ_by_lane=enc_by_lane,
            primal_Gauss8_interval_RZ=q8_primal,primal_integral_enclosure_RZ=primal_enc,
