                Bz=eu.Bz.ideal_exact_gauss8_peano_upper)),gauss_order=8,taylor_degree=16,
            peano_constant=peano,full_axis_degree17_dual_coefficient_used=chart_kind===:star,
            remainder_bound_method=_fixed_stored_q8_moment_error ? :signed_centered_stored_rule_moments_with_degree17_tail : chart_kind===:nonstar ? :positive_distance_ring_coefficient_bound : :interval_Taylor_jet,
            interval_operations=ops[],max_interval_operations=max_interval_ops,
            phase_operation_counts=phase_snapshot(),kernel_calls=0,
            qualified_gauss8_rule=true_gauss,global_closure=false,physical_validation=false,
            parent_child_jet_containment=_parent_child_jet_containment_probe ?
