                 child_domain=rbox,parent_u_domain=ubox,child_u_domain=ubox,
                 radial_coefficients_and_lanes=parent_child_r_jet_containment,
                 angular_coefficients_and_lanes=parent_child_u_jet_containment,
                 radial_center_coefficients_and_lanes=parent_child_r_center_containment,
                 parent_qhat_direction_bounds=parent_qhat_direction_bounds,
                 coefficient_count=18,lane_count=lane_count,precision_bits=precision_bits) : :not_requested)
    end
    try
        lane_count in (1,4) && _radial_depth isa Integer && !(_radial_depth isa Bool) && _radial_depth in (0,1) ||
            return (status=:typed_absent,reason=:invalid_radial_subbox_recursion_depth_or_lanes,kernel_calls=0,interval_operations=ops[])
        basis_index isa Integer && !(basis_index isa Bool) && basis_index in 1:4 &&
