            0<max_interval_ops<=8_000_000 && interval_ops isa Base.RefValue &&
            interval_ops[] isa Integer && !(interval_ops[] isa Bool) &&
            0<=interval_ops[]<=max_interval_ops &&
            ((chart_kind===:nonstar && _radial_depth==1 ? 0<=rbox[1] : 0<rbox[1]) &&
                rbox[1]<rbox[2]<=1 && 0<=ubox[1]<ubox[2]<=1) ||
            return (status=:typed_absent,reason=:invalid_directional_taylor_box,kernel_calls=0,interval_operations=ops[])
        _ccp_q1_lcfs_red_leaf_points_match_parent_chart(actual_triangle_points,parent,weights) ||
            return (status=:typed_absent,reason=:actual_triangle_chart_mismatch,kernel_calls=0,interval_operations=ops[])
        if _shared_parent_star_bounds!==nothing
            pb=_shared_parent_star_bounds
            pb isa NamedTuple && pb.schema===:star_parent_radial_jet_enclosure_v1 &&
                pb.proof===:interval_jet_domain_containment && pb.parent_ubox==ubox &&
                pb.binding_key==parent_geometry_binding_key &&
                length(pb.parent_rbox)==2 && pb.parent_rbox[1]<=rbox[1]<rbox[2]<=pb.parent_rbox[2] ||
                return (status=:typed_absent,reason=:invalid_parent_star_jet_domain_binding,
                    kernel_calls=0,interval_operations=ops[])
        end
        _parent_child_jet_smoke isa Bool ||
            return (status=:typed_absent,reason=:invalid_parent_child_jet_smoke_flag,kernel_calls=0,interval_operations=ops[])
        if _parent_child_jet_smoke && _radial_depth!=0
            return (status=:typed_absent,reason=:parent_child_jet_smoke_requires_parent_depth,
                kernel_calls=0,interval_operations=ops[])
        end
        _parent_child_jet_containment_probe isa Bool ||
            return (status=:typed_absent,reason=:invalid_parent_child_containment_probe_flag,kernel_calls=0,interval_operations=ops[])
        (!_parent_child_jet_containment_probe ||
            (!_parent_child_jet_smoke && chart_kind===:star && _radial_depth==1 && _shared_parent_star_bounds!==nothing)) ||
            return (status=:typed_absent,reason=:parent_child_containment_probe_requires_child_and_parent_bound,
                kernel_calls=0,interval_operations=ops[])
        (_parent_star_build_only isa Bool && _parent_star_scope_preflight isa Bool) ||
            return (status=:typed_absent,reason=:invalid_parent_star_builder_mode,kernel_calls=0,interval_operations=ops[])
        _range0_coarse_bound isa Bool ||
            return (status=:typed_absent,reason=:invalid_range0_coarse_bound_flag,kernel_calls=0,interval_operations=ops[])
        (!_range0_coarse_bound || (chart_kind===:star && _radial_depth==0 && !_parent_child_jet_smoke &&
            !_parent_star_build_only && !_parent_star_scope_preflight)) ||
            return (status=:typed_absent,reason=:range0_coarse_bound_requires_star_parent_aggregation,
                kernel_calls=0,interval_operations=ops[])
        (!_parent_star_scope_preflight || (chart_kind===:star && _radial_depth in (0,1))) ||
            return (status=:typed_absent,reason=:scope_preflight_requires_star_depth_zero_or_one,kernel_calls=0,interval_operations=ops[])
        (!_parent_star_build_only || (chart_kind===:star && _radial_depth==1)) ||
            return (status=:typed_absent,reason=:parent_builder_only_requires_star_depth_one,kernel_calls=0,interval_operations=ops[])
        if _ring_edge_moment_request
            # The edge-only request evaluates the full AB Taylor chart directly.
