                        parent,parent_dot,weights,bounds,bounds_dot,mu0,(edges[k],edges[k+1]),ubox;
                        actual_triangle_points=actual_triangle_points,basis_index=basis_index,
                        current=current,current_dot=current_dot,
                        _weighted_q1_coefficients=_weighted_q1_coefficients,
                        _weighted_q1_direction_coefficients=_weighted_q1_direction_coefficients,
                        _fixed_stored_q8_moment_error=_fixed_stored_q8_moment_error,
                        terms=terms,precision_bits=precision_bits,
                        interval_ops=ops,max_interval_ops=max_interval_ops,
                        exact_ops=exact_ops,max_exact_ops=max_exact_ops,_radial_depth=1,
                        _true_gauss_rule=true_gauss,_shared_taylor_cache=taylor_cache,
                        _shared_geometry_cache=geometry_cache,_q8_jacobian_probe=true,
                        chart_kind=chart_kind)
                    child isa NamedTuple && get(child,:status,:typed_absent)===:evaluated_weighted_q8_jacobian_probe_v1 ||
                        throw(DomainError(child,"Q8-only radial child failed"))
                    push!(children,child)
                end
                add_iv(a,b)=begin
                    charge!(2)
                    (down(()->a[1]+b[1]),up(()->a[2]+b[2]))
                end
                sum2(field)=ntuple(c->foldl((a,x)->add_iv(a,x[field][c]),children;
                    init=(BigFloat(0),BigFloat(0))),2)
                sum_lanes(field)=ntuple(l->ntuple(c->foldl((a,x)->add_iv(a,x[field][l][c]),children;
                    init=(BigFloat(0),BigFloat(0))),2),lane_count)
                primal=sum2(:primal_Gauss8_interval_RZ)
                directional_by_lane=sum_lanes(:directional_Gauss8_interval_RZ_by_lane)
                (status=:evaluated_weighted_q8_jacobian_probe_v1,
                    scope=:weighted_star_chart_eight_radial_piece_direct_gauss8_only_no_Taylor_certificate,
                    primal_Gauss8_interval_RZ=primal,
                    directional_Gauss8_interval_RZ=directional_by_lane[1],
                    directional_Gauss8_interval_RZ_by_lane=directional_by_lane,lane_count=lane_count,
                    gauss_order=8,radial_piece_count=8,weighted_q1_coefficients=_weighted_q1_coefficients,
                    weighted_q1_direction_coefficients=weighted_q1_direction_coefficients,
                    interval_operations=ops[],max_interval_operations=max_interval_ops,kernel_calls=0,
                    full_certificate=false,global_closure=false,physical_validation=false)
            end
        end
        if _radial_depth==0
            phase_mark!(:radial_aggregation)
            return setprecision(BigFloat,precision_bits) do
                down(f)=setrounding(BigFloat,RoundDown) do;f();end
                up(f)=setrounding(BigFloat,RoundUp) do;f();end
                charge!(n)=begin
                    n isa Integer && n>=0 && ops[]<=max_interval_ops-n ||
                        throw(OverflowError("radial subbox aggregate operation cap"))
                    ops[]+=n
                end
                charge!(24)
                rlo=BigFloat(rbox[1]);rhi=BigFloat(rbox[2])
                ratio=up(()->(rhi/rlo)^(BigFloat(1)/BigFloat(8)))
                isfinite(ratio) && ratio>1 && ratio<=2 ||
                    throw(DomainError(ratio,"eight radial subboxes do not meet the ratio-at-most-two condition"))
                edges=Vector{Float64}(undef,9);edges[1]=rbox[1];edges[9]=rbox[2]
                for k in 2:8
                    edges[k]=Float64(BigFloat(rbox[1])*(rhi/rlo)^(BigFloat(k-1)/BigFloat(8)))
                end
                all(k->edges[k]<edges[k+1],1:8) ||
                    throw(DomainError(edges,"radial subbox boundaries are not strictly increasing"))
                charge!(8)
                stored_ratio=maximum(up(()->BigFloat(edges[k+1])/BigFloat(edges[k])) for k in 1:8)
                stored_ratio<=2 || throw(DomainError(stored_ratio,"stored radial subbox ratio exceeds two"))
                shared_parent_star_bounds=if chart_kind===:star
                    parent_result=_ccp_q1_lcfs_star_leaf_directional_gauss8_taylor_box(target,target_dot,
                        parent,parent_dot,weights,bounds,bounds_dot,mu0,rbox,ubox;
                        actual_triangle_points=actual_triangle_points,basis_index=basis_index,
                        current=current,current_dot=current_dot,
                        _weighted_q1_coefficients=_weighted_q1_coefficients,
                        _weighted_q1_direction_coefficients=_weighted_q1_direction_coefficients,
                        _fixed_stored_q8_moment_error=_fixed_stored_q8_moment_error,
                        terms=terms,precision_bits=precision_bits,
                        interval_ops=ops,max_interval_ops=max_interval_ops,
                        exact_ops=exact_ops,max_exact_ops=max_exact_ops,_radial_depth=1,
                        _true_gauss_rule=nothing,_shared_taylor_cache=taylor_cache,
                        _shared_geometry_cache=geometry_cache,_shared_parent_star_bounds=nothing,
                        _parent_child_jet_smoke=false,_parent_star_build_only=true,
                        _parent_star_scope_preflight=false,chart_kind=chart_kind)
                    parent_result isa NamedTuple && get(parent_result,:schema,nothing)===:star_parent_radial_jet_enclosure_v1 ||
                        throw(DomainError(parent_result,"parent star interval-jet constructor did not return a bound certificate"))
                    parent_result
                else
                    nothing
                end
                gauss_nodes,_=_ccp_q1_green_gauss(8)
                true_gauss=qualify_gauss8_rule(gauss_nodes)
                phase_mark!(:radial_aggregation)
                children=Any[];child_starts=Int[];start=ops[]
                for k in 1:8
                    push!(child_starts,ops[])
                    child=_ccp_q1_lcfs_star_leaf_directional_gauss8_taylor_box(target,target_dot,
                        parent,parent_dot,weights,bounds,bounds_dot,mu0,(edges[k],edges[k+1]),ubox;
                        actual_triangle_points=actual_triangle_points,basis_index=basis_index,
                        current=current,current_dot=current_dot,
                        _weighted_q1_coefficients=_weighted_q1_coefficients,
                        _weighted_q1_direction_coefficients=_weighted_q1_direction_coefficients,
                        _fixed_stored_q8_moment_error=_fixed_stored_q8_moment_error,
                        terms=terms,precision_bits=precision_bits,
                        interval_ops=ops,max_interval_ops=max_interval_ops,
                        exact_ops=exact_ops,max_exact_ops=max_exact_ops,_radial_depth=1,
                        _true_gauss_rule=true_gauss,_shared_taylor_cache=taylor_cache,
                        _shared_geometry_cache=geometry_cache,
                        _shared_parent_star_bounds=shared_parent_star_bounds,
                        _parent_child_jet_smoke=false,
                        _parent_child_jet_containment_probe=_parent_child_jet_smoke,chart_kind=chart_kind)
                    child isa NamedTuple && get(child,:status,:typed_absent)===:evaluated_directional_star_gauss8_taylor_box ||
                        throw(DomainError(child,"radial child Taylor/Gauss8 enclosure failed"))
                    push!(children,child)
                    if _parent_child_jet_smoke
                        return (status=:evaluated_star_parent_child_jet_smoke_v1,
                            smoke_child=child,shared_parent_domain=shared_parent_star_bounds.parent_rbox,
                            parent_interval_profile=shared_parent_star_bounds.interval_profile,
                            completed_radial_subboxes=(k,),interval_operations=ops[],
                            max_interval_operations=max_interval_ops,kernel_calls=0,
                            global_closure=false,physical_validation=false)
                    end
                    push!(completed_child_phase_counts,(radial_subbox=k,
                        interval_operation_increment=child.interval_operations-child_starts[k],
                        phase_operation_counts=child.phase_operation_counts))
                end
                addi(a,b)=(charge!(2);(down(()->a[1]+b[1]),up(()->a[2]+b[2])))
                add_scalar(a,b)=(charge!(1);up(()->a+b))
                sum_intervals(field)=ntuple(c->foldl((a,x)->addi(a,x[field][c]),children;
                    init=(BigFloat(0),BigFloat(0))),2)
                sum_lane_intervals(field)=ntuple(l->ntuple(c->foldl((a,x)->addi(a,x[field][l][c]),children;
                    init=(BigFloat(0),BigFloat(0))),2),lane_count)
                q8_by_lane=sum_lane_intervals(:directional_Gauss8_interval_RZ_by_lane)
                child_enc_by_lane=sum_lane_intervals(:directional_integral_enclosure_RZ_by_lane)
                q8=q8_by_lane[1];child_enc_sum=child_enc_by_lane[1]
                primal_q8=sum_intervals(:primal_Gauss8_interval_RZ)
                primal_child_enc_sum=sum_intervals(:primal_integral_enclosure_RZ)
                range0_coarse_certificate=if _range0_coarse_bound
                    # This block is in the radial aggregator, outside run(); define
                    # its charged directed interval primitives locally.
                    coarse_certificate_start=ops[]
                    interval_exact(x)=begin
                        charge!(2);(down(()->BigFloat(x)),up(()->BigFloat(x)))
                    end
                    interval_sub(a,b)=begin
                        charge!(2);(down(()->a[1]-b[2]),up(()->a[2]-b[1]))
                    end
                    interval_mul(a,b)=begin
                        charge!(14) # eight directed endpoint products plus six min/max comparisons
                        lows=(down(()->a[1]*b[1]),down(()->a[1]*b[2]),
                              down(()->a[2]*b[1]),down(()->a[2]*b[2]))
                        highs=(up(()->a[1]*b[1]),up(()->a[1]*b[2]),
                               up(()->a[2]*b[1]),up(()->a[2]*b[2]))
                        (minimum(lows),maximum(highs))
                    end
                    abs_upper(iv)=begin charge!(3);max(abs(iv[1]),abs(iv[2])) end
                    difference_upper(a,b)=abs_upper(interval_sub(a,b))
                    domain_measure=interval_mul(
                        interval_sub(interval_exact(rbox[2]),interval_exact(rbox[1])),
                        interval_sub(interval_exact(ubox[2]),interval_exact(ubox[1])))
                    integrand_primal=ntuple(c->shared_parent_star_bounds.radial[c][1][1],2)
                    integrand_by_lane=ntuple(l->ntuple(c->
                        shared_parent_star_bounds.radial[c][1][2][l],2),lane_count)
                    scale_domain(iv)=interval_mul(domain_measure,iv)
                    integral_primal=ntuple(c->scale_domain(integrand_primal[c]),2)
                    integral_by_lane=ntuple(l->ntuple(c->scale_domain(integrand_by_lane[l][c]),2),lane_count)
                    error_to_exact_gauss_primal=ntuple(c->difference_upper(integral_primal[c],primal_q8[c]),2)
                    error_to_exact_gauss_by_lane=ntuple(l->ntuple(c->
                        difference_upper(integral_by_lane[l][c],q8_by_lane[l][c]),2),lane_count)
                    coarse_certificate_ops=ops[]-coarse_certificate_start
                    (schema=:star_range0_coarse_integral_certificate_v1,
                        proof=:full_parent_degree_zero_weighted_integrand_times_parameter_measure,
                        parent_rbox=(rbox[1],rbox[2]),parent_ubox=ubox,domain_measure=domain_measure,
                        integrand_primal_RZ=integrand_primal,integrand_direction_RZ_by_lane=integrand_by_lane,
                        integral_enclosure_primal_RZ=integral_primal,
                        integral_enclosure_RZ_by_lane=integral_by_lane,
                        exact_Gauss8_interval_primal_RZ=primal_q8,exact_Gauss8_interval_RZ_by_lane=q8_by_lane,
                        distance_to_exact_gauss8_center_upper_primal_RZ=error_to_exact_gauss_primal,
                        distance_to_exact_gauss8_center_upper_RZ_by_lane=error_to_exact_gauss_by_lane,
                        actual_float64_Q8_roundoff=:fixture_computes_distance_to_stored_Q8_center,
                        interval_operations=coarse_certificate_ops,
                        uses_radial_parent_field_intervals=true,
                        all_eight_child_taylor_and_Q8_calculations_completed=true,
                        child_interval_nesting_required=false)
                else
                    nothing
                end
                errors_by_lane=ntuple(l->ntuple(c->foldl((a,x)->add_scalar(a,x.directional_taylor_error_upper_RZ_by_lane[l][c]),
                    children;init=BigFloat(0)),2),lane_count)
                errors=errors_by_lane[1]
                primal_errors=ntuple(c->foldl((a,x)->add_scalar(a,x.primal_taylor_error_upper_RZ[c]),
                    children;init=BigFloat(0)),2)
                charge!(8*lane_count)
                aggregate_by_lane=ntuple(l->ntuple(c->
                    (down(()->q8_by_lane[l][c][1]-errors_by_lane[l][c]),
                     up(()->q8_by_lane[l][c][2]+errors_by_lane[l][c])),2),lane_count)
                aggregate_gauss8_remainder=aggregate_by_lane[1]
                enc_by_lane=ntuple(l->ntuple(c->(min(child_enc_by_lane[l][c][1],aggregate_by_lane[l][c][1]),
                    max(child_enc_by_lane[l][c][2],aggregate_by_lane[l][c][2])),2),lane_count)
                enc=enc_by_lane[1]
                charge!(8) # primal Gauss8 remainder endpoints; lane remainders charged above
                primal_remainder=ntuple(c->(down(()->primal_q8[c][1]-primal_errors[c]),
                    up(()->primal_q8[c][2]+primal_errors[c])),2)
                primal_enc=ntuple(c->(min(primal_child_enc_sum[c][1],primal_remainder[c][1]),
                    max(primal_child_enc_sum[c][2],primal_remainder[c][2])),2)
                all(l->all(c->enc_by_lane[l][c][1]<=child_enc_by_lane[l][c][1] &&
                    enc_by_lane[l][c][2]>=child_enc_by_lane[l][c][2] &&
                    enc_by_lane[l][c][1]<=aggregate_by_lane[l][c][1] &&
                    enc_by_lane[l][c][2]>=aggregate_by_lane[l][c][2],1:2),1:lane_count) &&
                    all(c->enc[c][1]<=child_enc_sum[c][1] && enc[c][2]>=child_enc_sum[c][2] &&
                    enc[c][1]<=aggregate_gauss8_remainder[c][1] && enc[c][2]>=aggregate_gauss8_remainder[c][2] &&
                    primal_enc[c][1]<=primal_child_enc_sum[c][1] && primal_enc[c][2]>=primal_child_enc_sum[c][2] &&
                    primal_enc[c][1]<=primal_remainder[c][1] && primal_enc[c][2]>=primal_remainder[c][2],1:2) ||
                    throw(DomainError((child_enc_sum,aggregate_gauss8_remainder,enc),
                        "radial hull misses child enclosure sum or aggregate Gauss8 remainder"))
                (status=:evaluated_directional_star_gauss8_taylor_box,
                    scope=_weighted_q1_direction_coefficients===nothing ?
                        (chart_kind===:star ? :one_actual_star_leaf_basis_directional_integral : :one_actual_nonstar_leaf_basis_directional_integral) :
                        (chart_kind===:star ? :one_actual_star_leaf_weighted_q1_directional_integral :
                            :one_actual_nonstar_leaf_weighted_q1_directional_integral),
                    weighted_q1_coefficients=_weighted_q1_coefficients,
                    weighted_q1_direction_coefficients=weighted_q1_direction_coefficients,
                    directional_Gauss8_interval_RZ=q8,directional_integral_enclosure_RZ=enc,
            directional_Gauss8_interval_RZ_by_lane=q8_by_lane,
            directional_integral_enclosure_RZ_by_lane=enc_by_lane,
                    range0_coarse_integral_certificate=range0_coarse_certificate,
                    primal_Gauss8_interval_RZ=primal_q8,primal_integral_enclosure_RZ=primal_enc,
                    primal_taylor_error_upper_RZ=primal_errors,
                    summed_child_enclosure_RZ=child_enc_sum,primal_summed_child_enclosure_RZ=primal_child_enc_sum,
                    aggregate_gauss8_plus_taylor_interval_RZ=aggregate_gauss8_remainder,
                    first_degree_zero_point_direction=children[1].first_degree_zero_point_direction,
                    directed_Gauss8_sum_contained=true,directional_taylor_error_upper_RZ=errors,
                    directional_taylor_error_upper_RZ_by_lane=errors_by_lane,directional_lane_count=lane_count,
                    radial_error_upper_RZ=Tuple(x.radial_error_upper_RZ for x in children),
                    angular_error_upper_RZ=Tuple(x.angular_error_upper_RZ for x in children),
                    radial_subbox_count=8,radial_subbox_ratio_upper=stored_ratio,
                    radial_subboxes=Tuple((rbox=(edges[k],edges[k+1]),
                        directional_integral_enclosure_RZ=children[k].directional_integral_enclosure_RZ,
                        directional_Gauss8_interval_RZ=children[k].directional_Gauss8_interval_RZ,
                        directional_Gauss8_interval_RZ_by_lane=children[k].directional_Gauss8_interval_RZ_by_lane,
                        directional_integral_enclosure_RZ_by_lane=children[k].directional_integral_enclosure_RZ_by_lane,
                        directional_taylor_error_upper_RZ=children[k].directional_taylor_error_upper_RZ,
                        directional_taylor_error_upper_RZ_by_lane=children[k].directional_taylor_error_upper_RZ_by_lane,
                        interval_operations=children[k].interval_operations,
                        interval_operation_increment=children[k].interval_operations-child_starts[k],
                        phase_operation_counts=children[k].phase_operation_counts) for k in 1:8),
                    interval_operations=ops[],radial_candidate_operation_increment=ops[]-start,
                    phase_operation_counts=phase_snapshot(),max_interval_operations=max_interval_ops,kernel_calls=0,
                    qualified_gauss8_rule=true_gauss,global_closure=false,physical_validation=false)
            end
        end
        setprecision(BigFloat,precision_bits) do;run();end
    catch err
        err isa InterruptException && rethrow()
        failure_backtrace=try
            frames=stacktrace(catch_backtrace())
            Tuple(string(frames[i].file,":",frames[i].line) for i in 1:min(8,length(frames)))
        catch
            ()
        end
        (status=:typed_absent,reason=:directional_taylor_box_failed,detail=sprint(showerror,err),
            failure_detail=err isa DomainError ? err.val : nothing,
            failure_backtrace=failure_backtrace,
            completed_child_phase_counts=Tuple(completed_child_phase_counts),phase_operation_counts=phase_snapshot(),
            kernel_calls=0,interval_operations=ops[],global_closure=false,physical_validation=false)
    end
end

include("CandidateCoupledPeanoDistanceV4.jl")
include("CandidateCoupledSignedFanNearV4.jl")
